(window.NOVA_DATA = window.NOVA_DATA || {})["physics"] = {"id": "physics", "name": "Физика", "program": "Типовая учебная программа РК (обновлённое содержание образования). Темы сверять с действующим учебником.", "classes": {"7": {"sections": [{"title": "Физика и методы научного познания", "topics": [{"id": "p7-measure", "title": "Физические величины и их измерение", "explain": "Физика изучает явления природы: механические, тепловые, электрические, световые, звуковые. Чтобы описывать явления точно, их измеряют.\nФизическая величина — то, что можно измерить: длина, время, масса, температура. Измерить — значит сравнить величину с единицей. В Международной системе (СИ) длину измеряют в метрах, массу — в килограммах, время — в секундах. Цена деления шкалы = (разность двух соседних подписанных значений) : (число делений между ними).", "formula": "Цена деления = (b − a) / n; погрешность измерения обычно равна половине цены деления", "levels": {"easy": [{"q": "Какая единица длины основная в СИ?", "o": ["метр", "сантиметр", "километр", "дюйм"], "a": 0, "e": "В Международной системе единиц основная единица длины — метр (м)."}, {"q": "Какая величина — физическая?", "o": ["температура", "радость", "цвет глаз по ощущению", "название города"], "a": 0, "e": "Физическая величина — это то, что можно измерить прибором и выразить числом с единицей."}, {"q": "Каким прибором измеряют время?", "o": ["секундомером", "термометром", "линейкой", "мензуркой"], "a": 0, "e": "Время измеряют часами и секундомером."}, {"q": "Сколько миллиметров в 1 сантиметре?", "o": ["10", "100", "1000", "0,1"], "a": 0, "e": "1 см = 10 мм."}], "medium": [{"q": "Между штрихами 20 мл и 40 мл на мензурке 10 делений. Цена деления?", "o": ["2 мл", "4 мл", "20 мл", "0,5 мл"], "a": 0, "e": "(40 − 20) / 10 = 2 мл."}, {"q": "Выразите 2,5 км в метрах.", "o": ["2500 м", "250 м", "25 000 м", "25 м"], "a": 0, "e": "1 км = 1000 м, значит 2,5 км = 2500 м."}, {"q": "Сколько секунд в 1,5 минуты?", "o": ["90 с", "150 с", "60 с", "15 с"], "a": 0, "e": "1,5 × 60 = 90 с."}, {"q": "Цена деления линейки 1 мм. Чему обычно равна погрешность измерения?", "o": ["0,5 мм", "1 мм", "2 мм", "0,1 мм"], "a": 0, "e": "Погрешность измерения обычно принимают равной половине цены деления."}], "hard": [{"q": "Толщина пачки из 200 листов — 2 см. Какова толщина одного листа?", "o": ["0,1 мм", "1 мм", "0,01 мм", "0,2 мм"], "a": 0, "e": "2 см = 20 мм; 20 мм / 200 = 0,1 мм. Это метод рядов."}, {"q": "Площадь 1 м² — сколько это квадратных сантиметров?", "o": ["10 000 см²", "100 см²", "1000 см²", "1 000 000 см²"], "a": 0, "e": "1 м = 100 см, значит 1 м² = 100 × 100 = 10 000 см²."}, {"q": "Объём 1 литр равен:", "o": ["1 дм³", "1 м³", "1 см³", "10 см³"], "a": 0, "e": "1 л = 1 дм³ = 1000 см³ = 0,001 м³."}], "olympiad": [{"q": "Длину нити намотали на карандаш: 30 плотных витков заняли 1,5 см. Диаметр нити?", "o": ["0,5 мм", "5 мм", "0,05 мм", "1,5 мм"], "a": 0, "e": "1,5 см = 15 мм; 15 / 30 = 0,5 мм — каждый виток добавляет один диаметр."}, {"q": "Объём кубика 8 см³. Чему равна длина его ребра?", "o": ["2 см", "4 см", "2,8 см", "8 см"], "a": 0, "e": "V = a³, a = ∛8 = 2 см."}, {"q": "Скорость 72 км/ч выразите в м/с.", "o": ["20 м/с", "72 м/с", "7,2 м/с", "36 м/с"], "a": 0, "e": "72 км/ч = 72 000 м / 3600 с = 20 м/с."}]}}]}, {"title": "Механическое движение", "topics": [{"id": "p7-motion", "title": "Механическое движение. Траектория, путь, перемещение", "explain": "Механическое движение — изменение положения тела относительно других тел с течением времени. Движение относительно: пассажир неподвижен относительно автобуса, но движется относительно дороги. Поэтому всегда выбирают тело отсчёта.\nТраектория — линия, по которой движется тело. Путь — длина траектории. Перемещение — отрезок от начальной точки до конечной (имеет направление).", "levels": {"easy": [{"q": "Что такое траектория?", "o": ["линия, по которой движется тело", "время движения", "скорость тела", "масса тела"], "a": 0, "e": "Траектория — линия, которую описывает тело при движении."}, {"q": "Пассажир сидит в едущем автобусе. Относительно чего он покоится?", "o": ["относительно автобуса", "относительно дороги", "относительно деревьев", "относительно встречных машин"], "a": 0, "e": "Движение и покой относительны: относительно автобуса пассажир не движется."}, {"q": "Путь — это…", "o": ["длина траектории", "кратчайшее расстояние между началом и концом", "скорость движения", "направление движения"], "a": 0, "e": "Путь — длина всей пройденной линии."}], "medium": [{"q": "Мальчик прошёл 3 км на север и вернулся обратно. Путь и перемещение?", "o": ["6 км и 0", "3 км и 3 км", "6 км и 6 км", "0 и 6 км"], "a": 0, "e": "Путь — сумма длин: 6 км; он вернулся в начало, значит перемещение 0."}, {"q": "Тело прошло 3 м на восток, затем 4 м на север. Модуль перемещения?", "o": ["5 м", "7 м", "1 м", "12 м"], "a": 0, "e": "По теореме Пифагора: √(3² + 4²) = 5 м."}, {"q": "Может ли путь быть меньше модуля перемещения?", "o": ["нет, никогда", "да, всегда", "да, при движении по кругу", "да, если тело стоит"], "a": 0, "e": "Перемещение — кратчайший путь между точками, поэтому путь всегда не меньше перемещения."}], "hard": [{"q": "Точка на ободе колеса радиусом 0,5 м сделала полный оборот. Путь и перемещение (π ≈ 3,14)?", "o": ["3,14 м и 0", "1 м и 3,14 м", "0 и 3,14 м", "3,14 м и 1 м"], "a": 0, "e": "Путь — длина окружности 2πR = 3,14 м; точка вернулась на место — перемещение 0."}, {"q": "Та же точка сделала половину оборота (R = 0,5 м). Модуль перемещения?", "o": ["1 м", "1,57 м", "0,5 м", "0"], "a": 0, "e": "За пол-оборота точка оказывается на противоположном конце диаметра: 2R = 1 м."}, {"q": "Относительно какого тела отсчёта Солнце «восходит и заходит»?", "o": ["Земли", "Солнца", "Луны", "любой звезды"], "a": 0, "e": "Видимое движение Солнца — это движение относительно вращающейся Земли."}], "olympiad": [{"q": "Два поезда едут навстречу по 60 км/ч. С какой скоростью один движется относительно другого?", "o": ["120 км/ч", "60 км/ч", "0", "30 км/ч"], "a": 0, "e": "При встречном движении скорости относительно друг друга складываются."}, {"q": "Лодка плывёт по реке вниз по течению. Относительно какого тела она может покоиться?", "o": ["относительно плывущего рядом бревна, если не гребут", "относительно берега", "относительно дна", "ни относительно чего"], "a": 0, "e": "Без гребли лодка движется вместе с водой — как и бревно рядом с ней."}, {"q": "Пчела летела 2 м на восток, 2 м на север и 2 м на запад. Модуль перемещения?", "o": ["2 м", "6 м", "0", "4 м"], "a": 0, "e": "Восток и запад компенсировали друг друга, осталось 2 м на север."}]}}, {"id": "p7-speed", "title": "Скорость. Равномерное и неравномерное движение", "explain": "Скорость показывает, какой путь тело проходит за единицу времени. При равномерном движении тело за любые равные промежутки времени проходит равные пути. Если нет — движение неравномерное, и тогда говорят о средней скорости: весь путь делят на всё время.", "formula": "v = s / t;  s = v · t;  vср = sвесь / tвсё", "levels": {"easy": [{"q": "Единица скорости в СИ?", "o": ["м/с", "км", "с", "м/с²"], "a": 0, "e": "Скорость в СИ измеряют в метрах в секунду."}, {"q": "Автомобиль проехал 100 км за 2 ч. Скорость?", "o": ["50 км/ч", "200 км/ч", "100 км/ч", "25 км/ч"], "a": 0, "e": "v = s / t = 100 / 2 = 50 км/ч."}, {"q": "Какое движение называют равномерным?", "o": ["за любые равные промежутки времени тело проходит равные пути", "скорость всё время растёт", "тело движется по кругу", "тело стоит на месте"], "a": 0, "e": "Это определение равномерного движения."}], "medium": [{"q": "Велосипедист едет со скоростью 5 м/с. Какой путь он проедет за 2 минуты?", "o": ["600 м", "10 м", "300 м", "60 м"], "a": 0, "e": "2 мин = 120 с; s = 5 × 120 = 600 м."}, {"q": "За сколько секунд звук (340 м/с) пройдёт 1,7 км?", "o": ["5 с", "0,5 с", "50 с", "2 с"], "a": 0, "e": "t = s / v = 1700 / 340 = 5 с."}, {"q": "Выразите 54 км/ч в м/с.", "o": ["15 м/с", "54 м/с", "5,4 м/с", "150 м/с"], "a": 0, "e": "54 000 м / 3600 с = 15 м/с."}], "hard": [{"q": "Первые 60 км машина ехала 1 ч, следующие 60 км — 2 ч. Средняя скорость?", "o": ["40 км/ч", "45 км/ч", "60 км/ч", "30 км/ч"], "a": 0, "e": "vср = 120 км / 3 ч = 40 км/ч. Нельзя просто усреднять скорости."}, {"q": "Половину пути тело шло со скоростью 2 м/с, половину — 6 м/с. Средняя скорость?", "o": ["3 м/с", "4 м/с", "8 м/с", "2,5 м/с"], "a": 0, "e": "Пусть половина пути s: t = s/2 + s/6 = 4s/6; vср = 2s / (4s/6) = 3 м/с."}, {"q": "Поезд длиной 200 м проезжает мост длиной 400 м за 30 с. Скорость поезда?", "o": ["20 м/с", "13,3 м/с", "6,7 м/с", "30 м/с"], "a": 0, "e": "Поезд должен пройти длину моста плюс свою длину: 600 м / 30 с = 20 м/с."}], "olympiad": [{"q": "Первую половину времени тело двигалось со скоростью 2 м/с, вторую — 6 м/с. Средняя скорость?", "o": ["4 м/с", "3 м/с", "8 м/с", "5 м/с"], "a": 0, "e": "При равных отрезках времени средняя скорость — обычное среднее: (2 + 6) / 2 = 4 м/с."}, {"q": "Эскалатор поднимает стоящего человека за 60 с, а по неподвижному эскалатору он идёт 40 с. За сколько он поднимется, идя по движущемуся?", "o": ["24 с", "50 с", "100 с", "20 с"], "a": 0, "e": "Скорости складываются: L/60 + L/40 = L/t → 1/t = 1/60 + 1/40 = 1/24, t = 24 с."}, {"q": "Гроза: вспышку увидели, а гром услышали через 6 с. Как далеко гроза (звук 340 м/с)?", "o": ["около 2 км", "около 6 км", "около 340 м", "около 20 км"], "a": 0, "e": "Свет приходит почти мгновенно; s = 340 × 6 = 2040 м ≈ 2 км."}]}}, {"id": "p7-graphs", "title": "Графики равномерного движения", "explain": "Движение удобно изображать графиками. График пути s(t) при равномерном движении — прямая, выходящая из начала координат: чем круче прямая, тем больше скорость. График скорости v(t) при равномерном движении — горизонтальная прямая. Площадь под графиком v(t) равна пройденному пути.", "formula": "s = v · t — линейная зависимость; путь = площадь под графиком v(t)", "levels": {"easy": [{"q": "Как выглядит график скорости v(t) при равномерном движении?", "o": ["горизонтальная прямая", "наклонная прямая из начала координат", "парабола", "окружность"], "a": 0, "e": "При равномерном движении скорость не меняется — линия горизонтальна."}, {"q": "График пути s(t) равномерного движения — это…", "o": ["прямая, выходящая из начала координат", "горизонтальная прямая", "волнистая линия", "точка"], "a": 0, "e": "s = v·t — линейная зависимость."}, {"q": "На графиках s(t) двух тел у первого прямая круче. Чья скорость больше?", "o": ["первого", "второго", "одинаковы", "нельзя сказать"], "a": 0, "e": "Чем круче график пути, тем больше путь за то же время, значит больше скорость."}], "medium": [{"q": "По графику s(t): за 4 с тело прошло 20 м. Скорость?", "o": ["5 м/с", "80 м/с", "20 м/с", "4 м/с"], "a": 0, "e": "v = 20 / 4 = 5 м/с."}, {"q": "По графику v(t): скорость 3 м/с в течение 10 с. Пройденный путь?", "o": ["30 м", "13 м", "3,3 м", "10 м"], "a": 0, "e": "Путь — площадь прямоугольника под графиком: 3 × 10 = 30 м."}, {"q": "График s(t) — горизонтальная линия на высоте 50 м. Что делает тело?", "o": ["стоит на месте", "движется равномерно со скоростью 50 м/с", "ускоряется", "движется назад"], "a": 0, "e": "Путь не меняется со временем, значит тело покоится."}], "hard": [{"q": "График v(t): 2 м/с первые 5 с, затем 4 м/с ещё 5 с. Весь путь?", "o": ["30 м", "20 м", "15 м", "60 м"], "a": 0, "e": "Площадь: 2·5 + 4·5 = 10 + 20 = 30 м."}, {"q": "Для того же движения (2 м/с 5 с, 4 м/с 5 с) средняя скорость?", "o": ["3 м/с", "6 м/с", "2 м/с", "4 м/с"], "a": 0, "e": "vср = 30 м / 10 с = 3 м/с."}, {"q": "Два тела выехали одновременно из одной точки со скоростями 2 и 5 м/с в одну сторону. Расстояние между ними через 10 с?", "o": ["30 м", "70 м", "50 м", "20 м"], "a": 0, "e": "Разность скоростей 3 м/с × 10 с = 30 м."}], "olympiad": [{"q": "Тело 1 стартует из x = 0 со скоростью 4 м/с, тело 2 — из x = 60 м навстречу со скоростью 2 м/с. Когда они встретятся?", "o": ["через 10 с", "через 15 с", "через 30 с", "через 6 с"], "a": 0, "e": "Скорость сближения 6 м/с; 60 / 6 = 10 с."}, {"q": "Где произойдёт встреча в предыдущей задаче?", "o": ["x = 40 м", "x = 20 м", "x = 30 м", "x = 60 м"], "a": 0, "e": "Первое тело за 10 с пройдёт 4 × 10 = 40 м."}, {"q": "Как по графику v(t) неравномерного движения найти путь?", "o": ["найти площадь фигуры под графиком", "взять последнее значение скорости", "сложить начальную и конечную скорость", "умножить наибольшую скорость на время"], "a": 0, "e": "Путь всегда равен площади под графиком скорости."}]}}]}, {"title": "Масса и плотность", "topics": [{"id": "p7-density", "title": "Масса тела. Плотность вещества", "explain": "Масса — мера инертности тела: чем больше масса, тем труднее изменить скорость тела. Массу измеряют весами, единица — килограмм.\nПлотность показывает, какая масса вещества содержится в единице объёма. У воды плотность 1000 кг/м³ (1 г/см³). Тела из одинаковых веществ, но разного объёма, имеют одинаковую плотность.", "formula": "ρ = m / V;  m = ρ · V;  V = m / ρ", "levels": {"easy": [{"q": "Единица плотности в СИ?", "o": ["кг/м³", "кг", "м³", "Н"], "a": 0, "e": "Плотность = масса / объём, значит кг/м³."}, {"q": "Плотность воды?", "o": ["1000 кг/м³", "100 кг/м³", "1 кг/м³", "7800 кг/м³"], "a": 0, "e": "Плотность пресной воды ≈ 1000 кг/м³ = 1 г/см³."}, {"q": "Каким прибором измеряют массу?", "o": ["весами", "динамометром", "мензуркой", "барометром"], "a": 0, "e": "Массу измеряют рычажными или электронными весами."}], "medium": [{"q": "Масса тела 600 г, объём 200 см³. Плотность?", "o": ["3 г/см³", "0,33 г/см³", "120 000 г/см³", "800 г/см³"], "a": 0, "e": "ρ = 600 / 200 = 3 г/см³."}, {"q": "Какова масса 2 л воды?", "o": ["2 кг", "20 кг", "0,2 кг", "2000 кг"], "a": 0, "e": "2 л = 0,002 м³; m = 1000 × 0,002 = 2 кг."}, {"q": "Плотность железа 7800 кг/м³. Масса бруска объёмом 0,01 м³?", "o": ["78 кг", "780 кг", "7,8 кг", "780 000 кг"], "a": 0, "e": "m = ρV = 7800 × 0,01 = 78 кг."}], "hard": [{"q": "Выразите 2,7 г/см³ в кг/м³.", "o": ["2700 кг/м³", "27 кг/м³", "0,0027 кг/м³", "270 кг/м³"], "a": 0, "e": "1 г/см³ = 1000 кг/м³, значит 2,7 г/см³ = 2700 кг/м³."}, {"q": "Два кубика одинаковой массы: из алюминия (2,7 г/см³) и из железа (7,8 г/см³). У какого объём больше?", "o": ["у алюминиевого", "у железного", "одинаковы", "нельзя сказать"], "a": 0, "e": "V = m / ρ: чем меньше плотность, тем больше объём при той же массе."}, {"q": "Шар объёмом 100 см³ из чугуна (7 г/см³) весит 560 г. Есть ли полость?", "o": ["да, объём полости 20 см³", "нет", "да, 80 см³", "да, 56 см³"], "a": 0, "e": "Сплошной шар весил бы 700 г. Металла: 560 / 7 = 80 см³, значит полость 100 − 80 = 20 см³."}], "olympiad": [{"q": "Смешали 1 л воды (1 г/см³) и 1 л спирта (0,8 г/см³). Плотность смеси, если объёмы складываются?", "o": ["0,9 г/см³", "1,8 г/см³", "0,8 г/см³", "1 г/см³"], "a": 0, "e": "Масса 1000 + 800 = 1800 г, объём 2000 см³; ρ = 0,9 г/см³. (На деле объём смеси чуть меньше 2 л.)"}, {"q": "Пустая бутылка весит 200 г, с водой — 700 г, с маслом — 650 г. Плотность масла?", "o": ["0,9 г/см³", "0,93 г/см³", "1,1 г/см³", "0,65 г/см³"], "a": 0, "e": "Объём бутылки 500 см³ (по воде). Масло: 450 г / 500 см³ = 0,9 г/см³."}, {"q": "Во сколько раз увеличится масса кубика, если его ребро увеличить в 2 раза?", "o": ["в 8 раз", "в 2 раза", "в 4 раза", "в 6 раз"], "a": 0, "e": "Объём растёт как куб ребра: 2³ = 8; при той же плотности масса тоже ×8."}]}}]}, {"title": "Взаимодействие тел. Силы", "topics": [{"id": "p7-force", "title": "Инерция. Сила. Сложение сил", "explain": "Инерция — явление сохранения скорости тела, когда на него не действуют другие тела или их действия скомпенсированы. Скорость меняется только при взаимодействии.\nСила — мера действия одного тела на другое. У силы есть величина, направление и точка приложения. Единица — ньютон (Н), измеряют динамометром. Если на тело действуют несколько сил вдоль одной прямой, их можно заменить равнодействующей: силы в одну сторону складываются, в разные — вычитаются.", "formula": "Равнодействующая: R = F₁ + F₂ (в одну сторону), R = F₁ − F₂ (в противоположные)", "levels": {"easy": [{"q": "Единица силы?", "o": ["ньютон", "килограмм", "паскаль", "джоуль"], "a": 0, "e": "Сила измеряется в ньютонах (Н)."}, {"q": "Прибор для измерения силы?", "o": ["динамометр", "барометр", "термометр", "амперметр"], "a": 0, "e": "Динамометр — пружинный прибор для измерения силы."}, {"q": "Почему при резком торможении автобуса пассажиры наклоняются вперёд?", "o": ["по инерции", "из-за силы тяжести", "из-за трения", "из-за ветра"], "a": 0, "e": "Пассажиры продолжают двигаться с прежней скоростью, а автобус останавливается."}], "medium": [{"q": "На тело вправо действуют силы 5 Н и 3 Н. Равнодействующая?", "o": ["8 Н вправо", "2 Н вправо", "8 Н влево", "15 Н"], "a": 0, "e": "Силы в одну сторону складываются."}, {"q": "На тело действуют 10 Н вправо и 4 Н влево. Равнодействующая?", "o": ["6 Н вправо", "14 Н вправо", "6 Н влево", "40 Н"], "a": 0, "e": "Силы в разные стороны вычитаются; направление — у большей силы."}, {"q": "Равнодействующая сил равна нулю. Как движется тело?", "o": ["покоится или движется равномерно и прямолинейно", "обязательно покоится", "ускоряется", "движется по кругу"], "a": 0, "e": "Если действия сил скомпенсированы, скорость тела не меняется."}], "hard": [{"q": "Две силы 6 Н и 8 Н действуют под прямым углом. Равнодействующая?", "o": ["10 Н", "14 Н", "2 Н", "48 Н"], "a": 0, "e": "По теореме Пифагора: √(36 + 64) = 10 Н."}, {"q": "В каких пределах может быть равнодействующая сил 5 Н и 3 Н при любых направлениях?", "o": ["от 2 до 8 Н", "от 0 до 8 Н", "от 3 до 5 Н", "только 8 Н"], "a": 0, "e": "Минимум — при противоположных направлениях (2 Н), максимум — при одинаковых (8 Н)."}, {"q": "Почему трудно резко остановить тяжёлую тележку?", "o": ["у неё большая масса — большая инертность", "у неё большая скорость звука", "на неё не действует сила тяжести", "у неё нет трения"], "a": 0, "e": "Чем больше масса, тем сильнее тело «сопротивляется» изменению скорости."}], "olympiad": [{"q": "Три силы по 10 Н действуют на точку под углами 120° друг к другу. Равнодействующая?", "o": ["0", "30 Н", "10 Н", "20 Н"], "a": 0, "e": "Три одинаковые силы под 120° образуют замкнутый треугольник — они уравновешены."}, {"q": "Бегущий человек споткнулся. Куда он падает и почему?", "o": ["вперёд — ноги остановились, а тело движется по инерции", "назад — из-за силы тяжести", "вбок — из-за трения", "вперёд — из-за ветра"], "a": 0, "e": "Ноги остановились, верхняя часть тела сохраняет скорость."}, {"q": "Если пиджак резко дёрнуть со стула, на котором лежит монета, монета…", "o": ["останется почти на месте", "улетит вместе с пиджаком", "подпрыгнет вверх", "улетит в обратную сторону"], "a": 0, "e": "При быстром рывке сила трения действует слишком короткое время, монета по инерции остаётся на месте."}]}}, {"id": "p7-gravity", "title": "Сила тяжести. Вес тела. Невесомость", "explain": "Сила тяжести — сила, с которой Земля притягивает тело; направлена вертикально вниз и приложена к телу. Вес — сила, с которой тело давит на опору или растягивает подвес; приложен к опоре. Если тело и опора покоятся, вес равен силе тяжести. Если тело свободно падает вместе с опорой, веса нет — это невесомость.", "formula": "Fтяж = m · g, где g ≈ 9,8 Н/кг (в задачах часто 10 Н/кг)", "levels": {"easy": [{"q": "Куда направлена сила тяжести?", "o": ["вертикально вниз", "вертикально вверх", "горизонтально", "в любую сторону"], "a": 0, "e": "Земля притягивает тела к своему центру — вниз."}, {"q": "Сила тяжести, действующая на тело массой 1 кг (g = 10 Н/кг)?", "o": ["10 Н", "1 Н", "100 Н", "0,1 Н"], "a": 0, "e": "F = mg = 1 × 10 = 10 Н."}, {"q": "Что такое невесомость?", "o": ["состояние, когда тело не давит на опору", "отсутствие массы", "отсутствие силы тяжести на Земле", "очень малая плотность"], "a": 0, "e": "В невесомости вес равен нулю, но масса и сила тяжести остаются."}], "medium": [{"q": "Сила тяжести на тело 50 Н (g = 10 Н/кг). Масса тела?", "o": ["5 кг", "500 кг", "50 кг", "0,5 кг"], "a": 0, "e": "m = F / g = 50 / 10 = 5 кг."}, {"q": "К чему приложен вес книги, лежащей на столе?", "o": ["к столу", "к книге", "к Земле", "к воздуху"], "a": 0, "e": "Вес — сила, действующая на опору."}, {"q": "Ведро с 8 л воды (масса ведра 1 кг) поднимают. Сила тяжести на ведро с водой (g = 10 Н/кг)?", "o": ["90 Н", "80 Н", "9 Н", "10 Н"], "a": 0, "e": "Масса 8 + 1 = 9 кг; F = 90 Н."}], "hard": [{"q": "Почему космонавты на орбите находятся в невесомости?", "o": ["они вместе с кораблём всё время свободно падают", "на орбите нет силы тяжести", "у них нет массы", "корабль отталкивается от Земли"], "a": 0, "e": "Сила тяжести на орбите есть, но корабль и космонавты падают с одинаковым ускорением — никто не давит на опору."}, {"q": "На Луне g ≈ 1,6 Н/кг. Сила тяжести на космонавта массой 80 кг на Луне?", "o": ["128 Н", "800 Н", "50 Н", "80 Н"], "a": 0, "e": "F = 80 × 1,6 = 128 Н. Масса же остаётся 80 кг."}, {"q": "Чем отличаются масса и вес?", "o": ["масса — свойство тела (кг), вес — сила (Н)", "это одно и то же", "вес измеряют в кг, массу в Н", "масса бывает только на Земле"], "a": 0, "e": "Масса — мера инертности, вес — сила давления на опору."}], "olympiad": [{"q": "Человек стоит на весах в лифте, который начинает подниматься с ускорением. Показания весов…", "o": ["увеличатся", "уменьшатся", "не изменятся", "станут нулевыми"], "a": 0, "e": "Опора должна не только удерживать, но и разгонять тело вверх — тело сильнее давит на весы."}, {"q": "Если лифт падает свободно, весы покажут…", "o": ["ноль", "вес как в покое", "двойной вес", "отрицательное значение"], "a": 0, "e": "Человек и весы падают с одинаковым ускорением — давления нет, невесомость."}, {"q": "Брусок на динамометре опустили в воду, показания уменьшились. Изменилась ли сила тяжести бруска?", "o": ["нет, добавилась выталкивающая сила", "да, уменьшилась", "да, увеличилась", "она исчезла"], "a": 0, "e": "Сила тяжести mg та же; уменьшился вес из-за архимедовой силы."}]}}, {"id": "p7-elastic", "title": "Сила упругости. Закон Гука", "explain": "Сила упругости возникает при деформации тела (растяжении, сжатии, изгибе) и стремится вернуть телу прежнюю форму. Для небольших упругих деформаций выполняется закон Гука: сила упругости прямо пропорциональна удлинению. Коэффициент k — жёсткость пружины, измеряется в Н/м.", "formula": "Fупр = k · Δl", "levels": {"easy": [{"q": "Когда возникает сила упругости?", "o": ["при деформации тела", "при нагревании", "при падении", "только в жидкостях"], "a": 0, "e": "Сила упругости — ответ тела на деформацию."}, {"q": "В каких единицах измеряется жёсткость пружины?", "o": ["Н/м", "Н", "м", "кг/м³"], "a": 0, "e": "k = F / Δl, значит Н/м."}, {"q": "Закон Гука связывает силу упругости с…", "o": ["удлинением", "массой", "плотностью", "температурой"], "a": 0, "e": "Fупр = kΔl."}], "medium": [{"q": "Пружина жёсткостью 200 Н/м растянута на 5 см. Сила упругости?", "o": ["10 Н", "1000 Н", "40 Н", "0,1 Н"], "a": 0, "e": "5 см = 0,05 м; F = 200 × 0,05 = 10 Н."}, {"q": "Сила 6 Н растягивает пружину на 3 см. Жёсткость?", "o": ["200 Н/м", "2 Н/м", "18 Н/м", "0,5 Н/м"], "a": 0, "e": "k = 6 / 0,03 = 200 Н/м."}, {"q": "Груз какой массы растянет пружину жёсткостью 100 Н/м на 10 см (g = 10 Н/кг)?", "o": ["1 кг", "10 кг", "0,1 кг", "100 кг"], "a": 0, "e": "F = 100 × 0,1 = 10 Н; m = 10 / 10 = 1 кг."}], "hard": [{"q": "Пружину растянули силой 4 Н на 2 см. На сколько её растянет сила 10 Н?", "o": ["5 см", "8 см", "2,5 см", "20 см"], "a": 0, "e": "k = 200 Н/м; Δl = 10 / 200 = 0,05 м = 5 см."}, {"q": "Как изменится удлинение пружины, если груз увеличить в 3 раза?", "o": ["увеличится в 3 раза", "не изменится", "уменьшится в 3 раза", "увеличится в 9 раз"], "a": 0, "e": "По закону Гука удлинение пропорционально силе."}, {"q": "Выполняется ли закон Гука при очень сильном растяжении?", "o": ["нет, только для небольших упругих деформаций", "да, всегда", "только для резины", "только при сжатии"], "a": 0, "e": "При больших деформациях материал деформируется пластически, пропорциональность нарушается."}], "olympiad": [{"q": "Две одинаковые пружины по 100 Н/м соединили последовательно. Общая жёсткость?", "o": ["50 Н/м", "200 Н/м", "100 Н/м", "10 000 Н/м"], "a": 0, "e": "При последовательном соединении удлинения складываются: 1/k = 1/100 + 1/100, k = 50 Н/м."}, {"q": "Те же пружины соединили параллельно. Общая жёсткость?", "o": ["200 Н/м", "50 Н/м", "100 Н/м", "400 Н/м"], "a": 0, "e": "Силы складываются при одинаковом удлинении: k = 100 + 100."}, {"q": "Пружину жёсткостью 120 Н/м разрезали пополам. Жёсткость половинки?", "o": ["240 Н/м", "60 Н/м", "120 Н/м", "30 Н/м"], "a": 0, "e": "Короче пружина — меньше удлинение при той же силе: жёсткость половинки вдвое больше."}]}}, {"id": "p7-friction", "title": "Сила трения", "explain": "Сила трения возникает при движении (или попытке движения) одного тела по поверхности другого и направлена против движения. Причины: неровности поверхностей и притяжение молекул. Трение бывает покоя, скольжения и качения; трение качения обычно намного меньше трения скольжения. Трение уменьшают смазкой и подшипниками, увеличивают — шероховатостью, песком, протекторами.", "formula": "Fтр = μ · N (μ — коэффициент трения, N — сила нормального давления)", "levels": {"easy": [{"q": "Куда направлена сила трения скольжения?", "o": ["против движения", "по направлению движения", "вертикально вверх", "к центру Земли"], "a": 0, "e": "Трение всегда препятствует движению."}, {"q": "Какое трение обычно меньше?", "o": ["трение качения", "трение скольжения", "они всегда равны", "трение покоя"], "a": 0, "e": "Поэтому колесо и подшипник облегчают движение."}, {"q": "Как уменьшить трение?", "o": ["смазать поверхности", "посыпать песком", "сделать поверхность шершавой", "увеличить нагрузку"], "a": 0, "e": "Смазка разделяет неровности поверхностей."}], "medium": [{"q": "Брусок тянут равномерно с силой 3 Н. Сила трения?", "o": ["3 Н", "0", "6 Н", "больше 3 Н"], "a": 0, "e": "При равномерном движении силы уравновешены: трение равно силе тяги."}, {"q": "Пример полезного трения?", "o": ["подошва не скользит по дороге", "износ деталей двигателя", "нагрев осей колёс", "стирание обуви"], "a": 0, "e": "Без трения невозможно ходить."}, {"q": "Коэффициент трения 0,2, сила давления на опору 50 Н. Сила трения скольжения?", "o": ["10 Н", "250 Н", "50 Н", "0,2 Н"], "a": 0, "e": "Fтр = 0,2 × 50 = 10 Н."}], "hard": [{"q": "Ящик массой 20 кг тянут по полу (μ = 0,3, g = 10 Н/кг). Какая сила нужна для равномерного движения?", "o": ["60 Н", "200 Н", "6 Н", "66 Н"], "a": 0, "e": "N = mg = 200 Н; Fтр = 0,3 × 200 = 60 Н."}, {"q": "Зависит ли сила трения скольжения от площади соприкосновения (при той же силе давления)?", "o": ["практически нет", "да, прямо пропорциональна", "да, обратно пропорциональна", "трения нет при большой площади"], "a": 0, "e": "Сила трения определяется материалами и прижимающей силой."}, {"q": "Брусок лежит на столе, его толкают силой 2 Н, но он не движется. Сила трения покоя?", "o": ["2 Н", "0", "больше 2 Н", "равна весу бруска"], "a": 0, "e": "Трение покоя равно приложенной силе, пока не достигнет максимального значения."}], "olympiad": [{"q": "Почему зимой тротуары посыпают песком?", "o": ["чтобы увеличить трение между обувью и льдом", "чтобы растопить лёд", "чтобы уменьшить трение", "чтобы снег быстрее таял"], "a": 0, "e": "Песчинки увеличивают шероховатость — сцепление растёт."}, {"q": "Брусок массой 2 кг прижат к стене силой 50 Н, μ = 0,4 (g = 10 Н/кг). Будет ли он скользить вниз?", "o": ["нет: максимальное трение 20 Н равно весу 20 Н", "да, сразу упадёт", "поедет вверх", "нельзя определить"], "a": 0, "e": "Fтр.max = 0,4 × 50 = 20 Н, сила тяжести тоже 20 Н — брусок удерживается (на пределе)."}, {"q": "Машина тормозит на мокрой дороге дольше, чем на сухой, потому что…", "o": ["вода уменьшает коэффициент трения", "вода увеличивает массу машины", "на мокрой дороге больше сила тяжести", "вода нагревает шины"], "a": 0, "e": "Вода работает как смазка между шиной и асфальтом."}]}}]}, {"title": "Давление", "topics": [{"id": "p7-pressure", "title": "Давление твёрдых тел", "explain": "Давление показывает, какая сила действует на единицу площади поверхности. Единица — паскаль: 1 Па = 1 Н/м². При одной и той же силе давление тем больше, чем меньше площадь: поэтому острые ножи режут, а широкие лыжи не проваливаются в снег.", "formula": "p = F / S", "levels": {"easy": [{"q": "Единица давления?", "o": ["паскаль", "ньютон", "джоуль", "ватт"], "a": 0, "e": "1 Па = 1 Н/м²."}, {"q": "Зачем у трактора широкие гусеницы?", "o": ["уменьшить давление на почву", "увеличить давление", "увеличить скорость", "уменьшить массу"], "a": 0, "e": "Большая площадь опоры — меньше давление."}, {"q": "Почему острый нож режет лучше?", "o": ["меньше площадь — больше давление", "он тяжелее", "у него больше трение", "он холоднее"], "a": 0, "e": "p = F/S: меньшая площадь даёт большее давление при той же силе."}], "medium": [{"q": "Сила 200 Н действует на площадь 0,5 м². Давление?", "o": ["400 Па", "100 Па", "200 Па", "40 Па"], "a": 0, "e": "p = 200 / 0,5 = 400 Па."}, {"q": "Сколько паскалей в 2 кПа?", "o": ["2000 Па", "200 Па", "20 Па", "0,002 Па"], "a": 0, "e": "1 кПа = 1000 Па."}, {"q": "Ящик весом 600 Н оказывает давление 3000 Па. Площадь опоры?", "o": ["0,2 м²", "5 м²", "1,8 м²", "2 м²"], "a": 0, "e": "S = F / p = 600 / 3000 = 0,2 м²."}], "hard": [{"q": "Мальчик массой 45 кг стоит на лыжах длиной 1,5 м и шириной 10 см (две лыжи). Давление на снег (g = 10 Н/кг)?", "o": ["1500 Па", "3000 Па", "300 Па", "150 Па"], "a": 0, "e": "S = 2 × 1,5 × 0,1 = 0,3 м²; F = 450 Н; p = 450 / 0,3 = 1500 Па."}, {"q": "Кирпич положили сначала плашмя, потом на торец. Как изменилось давление на стол?", "o": ["увеличилось — площадь опоры уменьшилась", "уменьшилось", "не изменилось", "стало равно нулю"], "a": 0, "e": "Сила (вес) та же, а площадь меньше."}, {"q": "Площадь острия кнопки 0,1 мм², сила нажатия 10 Н. Давление?", "o": ["100 МПа", "1 МПа", "100 Па", "10 кПа"], "a": 0, "e": "0,1 мм² = 10⁻⁷ м²; p = 10 / 10⁻⁷ = 10⁸ Па = 100 МПа."}], "olympiad": [{"q": "Куб из одного материала с ребром a давит на стол. Как изменится давление, если ребро увеличить вдвое?", "o": ["увеличится вдвое", "увеличится в 8 раз", "увеличится в 4 раза", "не изменится"], "a": 0, "e": "Вес растёт в 8 раз (объём), площадь — в 4 раза; p = 8/4 = 2."}, {"q": "Давление сплошного цилиндра на стол зависит от…", "o": ["плотности и высоты, но не от площади основания", "только от массы", "только от площади", "от цвета"], "a": 0, "e": "p = mg/S = ρ·S·h·g/S = ρgh."}, {"q": "Слон массой 4 т стоит на четырёх ногах, площадь каждой ступни 0,1 м². Давление (g = 10 Н/кг)?", "o": ["100 кПа", "400 кПа", "10 кПа", "1 МПа"], "a": 0, "e": "S = 0,4 м²; F = 40 000 Н; p = 100 000 Па = 100 кПа."}]}}, {"id": "p7-pascal", "title": "Давление в жидкостях и газах. Закон Паскаля. Сообщающиеся сосуды", "explain": "Закон Паскаля: давление, производимое на жидкость или газ, передаётся в каждую точку без изменения во всех направлениях. Давление внутри жидкости растёт с глубиной.\nСообщающиеся сосуды — сосуды, соединённые внизу; в них однородная жидкость стоит на одном уровне. На законе Паскаля работает гидравлический пресс: малая сила на малом поршне даёт большую силу на большом.", "formula": "p = ρ · g · h;  гидропресс: F₂ / F₁ = S₂ / S₁", "levels": {"easy": [{"q": "Как меняется давление в жидкости с глубиной?", "o": ["растёт", "уменьшается", "не меняется", "сначала растёт, потом падает"], "a": 0, "e": "p = ρgh — чем глубже, тем больше давление."}, {"q": "Как формулируется закон Паскаля?", "o": ["давление на жидкость передаётся во все точки одинаково", "жидкость сжимается легче газа", "давление в жидкости одинаково на любой глубине", "тела в жидкости тонут"], "a": 0, "e": "Это и есть закон Паскаля."}, {"q": "Пример сообщающихся сосудов?", "o": ["чайник и его носик", "стакан", "бутылка с крышкой", "кастрюля с крышкой"], "a": 0, "e": "Носик соединён с чайником снизу — вода в них на одном уровне."}], "medium": [{"q": "Давление воды на глубине 10 м (ρ = 1000 кг/м³, g = 10 Н/кг)?", "o": ["100 кПа", "10 кПа", "1 МПа", "1000 Па"], "a": 0, "e": "p = 1000 × 10 × 10 = 100 000 Па."}, {"q": "В гидропрессе площади поршней 2 см² и 200 см². На малый действует 50 Н. Сила на большом?", "o": ["5000 Н", "500 Н", "50 Н", "0,5 Н"], "a": 0, "e": "F₂ = F₁ × S₂/S₁ = 50 × 100 = 5000 Н."}, {"q": "Зависит ли давление на дно сосуда от формы сосуда при одинаковой высоте воды?", "o": ["нет", "да, в широком больше", "да, в узком больше", "зависит от цвета сосуда"], "a": 0, "e": "Давление на дно определяется только ρ и h (гидростатический парадокс)."}], "hard": [{"q": "На какой глубине в море давление воды 412 кПа (ρ = 1030 кг/м³, g = 10 Н/кг)?", "o": ["40 м", "4 м", "400 м", "41,2 м"], "a": 0, "e": "h = p / (ρg) = 412 000 / 10 300 = 40 м."}, {"q": "В U-образную трубку налили воду, в одно колено добавили масло (0,8 г/см³) столбом 10 см. Разница уровней воды?", "o": ["8 см", "10 см", "2 см", "12,5 см"], "a": 0, "e": "Давления уравниваются: 0,8 × 10 = 1 × h → h = 8 см."}, {"q": "В гидропрессе малый поршень опустился на 20 см, площади 1:40. На сколько поднялся большой?", "o": ["0,5 см", "8 м", "20 см", "4 см"], "a": 0, "e": "Объём жидкости сохраняется: 20 см / 40 = 0,5 см. Выигрываем в силе — проигрываем в расстоянии."}], "olympiad": [{"q": "Сила давления воды на дно аквариума 50×30 см при высоте воды 40 см (g = 10 Н/кг)?", "o": ["600 Н", "6000 Н", "60 Н", "4000 Н"], "a": 0, "e": "p = 1000 × 10 × 0,4 = 4000 Па; F = pS = 4000 × 0,15 = 600 Н."}, {"q": "Почему подводные лодки не могут погружаться сколь угодно глубоко?", "o": ["давление воды растёт с глубиной и может раздавить корпус", "на глубине нет воды", "на глубине вода легче", "там нет силы тяжести"], "a": 0, "e": "Каждые 10 м добавляют около 100 кПа давления."}, {"q": "Сравните давление на дно стакана с водой и стакана с ртутью (13,6 г/см³) при одинаковой высоте.", "o": ["у ртути в 13,6 раза больше", "одинаково", "у воды больше", "у ртути в 1,36 раза больше"], "a": 0, "e": "p = ρgh — при равной высоте давление пропорционально плотности."}]}}, {"id": "p7-atm", "title": "Атмосферное давление", "explain": "Воздух имеет вес, и атмосфера давит на всё, что находится на Земле. Атмосферное давление измеряют барометром. Нормальное атмосферное давление — 760 мм рт. ст. ≈ 101 325 Па ≈ 100 кПа. С высотой давление уменьшается (у поверхности — примерно на 1 мм рт. ст. на каждые 12 м подъёма). Первым измерил атмосферное давление Торричелли с помощью трубки с ртутью.", "formula": "Нормальное давление: 760 мм рт. ст. ≈ 101 325 Па", "levels": {"easy": [{"q": "Каким прибором измеряют атмосферное давление?", "o": ["барометром", "манометром для шин", "термометром", "динамометром"], "a": 0, "e": "Барометр — прибор для измерения атмосферного давления."}, {"q": "Как меняется атмосферное давление с высотой?", "o": ["уменьшается", "увеличивается", "не меняется", "сначала растёт, потом падает"], "a": 0, "e": "Чем выше, тем меньше слой воздуха над нами."}, {"q": "Нормальное атмосферное давление равно…", "o": ["760 мм рт. ст.", "100 мм рт. ст.", "1000 мм рт. ст.", "76 мм рт. ст."], "a": 0, "e": "Это примерно 101 кПа."}], "medium": [{"q": "Почему сок поднимается по трубочке?", "o": ["атмосферное давление вталкивает его, когда во рту давление ниже", "трубочка притягивает сок", "сок легче воздуха", "из-за трения"], "a": 0, "e": "Мы уменьшаем давление во рту, а внешнее давление толкает жидкость."}, {"q": "Сколько это паскалей — 750 мм рт. ст. (1 мм рт. ст. ≈ 133 Па)?", "o": ["≈ 99 750 Па", "≈ 750 Па", "≈ 13 300 Па", "≈ 1 000 000 Па"], "a": 0, "e": "750 × 133 = 99 750 Па."}, {"q": "Учёный, впервые измеривший атмосферное давление?", "o": ["Торричелли", "Ньютон", "Архимед", "Паскаль"], "a": 0, "e": "Эванджелиста Торричелли провёл опыт с трубкой, заполненной ртутью."}], "hard": [{"q": "У подножия горы 760 мм рт. ст., на вершине 700 мм рт. ст. Примерная высота горы (−1 мм рт. ст. на 12 м)?", "o": ["720 м", "60 м", "7000 м", "1200 м"], "a": 0, "e": "Разница 60 мм; 60 × 12 = 720 м."}, {"q": "Почему в опыте Торричелли используют ртуть, а не воду?", "o": ["ртуть плотная — столб всего около 76 см, а воды был бы около 10 м", "вода испаряется мгновенно", "ртуть легче воды", "вода не передаёт давление"], "a": 0, "e": "h = p / (ρg): плотность ртути в 13,6 раза больше."}, {"q": "Сила атмосферного давления на ладонь площадью 0,01 м² (p ≈ 100 кПа)?", "o": ["около 1000 Н", "около 10 Н", "около 100 000 Н", "около 1 Н"], "a": 0, "e": "F = pS = 100 000 × 0,01 = 1000 Н. Мы не чувствуем её, т. к. давление внутри тела уравновешивает внешнее."}], "olympiad": [{"q": "Какой высоты был бы столб воды в «водяном барометре» при нормальном давлении?", "o": ["около 10,3 м", "около 76 см", "около 1 м", "около 100 м"], "a": 0, "e": "h = 101 325 / (1000 × 9,8) ≈ 10,3 м."}, {"q": "Почему в горах вода закипает при температуре ниже 100 °C?", "o": ["атмосферное давление там меньше", "в горах холоднее", "вода в горах легче", "в горах меньше кислорода в воде"], "a": 0, "e": "Температура кипения зависит от внешнего давления."}, {"q": "Магдебургские полушария не могли растащить 16 лошадей, потому что…", "o": ["из шара откачали воздух, и их прижимало атмосферное давление", "полушария были склеены", "они были намагничены", "внутри был вакуумный насос, тянувший их"], "a": 0, "e": "Снаружи давит атмосфера, а изнутри воздуха почти нет."}]}}, {"id": "p7-archimedes", "title": "Архимедова сила. Плавание тел", "explain": "На тело, погружённое в жидкость или газ, действует выталкивающая (архимедова) сила, направленная вверх и равная весу вытесненной жидкости. Если сила тяжести больше архимедовой — тело тонет, равна — плавает внутри жидкости, меньше — всплывает. Поэтому тела, плотность которых меньше плотности жидкости, плавают на поверхности.", "formula": "Fₐ = ρж · g · Vпогр", "levels": {"easy": [{"q": "Куда направлена архимедова сила?", "o": ["вверх", "вниз", "горизонтально", "в любую сторону"], "a": 0, "e": "Выталкивающая сила направлена вверх."}, {"q": "Будет ли плавать в воде тело, плотность которого меньше плотности воды?", "o": ["да", "нет, утонет", "будет висеть посередине", "зависит от формы"], "a": 0, "e": "Если ρтела < ρжидкости, тело всплывает и плавает на поверхности."}, {"q": "От чего НЕ зависит архимедова сила?", "o": ["от плотности самого тела", "от объёма погружённой части", "от плотности жидкости", "от g"], "a": 0, "e": "Fₐ = ρж g V — плотность тела в формулу не входит."}], "medium": [{"q": "Тело объёмом 0,002 м³ полностью погружено в воду. Архимедова сила (g = 10 Н/кг)?", "o": ["20 Н", "2 Н", "200 Н", "0,02 Н"], "a": 0, "e": "Fₐ = 1000 × 10 × 0,002 = 20 Н."}, {"q": "Брусок весит в воздухе 5 Н, в воде — 3 Н. Архимедова сила?", "o": ["2 Н", "8 Н", "3 Н", "5 Н"], "a": 0, "e": "Fₐ = 5 − 3 = 2 Н."}, {"q": "Почему в солёной воде плавать легче?", "o": ["плотность солёной воды больше — больше выталкивающая сила", "солёная вода теплее", "соль отталкивает человека", "в солёной воде меньше давление"], "a": 0, "e": "Fₐ пропорциональна плотности жидкости."}], "hard": [{"q": "Брусок весит в воздухе 5 Н, в воде — 3 Н. Его объём (g = 10 Н/кг)?", "o": ["200 см³", "300 см³", "500 см³", "20 см³"], "a": 0, "e": "V = Fₐ / (ρg) = 2 / 10 000 = 0,0002 м³ = 200 см³."}, {"q": "Какая часть льдины (0,9 г/см³) находится под водой?", "o": ["9/10", "1/10", "половина", "вся"], "a": 0, "e": "При плавании ρтела/ρжидкости = доля погружённого объёма = 0,9."}, {"q": "Плот из брёвен объёмом 2 м³ (дерево 600 кг/м³). Какой максимальный груз он удержит, погрузившись полностью?", "o": ["800 кг", "1200 кг", "2000 кг", "600 кг"], "a": 0, "e": "Fₐ max соответствует 2000 кг воды; плот весит 1200 кг; груз 2000 − 1200 = 800 кг."}], "olympiad": [{"q": "Брусок плавает в воде, погрузившись наполовину. Его плотность?", "o": ["500 кг/м³", "1000 кг/м³", "250 кг/м³", "2000 кг/м³"], "a": 0, "e": "Доля погружённого объёма = ρт/ρв = 0,5."}, {"q": "В стакане с водой плавает кубик льда. Как изменится уровень воды, когда лёд растает?", "o": ["не изменится", "повысится", "понизится", "сначала повысится, потом понизится"], "a": 0, "e": "Плавающий лёд вытесняет ровно столько воды, сколько получится при таянии."}, {"q": "Корабль переходит из реки в море. Его осадка…", "o": ["уменьшится", "увеличится", "не изменится", "станет нулевой"], "a": 0, "e": "В более плотной морской воде для той же выталкивающей силы нужен меньший погружённый объём."}]}}]}, {"title": "Работа, мощность, энергия", "topics": [{"id": "p7-work", "title": "Механическая работа и мощность", "explain": "Механическая работа совершается, когда на тело действует сила и тело перемещается в направлении этой силы. Единица работы — джоуль (Дж). Мощность показывает, как быстро совершается работа; единица — ватт (Вт). 1 кВт = 1000 Вт.", "formula": "A = F · s;  N = A / t;  N = F · v", "levels": {"easy": [{"q": "Единица работы?", "o": ["джоуль", "ватт", "ньютон", "паскаль"], "a": 0, "e": "Работа измеряется в джоулях: 1 Дж = 1 Н · 1 м."}, {"q": "Единица мощности?", "o": ["ватт", "джоуль", "ньютон", "килограмм"], "a": 0, "e": "1 Вт = 1 Дж/с."}, {"q": "Совершается ли механическая работа, если человек держит тяжёлую сумку неподвижно?", "o": ["нет, перемещения нет", "да, большая", "да, но маленькая", "только если сумка тяжелее 10 кг"], "a": 0, "e": "Без перемещения механическая работа равна нулю."}], "medium": [{"q": "Ящик передвинули на 5 м силой 40 Н. Работа?", "o": ["200 Дж", "8 Дж", "45 Дж", "35 Дж"], "a": 0, "e": "A = 40 × 5 = 200 Дж."}, {"q": "Работа 1200 Дж выполнена за 1 минуту. Мощность?", "o": ["20 Вт", "1200 Вт", "72 000 Вт", "120 Вт"], "a": 0, "e": "N = 1200 / 60 = 20 Вт."}, {"q": "Груз массой 10 кг подняли на 3 м (g = 10 Н/кг). Работа?", "o": ["300 Дж", "30 Дж", "13 Дж", "3000 Дж"], "a": 0, "e": "A = mgh = 10 × 10 × 3 = 300 Дж."}], "hard": [{"q": "Двигатель мощностью 2 кВт работал 10 минут. Работа?", "o": ["1,2 МДж", "20 кДж", "12 кДж", "120 Дж"], "a": 0, "e": "A = 2000 × 600 = 1 200 000 Дж."}, {"q": "Автомобиль движется со скоростью 20 м/с, сила тяги 1500 Н. Мощность?", "o": ["30 кВт", "75 Вт", "1520 Вт", "3 кВт"], "a": 0, "e": "N = F · v = 1500 × 20 = 30 000 Вт."}, {"q": "Работа силы тяжести, когда мяч массой 0,5 кг катится по горизонтальному полу 4 м?", "o": ["0", "20 Дж", "2 Дж", "5 Дж"], "a": 0, "e": "Сила тяжести перпендикулярна перемещению — работы нет."}], "olympiad": [{"q": "Насос поднимает 300 л воды на высоту 4 м за 1 минуту (g = 10 Н/кг). Мощность?", "o": ["200 Вт", "12 кВт", "20 Вт", "1200 Вт"], "a": 0, "e": "A = 300 × 10 × 4 = 12 000 Дж; N = 12 000 / 60 = 200 Вт."}, {"q": "Ученик массой 50 кг взбежал на 3-й этаж (6 м) за 12 с. Его мощность (g = 10 Н/кг)?", "o": ["250 Вт", "25 Вт", "3000 Вт", "600 Вт"], "a": 0, "e": "A = 50 × 10 × 6 = 3000 Дж; N = 3000 / 12 = 250 Вт."}, {"q": "Во сколько раз больше работа при подъёме груза на 2 этажа, чем на 1 (тот же груз)?", "o": ["в 2 раза", "в 4 раза", "одинакова", "в 1,5 раза"], "a": 0, "e": "A = mgh — работа пропорциональна высоте."}]}}, {"id": "p7-energy", "title": "Кинетическая и потенциальная энергия. Закон сохранения энергии", "explain": "Энергия показывает, какую работу может совершить тело. Кинетическая энергия — энергия движения, зависит от массы и скорости. Потенциальная энергия — энергия взаимодействия, например тела, поднятого над Землёй, или сжатой пружины. Полная механическая энергия (сумма кинетической и потенциальной) сохраняется, если нет трения.", "formula": "Eк = m·v² / 2;  Eп = m·g·h;  Eк + Eп = const (без трения)", "levels": {"easy": [{"q": "Какой энергией обладает летящий мяч?", "o": ["кинетической (и потенциальной, если он над землёй)", "только внутренней", "никакой", "только электрической"], "a": 0, "e": "Движущееся тело обладает кинетической энергией."}, {"q": "От чего зависит потенциальная энергия поднятого тела?", "o": ["от массы и высоты", "только от скорости", "только от цвета", "от температуры воздуха"], "a": 0, "e": "Eп = mgh."}, {"q": "В каких единицах измеряется энергия?", "o": ["в джоулях", "в ваттах", "в ньютонах", "в паскалях"], "a": 0, "e": "Энергия и работа измеряются в джоулях."}], "medium": [{"q": "Тело массой 2 кг движется со скоростью 3 м/с. Кинетическая энергия?", "o": ["9 Дж", "6 Дж", "18 Дж", "3 Дж"], "a": 0, "e": "Eк = 2 × 9 / 2 = 9 Дж."}, {"q": "Потенциальная энергия камня массой 2 кг на высоте 5 м (g = 10 Н/кг)?", "o": ["100 Дж", "10 Дж", "50 Дж", "20 Дж"], "a": 0, "e": "Eп = 2 × 10 × 5 = 100 Дж."}, {"q": "Мяч падает вниз. Какое превращение энергии происходит?", "o": ["потенциальная → кинетическая", "кинетическая → потенциальная", "энергия исчезает", "внутренняя → потенциальная"], "a": 0, "e": "Высота уменьшается, скорость растёт."}], "hard": [{"q": "Как изменится кинетическая энергия, если скорость увеличить вдвое?", "o": ["увеличится в 4 раза", "увеличится в 2 раза", "не изменится", "уменьшится вдвое"], "a": 0, "e": "Eк пропорциональна квадрату скорости."}, {"q": "Камень падает с высоты 5 м. Скорость у земли без сопротивления воздуха (g = 10 м/с²)?", "o": ["10 м/с", "5 м/с", "50 м/с", "100 м/с"], "a": 0, "e": "mgh = mv²/2 → v = √(2gh) = √100 = 10 м/с."}, {"q": "Мяч бросили вверх со скоростью 20 м/с. На какую высоту он поднимется (g = 10 м/с²)?", "o": ["20 м", "40 м", "10 м", "200 м"], "a": 0, "e": "h = v² / (2g) = 400 / 20 = 20 м."}], "olympiad": [{"q": "Санки съехали с горки высотой 5 м и у подножия имели скорость 8 м/с. Какая доля энергии ушла на трение (g = 10 м/с²)?", "o": ["36%", "64%", "20%", "0"], "a": 0, "e": "Без трения скорость была бы 10 м/с. Eк/Eп = 64/100 → потери 36%."}, {"q": "На какой высоте кинетическая энергия тела, брошенного вверх со скоростью 10 м/с, равна потенциальной (g = 10 м/с²)?", "o": ["2,5 м", "5 м", "1 м", "10 м"], "a": 0, "e": "Максимальная высота 5 м; Eк = Eп, когда Eп равна половине полной энергии — на высоте 2,5 м."}, {"q": "Пуля массой 10 г летит со скоростью 400 м/с. Её кинетическая энергия?", "o": ["800 Дж", "2000 Дж", "4 Дж", "1600 Дж"], "a": 0, "e": "Eк = 0,01 × 160 000 / 2 = 800 Дж."}]}}, {"id": "p7-mechanisms", "title": "Простые механизмы. Рычаг. Блоки. КПД", "explain": "Простые механизмы (рычаг, блок, наклонная плоскость) помогают получить выигрыш в силе. Рычаг в равновесии, если моменты сил равны: сила × плечо. Подвижный блок даёт выигрыш в силе в 2 раза, неподвижный — только меняет направление силы. «Золотое правило» механики: во сколько раз выигрываем в силе, во столько же проигрываем в расстоянии — выигрыша в работе нет. КПД — доля полезной работы во всей затраченной.", "formula": "F₁·l₁ = F₂·l₂ (M = F·l);  КПД = Aполезн / Aзатр · 100%", "levels": {"easy": [{"q": "Какой блок даёт выигрыш в силе в 2 раза?", "o": ["подвижный", "неподвижный", "любой", "никакой"], "a": 0, "e": "Подвижный блок делит вес груза между двумя участками верёвки."}, {"q": "Плечо силы — это…", "o": ["кратчайшее расстояние от оси вращения до линии действия силы", "длина рычага", "масса груза", "высота подъёма"], "a": 0, "e": "Это определение плеча силы."}, {"q": "Может ли КПД механизма быть больше 100%?", "o": ["нет", "да, у хороших механизмов", "да, у рычага", "только у блоков"], "a": 0, "e": "Полезная работа не может быть больше затраченной."}], "medium": [{"q": "На рычаг слева на плече 0,2 м действует 30 Н. Какая сила нужна на плече 0,6 м справа для равновесия?", "o": ["10 Н", "90 Н", "30 Н", "3,6 Н"], "a": 0, "e": "30 × 0,2 = F × 0,6 → F = 10 Н."}, {"q": "Подвижным блоком поднимают груз 200 Н. Какую силу прикладывают (без трения и веса блока)?", "o": ["100 Н", "200 Н", "400 Н", "50 Н"], "a": 0, "e": "Подвижный блок даёт выигрыш в силе в 2 раза."}, {"q": "Полезная работа 300 Дж, затраченная — 400 Дж. КПД?", "o": ["75%", "133%", "25%", "70%"], "a": 0, "e": "300 / 400 × 100% = 75%."}], "hard": [{"q": "По наклонной плоскости длиной 5 м подняли груз 500 Н на высоту 1 м силой 125 Н. КПД?", "o": ["80%", "100%", "25%", "62,5%"], "a": 0, "e": "Aполезн = 500 × 1 = 500 Дж; Aзатр = 125 × 5 = 625 Дж; КПД = 80%."}, {"q": "Подвижным блоком подняли груз на 2 м. На сколько вытянули верёвку?", "o": ["на 4 м", "на 2 м", "на 1 м", "на 8 м"], "a": 0, "e": "Выигрыш в силе в 2 раза — проигрыш в расстоянии в 2 раза."}, {"q": "Момент силы 10 Н с плечом 0,5 м?", "o": ["5 Н·м", "20 Н·м", "10,5 Н·м", "0,05 Н·м"], "a": 0, "e": "M = F · l = 10 × 0,5 = 5 Н·м."}], "olympiad": [{"q": "Система из одного подвижного и одного неподвижного блока поднимает груз 600 Н с КПД 75%. Сила, приложенная к верёвке?", "o": ["400 Н", "300 Н", "450 Н", "800 Н"], "a": 0, "e": "Без потерь нужно 300 Н; с КПД 75%: 300 / 0,75 = 400 Н."}, {"q": "Однородный стержень массой 2 кг подпирают на расстоянии 1/4 длины от левого конца. Какую силу нужно приложить к левому концу, чтобы он был горизонтален (g = 10 Н/кг)?", "o": ["20 Н", "10 Н", "40 Н", "5 Н"], "a": 0, "e": "Центр тяжести в середине — на расстоянии L/4 от опоры; F × L/4 = 20 × L/4 → F = 20 Н."}, {"q": "Почему дверную ручку размещают далеко от петель?", "o": ["большее плечо — меньшая сила для открытия", "так красивее", "чтобы дверь не скрипела", "чтобы уменьшить массу двери"], "a": 0, "e": "Момент силы = F · l: чем больше плечо, тем меньше нужна сила."}]}}]}, {"title": "Основы астрономии", "topics": [{"id": "p7-astro", "title": "Звёздное небо. Солнечная система", "explain": "Астрономия изучает небесные тела: звёзды, планеты, галактики. Солнце — ближайшая к нам звезда. Вокруг него обращаются 8 планет: Меркурий, Венера, Земля, Марс, Юпитер, Сатурн, Уран, Нептун. Звёзды на небе объединяют в созвездия. Видимое суточное движение звёзд — следствие вращения Земли вокруг своей оси за сутки.", "check": true, "levels": {"easy": [{"q": "Сколько планет в Солнечной системе?", "o": ["8", "9", "7", "12"], "a": 0, "e": "С 2006 года Плутон считают карликовой планетой, планет — 8."}, {"q": "Что такое Солнце?", "o": ["звезда", "планета", "спутник", "комета"], "a": 0, "e": "Солнце — звезда, ближайшая к Земле."}, {"q": "Какая планета ближе всех к Солнцу?", "o": ["Меркурий", "Венера", "Марс", "Нептун"], "a": 0, "e": "Порядок: Меркурий, Венера, Земля, Марс…"}], "medium": [{"q": "Почему звёзды за ночь «движутся» по небу?", "o": ["Земля вращается вокруг своей оси", "звёзды летят вокруг Земли", "Солнце двигает звёзды", "из-за ветра в атмосфере"], "a": 0, "e": "Видимое движение звёзд — следствие суточного вращения Земли."}, {"q": "Самая большая планета Солнечной системы?", "o": ["Юпитер", "Сатурн", "Земля", "Нептун"], "a": 0, "e": "Юпитер — газовый гигант, самая массивная планета."}, {"q": "Сколько длится оборот Земли вокруг Солнца?", "o": ["около 1 года", "1 сутки", "1 месяц", "10 лет"], "a": 0, "e": "Около 365,25 суток."}], "hard": [{"q": "Почему на Земле сменяются времена года?", "o": ["ось Земли наклонена к плоскости орбиты", "Земля то приближается, то удаляется от Солнца", "Солнце меняет яркость", "Луна закрывает Солнце"], "a": 0, "e": "Из-за наклона оси меняется высота Солнца и долгота дня."}, {"q": "Свет от Солнца до Земли идёт около 8 минут. Что это значит?", "o": ["мы видим Солнце таким, каким оно было 8 минут назад", "Солнце в 8 км от нас", "свет медленнее звука", "Солнце светит 8 минут в сутки"], "a": 0, "e": "Свет проходит ~150 млн км за ~8,3 мин."}, {"q": "Какая звезда почти не меняет положения на небе Северного полушария?", "o": ["Полярная", "Сириус", "Солнце", "Вега"], "a": 0, "e": "Полярная звезда почти совпадает с направлением оси вращения Земли."}], "olympiad": [{"q": "Как по Полярной звезде примерно определить широту места?", "o": ["её высота над горизонтом ≈ широте", "по её цвету", "по яркости", "по времени восхода"], "a": 0, "e": "Высота полюса мира над горизонтом равна географической широте."}, {"q": "Почему Луна всегда повёрнута к Земле одной стороной?", "o": ["период её вращения вокруг оси равен периоду обращения вокруг Земли", "Луна не вращается", "Земля закрывает другую сторону", "у Луны одна сторона"], "a": 0, "e": "Это синхронное вращение."}, {"q": "Световой год — это единица…", "o": ["расстояния", "времени", "скорости", "яркости"], "a": 0, "e": "Расстояние, которое свет проходит за год (~9,5 трлн км)."}]}}]}]}, "8": {"sections": [{"title": "Тепловые явления", "topics": [{"id": "p8-internal", "title": "Тепловое движение. Внутренняя энергия", "explain": "Все вещества состоят из молекул, которые непрерывно и хаотично движутся — это тепловое движение. Чем выше температура, тем быстрее движутся молекулы. Внутренняя энергия — энергия движения и взаимодействия всех частиц тела. Её можно изменить двумя способами: совершением работы (трение, удар, сжатие) и теплопередачей.", "levels": {"easy": [{"q": "Как связаны температура и движение молекул?", "o": ["чем выше температура, тем быстрее движутся молекулы", "при нагревании молекулы останавливаются", "связи нет", "при охлаждении молекулы ускоряются"], "a": 0, "e": "Температура — мера средней скорости хаотического движения частиц."}, {"q": "Что такое диффузия?", "o": ["взаимное проникновение частиц одного вещества между частицами другого", "плавление льда", "кипение воды", "расширение газа"], "a": 0, "e": "Например, запах духов распространяется по комнате."}, {"q": "Два способа изменить внутреннюю энергию?", "o": ["совершить работу и теплопередача", "покрасить и помыть", "переместить и повернуть", "взвесить и измерить"], "a": 0, "e": "Например, трение нагревает тело, нагревание на плите — тоже."}], "medium": [{"q": "Почему при трении ладоней они нагреваются?", "o": ["работа против сил трения увеличивает внутреннюю энергию", "из-за теплопередачи от воздуха", "кровь приливает только из-за движения", "молекулы замедляются"], "a": 0, "e": "Механическая работа переходит во внутреннюю энергию."}, {"q": "Где диффузия идёт быстрее всего?", "o": ["в газах", "в твёрдых телах", "в жидкостях", "везде одинаково"], "a": 0, "e": "В газах расстояния между частицами большие, частицы движутся свободно."}, {"q": "Почему диффузия в горячей воде идёт быстрее, чем в холодной?", "o": ["молекулы движутся быстрее", "горячая вода плотнее", "в холодной воде нет молекул", "горячая вода тяжелее"], "a": 0, "e": "Скорость теплового движения растёт с температурой."}], "hard": [{"q": "При сжатии воздуха в насосе он нагревается. Почему?", "o": ["над газом совершают работу — внутренняя энергия растёт", "насос нагревается от руки", "воздух получает тепло от шины", "молекул становится больше"], "a": 0, "e": "Работа внешних сил увеличивает внутреннюю энергию газа."}, {"q": "Чем отличается внутренняя энергия 1 кг горячей воды от 1 кг холодной?", "o": ["у горячей больше", "у холодной больше", "одинаковы", "у воды нет внутренней энергии"], "a": 0, "e": "При той же массе и веществе больше температура — больше внутренняя энергия."}, {"q": "Броуновское движение доказывает, что…", "o": ["молекулы жидкости хаотично движутся и толкают частицы", "частицы краски живые", "вода течёт", "молекулы неподвижны"], "a": 0, "e": "Видимые частицы дёргаются от ударов невидимых молекул."}], "olympiad": [{"q": "Кусок свинца ударили молотом несколько раз — он нагрелся. Как изменилась его внутренняя энергия и почему?", "o": ["увеличилась за счёт работы удара", "уменьшилась, т. к. свинец деформировался", "не изменилась", "увеличилась за счёт теплопередачи от молота"], "a": 0, "e": "Механическая работа деформации переходит во внутреннюю энергию."}, {"q": "Есть ли у льда при −10 °C внутренняя энергия?", "o": ["да, у любого тела есть внутренняя энергия", "нет, он замёрз", "только при 0 °C", "только в жидком виде"], "a": 0, "e": "Частицы движутся (колеблются) при любой температуре выше абсолютного нуля."}, {"q": "Почему газ занимает весь предоставленный объём?", "o": ["его молекулы слабо притягиваются и свободно движутся", "газ тяжелее жидкости", "его молекулы неподвижны", "газ притягивается стенками"], "a": 0, "e": "Взаимодействие молекул газа мало, они разлетаются по всему сосуду."}]}}, {"id": "p8-transfer", "title": "Способы теплопередачи", "explain": "Теплопередача — переход энергии от более нагретого тела к менее нагретому без совершения работы. Три способа: теплопроводность (передача от частицы к частице, лучше всего в металлах), конвекция (перенос энергии потоками жидкости или газа) и излучение (передача энергии электромагнитными волнами, возможна даже в вакууме).", "levels": {"easy": [{"q": "Каким способом тепло от Солнца доходит до Земли?", "o": ["излучением", "теплопроводностью", "конвекцией", "никаким"], "a": 0, "e": "В космосе вакуум, передача возможна только излучением."}, {"q": "Какие вещества — лучшие проводники тепла?", "o": ["металлы", "воздух", "шерсть", "дерево"], "a": 0, "e": "У металлов высокая теплопроводность."}, {"q": "Батарея отопления нагревает воздух комнаты в основном за счёт…", "o": ["конвекции", "излучения только", "теплопроводности через стены", "трения"], "a": 0, "e": "Тёплый воздух поднимается вверх, холодный опускается — так перемешивается воздух."}], "medium": [{"q": "Почему батареи ставят внизу, у пола?", "o": ["тёплый воздух поднимается и перемешивает весь воздух комнаты", "так красивее", "внизу холоднее трубы", "чтобы не нагревать потолок"], "a": 0, "e": "Так возникают конвекционные потоки по всей комнате."}, {"q": "Почему тёмная одежда летом нагревается сильнее?", "o": ["тёмные тела лучше поглощают излучение", "тёмная ткань толще", "тёмная ткань хуже проводит тепло", "светлая ткань отражает ветер"], "a": 0, "e": "Тёмные поверхности поглощают больше излучения, светлые — отражают."}, {"q": "Почему шерстяной свитер греет?", "o": ["шерсть и воздух в ней — плохие проводники тепла", "шерсть сама выделяет тепло", "шерсть притягивает тепло Солнца", "в шерсти идёт конвекция"], "a": 0, "e": "Воздух между волокнами плохо проводит тепло."}], "hard": [{"q": "Возможна ли конвекция в твёрдых телах?", "o": ["нет — частицы не могут перемещаться потоками", "да, всегда", "да, только в металлах", "да, при сильном нагреве"], "a": 0, "e": "Конвекция — перенос вещества, а в твёрдом теле частицы закреплены."}, {"q": "Почему в термосе чай долго остаётся горячим?", "o": ["вакуум между стенками мешает теплопроводности и конвекции, а зеркальные стенки — излучению", "термос нагревает чай", "крышка греется", "стекло хорошо проводит тепло"], "a": 0, "e": "Термос мешает всем трём способам теплопередачи."}, {"q": "Почему в морозный день железные перила кажутся холоднее деревянных при одинаковой температуре?", "o": ["металл быстрее отводит тепло от руки", "металл действительно холоднее", "дерево нагревает руку", "металл тяжелее"], "a": 0, "e": "Ощущение холода зависит от скорости отвода тепла — у металла теплопроводность выше."}], "olympiad": [{"q": "Днём у моря ветер дует с моря на сушу (бриз). Почему?", "o": ["суша нагревается быстрее, тёплый воздух над ней поднимается, его место занимает воздух с моря", "море теплее суши днём", "из-за вращения Земли", "из-за приливов"], "a": 0, "e": "Конвекция в масштабе побережья: днём суша теплее воды."}, {"q": "Почему двойные оконные рамы сохраняют тепло?", "o": ["воздух между стёклами — плохой проводник тепла", "два стекла отражают холод", "стекло — хороший проводник", "между стёклами вакуум"], "a": 0, "e": "Слой неподвижного воздуха уменьшает теплопроводность."}, {"q": "Чайник с тёмной матовой поверхностью и блестящей остывают по-разному. Какой остынет быстрее?", "o": ["тёмный матовый — он сильнее излучает", "блестящий", "одинаково", "тот, что тяжелее"], "a": 0, "e": "Тела, хорошо поглощающие излучение, так же хорошо его и испускают."}]}}, {"id": "p8-heat", "title": "Количество теплоты. Удельная теплоёмкость", "explain": "Количество теплоты — энергия, которую тело получает или отдаёт при теплопередаче. Чтобы нагреть тело, нужно тем больше теплоты, чем больше его масса и изменение температуры, и это зависит от вещества. Удельная теплоёмкость c — сколько теплоты нужно, чтобы нагреть 1 кг вещества на 1 °C. У воды c = 4200 Дж/(кг·°C) — одна из самых больших.", "formula": "Q = c · m · (t₂ − t₁)", "levels": {"easy": [{"q": "В каких единицах измеряется количество теплоты?", "o": ["в джоулях", "в градусах", "в ваттах", "в ньютонах"], "a": 0, "e": "Количество теплоты — это энергия, единица — джоуль."}, {"q": "Удельная теплоёмкость воды?", "o": ["4200 Дж/(кг·°C)", "420 Дж/(кг·°C)", "1000 Дж/(кг·°C)", "100 Дж/(кг·°C)"], "a": 0, "e": "Это нужно знать наизусть."}, {"q": "От чего зависит количество теплоты для нагревания?", "o": ["от массы, вещества и изменения температуры", "только от массы", "только от времени", "от формы сосуда"], "a": 0, "e": "Q = cmΔt."}], "medium": [{"q": "Сколько теплоты нужно, чтобы нагреть 2 кг воды на 10 °C?", "o": ["84 кДж", "8,4 кДж", "42 кДж", "840 кДж"], "a": 0, "e": "Q = 4200 × 2 × 10 = 84 000 Дж."}, {"q": "1 кг меди (c = 400 Дж/(кг·°C)) нагрели от 20 до 70 °C. Q?", "o": ["20 кДж", "28 кДж", "8 кДж", "200 кДж"], "a": 0, "e": "Q = 400 × 1 × 50 = 20 000 Дж."}, {"q": "Почему климат у моря мягче?", "o": ["вода медленно нагревается и медленно остывает из-за большой теплоёмкости", "у моря больше солнца", "вода холодная всегда", "ветер дует только с суши"], "a": 0, "e": "Большая теплоёмкость воды сглаживает колебания температуры."}], "hard": [{"q": "На сколько градусов нагреется 0,5 кг воды, получив 21 кДж?", "o": ["на 10 °C", "на 1 °C", "на 21 °C", "на 5 °C"], "a": 0, "e": "Δt = Q / (cm) = 21 000 / (4200 × 0,5) = 10 °C."}, {"q": "Смешали 1 кг воды при 20 °C и 1 кг воды при 80 °C. Температура смеси (без потерь)?", "o": ["50 °C", "60 °C", "40 °C", "100 °C"], "a": 0, "e": "Равные массы — среднее: (20 + 80) / 2."}, {"q": "Нагрев 2 кг вещества на 5 °C потребовал 4,6 кДж. Удельная теплоёмкость?", "o": ["460 Дж/(кг·°C)", "920 Дж/(кг·°C)", "230 Дж/(кг·°C)", "46 Дж/(кг·°C)"], "a": 0, "e": "c = 4600 / (2 × 5) = 460 — это железо/сталь."}], "olympiad": [{"q": "Смешали 2 кг воды при 10 °C и 1 кг воды при 70 °C. Температура смеси?", "o": ["30 °C", "40 °C", "50 °C", "35 °C"], "a": 0, "e": "2(t − 10) = 1(70 − t) → 3t = 90 → t = 30 °C."}, {"q": "Медный (400) и алюминиевый (920 Дж/(кг·°C)) бруски по 1 кг получили одинаковое Q. Какой нагреется сильнее?", "o": ["медный", "алюминиевый", "одинаково", "зависит от формы"], "a": 0, "e": "Δt = Q/(cm): меньше c — больше нагрев."}, {"q": "В 1 кг воды при 20 °C опустили железный шар 0,5 кг при 100 °C (c = 460). Примерная температура (без потерь)?", "o": ["≈ 24 °C", "≈ 60 °C", "≈ 40 °C", "≈ 20 °C"], "a": 0, "e": "460·0,5·(100 − t) = 4200·1·(t − 20) → 23 000 − 230t = 4200t − 84 000 → t ≈ 24,2 °C."}]}}, {"id": "p8-fuel", "title": "Энергия топлива. Удельная теплота сгорания", "explain": "При сгорании топлива выделяется энергия. Удельная теплота сгорания q показывает, сколько теплоты выделится при полном сгорании 1 кг топлива. Например, у бензина q ≈ 46 МДж/кг, у дров ≈ 10 МДж/кг. Топливо — главный источник энергии для транспорта и электростанций, но его сжигание загрязняет воздух.", "formula": "Q = q · m", "levels": {"easy": [{"q": "Что показывает удельная теплота сгорания?", "o": ["сколько теплоты выделяется при сгорании 1 кг топлива", "температуру горения", "массу топлива", "скорость горения"], "a": 0, "e": "Это определение q."}, {"q": "Единица удельной теплоты сгорания?", "o": ["Дж/кг", "Дж/(кг·°C)", "Дж", "кг/м³"], "a": 0, "e": "q = Q / m."}, {"q": "Какое топливо даёт больше энергии с 1 кг?", "o": ["бензин", "сухие дрова", "торф", "бумага"], "a": 0, "e": "У бензина q ≈ 46 МДж/кг, у дров примерно в 4–5 раз меньше."}], "medium": [{"q": "Сколько теплоты выделится при сгорании 2 кг бензина (q = 46 МДж/кг)?", "o": ["92 МДж", "23 МДж", "46 МДж", "48 МДж"], "a": 0, "e": "Q = 46 × 2 = 92 МДж."}, {"q": "При сгорании 0,5 кг топлива выделилось 15 МДж. q?", "o": ["30 МДж/кг", "7,5 МДж/кг", "15 МДж/кг", "3 МДж/кг"], "a": 0, "e": "q = 15 / 0,5 = 30 МДж/кг (похоже на уголь)."}, {"q": "Какая проблема связана со сжиганием топлива?", "o": ["загрязнение воздуха и выбросы CO₂", "охлаждение Земли", "увеличение кислорода в воздухе", "никакой"], "a": 0, "e": "Продукты сгорания загрязняют атмосферу."}], "hard": [{"q": "Сколько дров (q = 10 МДж/кг) нужно сжечь, чтобы нагреть 10 кг воды на 50 °C при отсутствии потерь?", "o": ["0,21 кг", "2,1 кг", "21 кг", "0,021 кг"], "a": 0, "e": "Q = 4200 × 10 × 50 = 2,1 МДж; m = 2,1 / 10 = 0,21 кг."}, {"q": "КПД печки 50%. Сколько теплоты получит вода при сгорании 1 кг угля (q = 30 МДж/кг)?", "o": ["15 МДж", "30 МДж", "60 МДж", "3 МДж"], "a": 0, "e": "Полезно используется половина: 15 МДж."}, {"q": "Почему удельная теплота сгорания пороха меньше, чем у бензина, но порох опаснее?", "o": ["порох сгорает очень быстро — энергия выделяется за доли секунды", "у пороха больше масса", "бензин не горит", "порох холоднее"], "a": 0, "e": "Важна не только энергия, но и скорость её выделения (мощность)."}], "olympiad": [{"q": "На газовой плите (КПД 40%) нагревают 2 кг воды от 20 °C до 100 °C. Сколько газа сгорит (q = 44 МДж/кг)?", "o": ["≈ 38 г", "≈ 15 г", "≈ 380 г", "≈ 3,8 г"], "a": 0, "e": "Q = 4200·2·80 = 672 кДж; нужно 672 / 0,4 = 1680 кДж; m = 1,68 / 44 ≈ 0,038 кг."}, {"q": "Во сколько раз больше энергии даёт 1 кг бензина (46 МДж/кг), чем 1 кг дров (10 МДж/кг)?", "o": ["в 4,6 раза", "в 46 раз", "в 10 раз", "в 2 раза"], "a": 0, "e": "46 / 10 = 4,6."}, {"q": "Почему энергия топлива — «запасённая энергия Солнца»?", "o": ["нефть, уголь и дрова образовались из растений, которые запасали энергию света при фотосинтезе", "топливо нагревалось на Солнце", "Солнце состоит из угля", "это просто выражение без смысла"], "a": 0, "e": "Ископаемое топливо — остатки древних организмов."}]}}, {"id": "p8-melting", "title": "Плавление и кристаллизация", "explain": "Плавление — переход вещества из твёрдого состояния в жидкое, кристаллизация — обратный процесс. У кристаллических тел есть температура плавления (у льда 0 °C), и пока идёт плавление, температура не меняется — энергия идёт на разрушение кристаллической решётки. Удельная теплота плавления λ показывает, сколько теплоты нужно, чтобы расплавить 1 кг вещества при температуре плавления. У льда λ ≈ 340 кДж/кг.", "formula": "Q = λ · m", "levels": {"easy": [{"q": "Как называется переход из твёрдого состояния в жидкое?", "o": ["плавление", "кристаллизация", "испарение", "конденсация"], "a": 0, "e": "Плавление: лёд → вода."}, {"q": "Температура плавления льда?", "o": ["0 °C", "100 °C", "−10 °C", "4 °C"], "a": 0, "e": "При нормальном давлении лёд плавится при 0 °C."}, {"q": "Меняется ли температура льда во время плавления?", "o": ["нет, остаётся 0 °C", "растёт", "падает", "скачет"], "a": 0, "e": "Энергия уходит на разрушение кристаллической решётки."}], "medium": [{"q": "Сколько теплоты нужно, чтобы расплавить 2 кг льда при 0 °C (λ = 340 кДж/кг)?", "o": ["680 кДж", "170 кДж", "340 кДж", "6,8 МДж"], "a": 0, "e": "Q = 340 × 2 = 680 кДж."}, {"q": "Что происходит с энергией при кристаллизации воды?", "o": ["выделяется", "поглощается", "не меняется", "исчезает"], "a": 0, "e": "При кристаллизации выделяется столько же энергии, сколько поглощается при плавлении."}, {"q": "Почему весной снег тает не мгновенно?", "o": ["на плавление нужна большая энергия", "снег холоднее 0 °C всегда", "снег не проводит тепло", "солнце слабое"], "a": 0, "e": "λ у льда большая — 340 кДж на каждый килограмм."}], "hard": [{"q": "Сколько теплоты нужно, чтобы 1 кг льда при −10 °C превратить в воду при 0 °C (cльда = 2100)?", "o": ["361 кДж", "340 кДж", "21 кДж", "382 кДж"], "a": 0, "e": "Нагрев: 2100·1·10 = 21 кДж; плавление: 340 кДж; всего 361 кДж."}, {"q": "Почему в погреб ставят кадку с водой, чтобы овощи не замёрзли?", "o": ["при замерзании вода выделяет теплоту", "вода нагревает воздух за счёт испарения", "вода поглощает холод", "вода увлажняет воздух"], "a": 0, "e": "Кристаллизация воды сопровождается выделением энергии."}, {"q": "Есть ли определённая температура плавления у стекла?", "o": ["нет, это аморфное тело — оно размягчается постепенно", "да, 0 °C", "да, 100 °C", "да, как у металлов"], "a": 0, "e": "У аморфных тел нет кристаллической решётки и чёткой температуры плавления."}], "olympiad": [{"q": "В 1 кг воды при 30 °C бросили 100 г льда при 0 °C. Какая будет температура после таяния (без потерь)?", "o": ["≈ 20 °C", "≈ 27 °C", "≈ 0 °C", "≈ 15 °C"], "a": 0, "e": "Лёд таял: 34 кДж. Остыв, вода отдала 34 кДж и подогрела талую: 4200·1·(30 − t) = 34 000 + 4200·0,1·t → t ≈ 20 °C."}, {"q": "Можно ли расплавить олово (232 °C) в алюминиевой кастрюле (660 °C)?", "o": ["да", "нет", "только при 0 °C", "нельзя, оба металла"], "a": 0, "e": "Температура плавления алюминия выше — кастрюля останется твёрдой."}, {"q": "Почему лёд в стакане с водой при 0 °C не тает в холодильнике при 0 °C?", "o": ["нет разности температур — тепло не передаётся", "лёд всегда тает", "холодильник излучает холод", "в холодильнике нет воздуха"], "a": 0, "e": "Для плавления нужен приток энергии, а теплопередача идёт только при разнице температур."}]}}, {"id": "p8-boiling", "title": "Испарение, кипение, конденсация. Влажность воздуха", "explain": "Испарение — переход из жидкости в пар с поверхности при любой температуре; при этом жидкость охлаждается. Кипение — бурное парообразование по всему объёму при температуре кипения (вода — 100 °C при нормальном давлении). Конденсация — превращение пара в жидкость с выделением энергии. Удельная теплота парообразования воды L ≈ 2,3 МДж/кг. Влажность воздуха показывает, сколько водяного пара в воздухе; её измеряют психрометром или гигрометром.", "formula": "Q = L · m", "levels": {"easy": [{"q": "Испарение происходит…", "o": ["при любой температуре", "только при 100 °C", "только при нагревании на плите", "только зимой"], "a": 0, "e": "Лужа высыхает и в прохладную погоду."}, {"q": "Как называется превращение пара в жидкость?", "o": ["конденсация", "испарение", "плавление", "сублимация"], "a": 0, "e": "Например, капли на холодной крышке кастрюли."}, {"q": "Каким прибором измеряют влажность воздуха?", "o": ["психрометром (гигрометром)", "барометром", "амперметром", "спидометром"], "a": 0, "e": "Психрометр — два термометра, сухой и влажный."}], "medium": [{"q": "Почему после купания становится холодно?", "o": ["вода испаряется с кожи и охлаждает её", "вода холоднее воздуха всегда", "ветер приносит холод", "кожа излучает тепло только мокрой"], "a": 0, "e": "Испарение уносит энергию, тело охлаждается."}, {"q": "Сколько теплоты нужно, чтобы превратить в пар 0,5 кг кипящей воды (L = 2,3 МДж/кг)?", "o": ["1,15 МДж", "4,6 МДж", "2,3 МДж", "0,23 МДж"], "a": 0, "e": "Q = 2,3 × 0,5 = 1,15 МДж."}, {"q": "От чего зависит скорость испарения?", "o": ["от температуры, площади поверхности, ветра и рода жидкости", "только от массы", "только от цвета сосуда", "ни от чего"], "a": 0, "e": "Бельё сохнет быстрее в тёплый ветреный день."}], "hard": [{"q": "Почему ожог паром опаснее ожога кипятком той же температуры?", "o": ["пар при конденсации на коже выделяет ещё большую теплоту", "пар горячее", "пар легче", "кипяток холоднее 100 °C"], "a": 0, "e": "Конденсация 1 кг пара выделяет 2,3 МДж."}, {"q": "Почему в горах вода кипит при температуре ниже 100 °C?", "o": ["атмосферное давление меньше", "воздух чище", "вода другая", "в горах холоднее"], "a": 0, "e": "Температура кипения падает при снижении давления."}, {"q": "Что такое точка росы?", "o": ["температура, при которой пар в воздухе становится насыщенным и выпадает роса", "температура кипения воды", "температура замерзания воды", "время появления росы"], "a": 0, "e": "При охлаждении до точки росы пар начинает конденсироваться."}], "olympiad": [{"q": "Сколько теплоты нужно, чтобы 1 кг воды при 20 °C полностью превратить в пар?", "o": ["≈ 2,64 МДж", "≈ 2,3 МДж", "≈ 0,34 МДж", "≈ 4,2 МДж"], "a": 0, "e": "Нагрев 4200·80 = 336 кДж + парообразование 2,3 МДж ≈ 2,64 МДж."}, {"q": "Почему в жару собака высовывает язык?", "o": ["испарение влаги с языка охлаждает тело", "чтобы показать язык", "так она лучше дышит холодом", "чтобы смочить шерсть"], "a": 0, "e": "Собаки почти не потеют и охлаждаются испарением."}, {"q": "Почему зимой окна «плачут» изнутри?", "o": ["тёплый влажный воздух комнаты охлаждается у холодного стекла ниже точки росы", "стекло тает", "вода просачивается снаружи", "из-за давления"], "a": 0, "e": "Пар конденсируется на холодной поверхности."}]}}, {"id": "p8-engines", "title": "Тепловые двигатели. КПД теплового двигателя", "explain": "Тепловой двигатель превращает часть внутренней энергии топлива в механическую работу. Примеры: двигатель внутреннего сгорания, паровая и газовая турбины, реактивный двигатель. У двигателя есть нагреватель, рабочее тело (газ или пар) и холодильник. КПД показывает, какая доля теплоты от нагревателя превращается в полезную работу; он всегда меньше 100%.", "formula": "КПД = A / Q₁ · 100% = (Q₁ − Q₂) / Q₁ · 100%", "levels": {"easy": [{"q": "Что делает тепловой двигатель?", "o": ["превращает внутреннюю энергию топлива в механическую работу", "производит топливо", "охлаждает воздух", "превращает свет в звук"], "a": 0, "e": "Это определение теплового двигателя."}, {"q": "Пример теплового двигателя?", "o": ["двигатель автомобиля", "электрический чайник", "солнечная батарея", "аккумулятор"], "a": 0, "e": "Двигатель внутреннего сгорания — тепловой двигатель."}, {"q": "Может ли КПД теплового двигателя быть 100%?", "o": ["нет", "да", "только у ракет", "только зимой"], "a": 0, "e": "Часть энергии всегда уходит холодильнику (в окружающую среду)."}], "medium": [{"q": "Двигатель получил 1000 Дж теплоты и совершил работу 250 Дж. КПД?", "o": ["25%", "75%", "40%", "250%"], "a": 0, "e": "250 / 1000 = 0,25."}, {"q": "Сколько тактов у четырёхтактного ДВС?", "o": ["4: впуск, сжатие, рабочий ход, выпуск", "2", "3", "6"], "a": 0, "e": "Название говорит само за себя."}, {"q": "В каком такте ДВС совершается полезная работа?", "o": ["рабочий ход", "впуск", "выпуск", "сжатие"], "a": 0, "e": "Газы от сгорания топлива толкают поршень."}], "hard": [{"q": "КПД двигателя 30%, сгорело 2 кг бензина (q = 46 МДж/кг). Полезная работа?", "o": ["27,6 МДж", "92 МДж", "13,8 МДж", "30 МДж"], "a": 0, "e": "Q = 92 МДж; A = 0,3 × 92 = 27,6 МДж."}, {"q": "Двигатель получает 500 кДж, отдаёт холодильнику 350 кДж. КПД?", "o": ["30%", "70%", "35%", "50%"], "a": 0, "e": "A = 150 кДж; 150 / 500 = 30%."}, {"q": "Какую экологическую проблему создают тепловые двигатели?", "o": ["выбросы вредных газов и CO₂", "шумят только", "охлаждают атмосферу", "никакую"], "a": 0, "e": "Сгорание топлива загрязняет воздух и усиливает парниковый эффект."}], "olympiad": [{"q": "Автомобиль с КПД 25% проехал 100 км при силе тяги 700 Н. Сколько бензина израсходовано (q = 46 МДж/кг)?", "o": ["≈ 6,1 кг", "≈ 1,5 кг", "≈ 25 кг", "≈ 0,6 кг"], "a": 0, "e": "A = 700 × 100 000 = 70 МДж; Q = 70 / 0,25 = 280 МДж; m = 280 / 46 ≈ 6,1 кг."}, {"q": "Почему КПД тепловых двигателей нельзя сделать 100%, даже убрав трение?", "o": ["часть теплоты обязательно отдаётся холодильнику", "из-за веса двигателя", "из-за цвета топлива", "можно, если хорошо смазать"], "a": 0, "e": "Это следует из второго закона термодинамики."}, {"q": "Как повысить КПД тепловой машины в идеале?", "o": ["увеличить температуру нагревателя и уменьшить температуру холодильника", "покрасить двигатель", "увеличить массу двигателя", "уменьшить количество топлива до нуля"], "a": 0, "e": "Предельный КПД зависит от отношения температур нагревателя и холодильника."}]}}]}, {"title": "Электрические явления", "topics": [{"id": "p8-charge", "title": "Электризация. Электрический заряд. Электрическое поле", "explain": "При трении тела могут электризоваться — получать электрический заряд. Заряды бывают положительные и отрицательные: одноимённые отталкиваются, разноимённые притягиваются. Носитель отрицательного заряда — электрон. Заряд измеряют в кулонах (Кл). Вокруг заряженного тела существует электрическое поле, через которое заряды действуют друг на друга. Проводники (металлы) хорошо проводят заряды, диэлектрики (резина, стекло) — плохо.", "levels": {"easy": [{"q": "Как взаимодействуют одноимённые заряды?", "o": ["отталкиваются", "притягиваются", "не взаимодействуют", "по-разному"], "a": 0, "e": "Одноимённые отталкиваются, разноимённые притягиваются."}, {"q": "Какая частица имеет отрицательный заряд?", "o": ["электрон", "протон", "нейтрон", "атом"], "a": 0, "e": "Электрон — носитель элементарного отрицательного заряда."}, {"q": "Пример диэлектрика?", "o": ["резина", "медь", "алюминий", "железо"], "a": 0, "e": "Диэлектрики почти не проводят электрический ток."}], "medium": [{"q": "Почему наэлектризованная расчёска притягивает бумажки?", "o": ["электрическое поле расчёски действует на бумажки", "расчёска магнитная", "из-за силы тяжести", "бумажки липкие"], "a": 0, "e": "Заряженное тело притягивает и незаряженные лёгкие тела."}, {"q": "При трении эбонитовой палочки о шерсть палочка заряжается отрицательно. Почему?", "o": ["электроны переходят с шерсти на палочку", "протоны уходят с палочки", "палочка нагревается", "шерсть теряет нейтроны"], "a": 0, "e": "Перемещаются электроны; палочка их приобретает."}, {"q": "Каким прибором обнаруживают заряд?", "o": ["электроскопом", "амперметром", "динамометром", "барометром"], "a": 0, "e": "Листочки электроскопа расходятся при зарядке."}], "hard": [{"q": "Атом потерял один электрон. Каким стал его заряд?", "o": ["положительным", "отрицательным", "нейтральным", "нулевым по массе"], "a": 0, "e": "Протонов стало больше, чем электронов — получился положительный ион."}, {"q": "Два одинаковых шарика с зарядами +6 нКл и −2 нКл соприкоснулись и разошлись. Заряд каждого?", "o": ["+2 нКл", "+4 нКл", "+3 нКл", "−4 нКл"], "a": 0, "e": "Общий заряд +4 нКл делится поровну: по +2 нКл."}, {"q": "Почему автоцистерны с бензином оснащают цепью, касающейся земли?", "o": ["чтобы отводить в землю накопившийся при трении заряд", "для красоты", "чтобы машина не скользила", "для звукового сигнала"], "a": 0, "e": "Искра от статического заряда может воспламенить пары бензина."}], "olympiad": [{"q": "Можно ли наэлектризовать трением металлический стержень, держа его в руке?", "o": ["практически нет — заряд уйдёт через руку в землю", "да, легко", "только алюминиевый", "только при нагревании"], "a": 0, "e": "Металл и тело человека — проводники; держа через изолирующую ручку — можно."}, {"q": "К незаряженному металлическому шару поднесли (не касаясь) положительно заряженную палочку. Что произойдёт?", "o": ["на ближней стороне шара соберутся электроны, шар притянется", "шар оттолкнётся", "ничего", "шар зарядится положительно целиком"], "a": 0, "e": "Электризация через влияние: заряды в проводнике перераспределяются."}, {"q": "Почему зимой при снятии свитера слышен треск?", "o": ["при трении одежда электризуется, проскакивают маленькие искры", "рвутся нитки", "трещат волосы от холода", "это звук ветра"], "a": 0, "e": "Сухой воздух плохо отводит заряды — они накапливаются."}]}}, {"id": "p8-current", "title": "Электрический ток. Сила тока. Напряжение", "explain": "Электрический ток — упорядоченное (направленное) движение заряженных частиц. В металлах ток создают свободные электроны. Для тока нужны источник тока и замкнутая цепь. Сила тока I показывает, какой заряд проходит через сечение проводника за 1 секунду; измеряется амперметром (последовательно), единица — ампер. Напряжение U показывает, какую работу совершает поле при перемещении единичного заряда; измеряется вольтметром (параллельно), единица — вольт.", "formula": "I = q / t;  U = A / q", "levels": {"easy": [{"q": "Единица силы тока?", "o": ["ампер", "вольт", "ом", "ватт"], "a": 0, "e": "Сила тока измеряется в амперах (А)."}, {"q": "Как включают амперметр в цепь?", "o": ["последовательно", "параллельно", "как угодно", "не включают"], "a": 0, "e": "Через амперметр должен идти весь ток участка."}, {"q": "Чем измеряют напряжение?", "o": ["вольтметром", "амперметром", "омметром только", "манометром"], "a": 0, "e": "Вольтметр подключают параллельно участку цепи."}], "medium": [{"q": "За 10 с через лампу прошёл заряд 5 Кл. Сила тока?", "o": ["0,5 А", "50 А", "2 А", "15 А"], "a": 0, "e": "I = q / t = 5 / 10 = 0,5 А."}, {"q": "Ток 2 А течёт 1 минуту. Какой заряд прошёл?", "o": ["120 Кл", "2 Кл", "30 Кл", "60 Кл"], "a": 0, "e": "q = I · t = 2 × 60 = 120 Кл."}, {"q": "При перемещении заряда 2 Кл поле совершило работу 24 Дж. Напряжение?", "o": ["12 В", "48 В", "26 В", "0,08 В"], "a": 0, "e": "U = A / q = 24 / 2 = 12 В."}], "hard": [{"q": "Какие частицы создают ток в металлах?", "o": ["свободные электроны", "протоны", "ионы обоих знаков", "нейтроны"], "a": 0, "e": "В металлах положительные ионы закреплены в решётке, движутся электроны."}, {"q": "За направление тока принято направление движения…", "o": ["положительных зарядов (от «+» к «−»)", "электронов", "нейтронов", "от «−» к «+» всегда"], "a": 0, "e": "Электроны в металле движутся противоположно условному направлению тока."}, {"q": "Батарейка 1,5 В перемещает заряд 300 Кл. Совершённая работа?", "o": ["450 Дж", "200 Дж", "301,5 Дж", "0,005 Дж"], "a": 0, "e": "A = U · q = 1,5 × 300 = 450 Дж."}], "olympiad": [{"q": "Сколько электронов проходит через сечение проводника за 1 с при токе 1,6 А (e = 1,6·10⁻¹⁹ Кл)?", "o": ["10¹⁹", "10¹⁶", "1,6·10¹⁹", "10²¹"], "a": 0, "e": "N = q / e = 1,6 / 1,6·10⁻¹⁹ = 10¹⁹."}, {"q": "Почему лампа загорается сразу при включении, хотя электроны в проводе движутся медленно (доли мм/с)?", "o": ["электрическое поле распространяется по проводу почти со скоростью света", "электроны летят со скоростью света", "лампа включается заранее", "ток идёт по воздуху"], "a": 0, "e": "Поле приводит в движение электроны сразу по всей цепи."}, {"q": "Что покажет амперметр, ошибочно включённый параллельно лампе?", "o": ["очень большой ток — прибор может сгореть", "ноль", "напряжение", "то же, что и последовательно"], "a": 0, "e": "У амперметра очень маленькое сопротивление — получится почти короткое замыкание."}]}}, {"id": "p8-ohm", "title": "Сопротивление. Закон Ома для участка цепи", "explain": "Сопротивление R характеризует, как проводник препятствует току; единица — ом (Ом). Оно зависит от материала, длины и площади сечения проводника. Закон Ома: сила тока на участке цепи прямо пропорциональна напряжению и обратно пропорциональна сопротивлению.", "formula": "I = U / R;  R = ρ · l / S", "levels": {"easy": [{"q": "Единица сопротивления?", "o": ["ом", "ампер", "вольт", "кулон"], "a": 0, "e": "R измеряется в омах."}, {"q": "Закон Ома для участка цепи:", "o": ["I = U / R", "I = U · R", "U = I / R", "R = I · U"], "a": 0, "e": "Сила тока = напряжение / сопротивление."}, {"q": "Как изменится сила тока, если напряжение увеличить, а сопротивление оставить прежним?", "o": ["увеличится", "уменьшится", "не изменится", "станет нулевой"], "a": 0, "e": "I пропорциональна U."}], "medium": [{"q": "U = 12 В, R = 4 Ом. Сила тока?", "o": ["3 А", "48 А", "16 А", "0,33 А"], "a": 0, "e": "I = 12 / 4 = 3 А."}, {"q": "Через резистор 10 Ом течёт 0,5 А. Напряжение на нём?", "o": ["5 В", "20 В", "10,5 В", "0,05 В"], "a": 0, "e": "U = I · R = 0,5 × 10 = 5 В."}, {"q": "Как изменится сопротивление проволоки, если её длину увеличить вдвое?", "o": ["увеличится вдвое", "уменьшится вдвое", "не изменится", "увеличится в 4 раза"], "a": 0, "e": "R = ρl/S — пропорционально длине."}], "hard": [{"q": "Сопротивление медного провода длиной 100 м и сечением 1 мм² (ρ = 0,017 Ом·мм²/м)?", "o": ["1,7 Ом", "17 Ом", "0,17 Ом", "170 Ом"], "a": 0, "e": "R = 0,017 × 100 / 1 = 1,7 Ом."}, {"q": "Проволоку сложили пополам (вдвое короче, сечение вдвое больше). Сопротивление…", "o": ["уменьшится в 4 раза", "уменьшится в 2 раза", "не изменится", "увеличится в 2 раза"], "a": 0, "e": "l/2 и 2S: R = ρ(l/2)/(2S) = R/4."}, {"q": "Почему провода делают из меди или алюминия?", "o": ["у них малое удельное сопротивление", "они самые прочные", "они не нагреваются вообще", "они дешевле резины"], "a": 0, "e": "Малое сопротивление — меньше потери на нагрев."}], "olympiad": [{"q": "На лампе написано «6 В; 0,5 А». Какое сопротивление у её нити в рабочем режиме?", "o": ["12 Ом", "3 Ом", "6,5 Ом", "0,08 Ом"], "a": 0, "e": "R = 6 / 0,5 = 12 Ом."}, {"q": "Проволоку растянули так, что длина выросла вдвое (объём тот же). Как изменилось сопротивление?", "o": ["увеличилось в 4 раза", "увеличилось вдвое", "не изменилось", "уменьшилось вдвое"], "a": 0, "e": "l ×2, S ÷2 → R ×4."}, {"q": "График I(U) для резистора — прямая через начало координат. При U = 4 В ток 0,2 А. Сопротивление?", "o": ["20 Ом", "0,8 Ом", "5 Ом", "4,2 Ом"], "a": 0, "e": "R = 4 / 0,2 = 20 Ом."}]}}, {"id": "p8-circuits", "title": "Последовательное и параллельное соединение проводников", "explain": "При последовательном соединении через все проводники течёт одинаковый ток, напряжения складываются, общее сопротивление равно сумме сопротивлений. При параллельном соединении напряжение на всех ветвях одинаковое, токи складываются, а общее сопротивление меньше самого маленького из сопротивлений. Дома приборы включены параллельно — каждый получает 220 В и работает независимо.", "formula": "Послед.: R = R₁ + R₂;  парал.: 1/R = 1/R₁ + 1/R₂", "levels": {"easy": [{"q": "Как соединены приборы в квартире?", "o": ["параллельно", "последовательно", "по-разному каждый день", "никак"], "a": 0, "e": "Так каждый прибор получает полное напряжение сети."}, {"q": "Два резистора 3 Ом и 5 Ом соединены последовательно. Общее сопротивление?", "o": ["8 Ом", "2 Ом", "15 Ом", "1,9 Ом"], "a": 0, "e": "R = 3 + 5 = 8 Ом."}, {"q": "При последовательном соединении одинакова для всех проводников…", "o": ["сила тока", "напряжение", "мощность всегда", "длина"], "a": 0, "e": "Ток течёт по одному пути."}], "medium": [{"q": "Два резистора по 10 Ом соединены параллельно. Общее сопротивление?", "o": ["5 Ом", "20 Ом", "10 Ом", "100 Ом"], "a": 0, "e": "Для двух одинаковых: R/2 = 5 Ом."}, {"q": "Резисторы 6 Ом и 3 Ом параллельно. Общее сопротивление?", "o": ["2 Ом", "9 Ом", "4,5 Ом", "18 Ом"], "a": 0, "e": "R = 6·3 / (6 + 3) = 2 Ом."}, {"q": "Одна лампа гирлянды (последовательно соединённой) перегорела. Что будет?", "o": ["погаснут все", "остальные засветятся ярче", "ничего", "погаснет только она"], "a": 0, "e": "Цепь разомкнулась — тока нет."}], "hard": [{"q": "Резисторы 2 Ом и 4 Ом последовательно подключены к 12 В. Напряжение на 4 Ом?", "o": ["8 В", "4 В", "6 В", "12 В"], "a": 0, "e": "I = 12 / 6 = 2 А; U₂ = 2 × 4 = 8 В."}, {"q": "Резисторы 4 Ом и 12 Ом параллельно подключены к 12 В. Общий ток?", "o": ["4 А", "1 А", "3 А", "0,75 А"], "a": 0, "e": "I₁ = 3 А, I₂ = 1 А; всего 4 А."}, {"q": "Три резистора по 6 Ом: два параллельно, к ним последовательно третий. Общее сопротивление?", "o": ["9 Ом", "18 Ом", "2 Ом", "12 Ом"], "a": 0, "e": "6 ∥ 6 = 3 Ом; 3 + 6 = 9 Ом."}], "olympiad": [{"q": "Из четырёх резисторов по 4 Ом нужно получить 4 Ом. Как?", "o": ["две пары последовательно, пары — параллельно", "все последовательно", "все параллельно", "невозможно"], "a": 0, "e": "Каждая пара: 8 Ом; две по 8 Ом параллельно = 4 Ом."}, {"q": "Лампы 60 Вт и 100 Вт (на 220 В) включили последовательно в сеть 220 В. Какая светит ярче?", "o": ["60-ваттная", "100-ваттная", "одинаково", "ни одна не светит"], "a": 0, "e": "У 60-ваттной больше сопротивление; ток одинаков, P = I²R больше у неё."}, {"q": "Добавили ещё один резистор параллельно к имеющимся. Общее сопротивление цепи…", "o": ["уменьшится", "увеличится", "не изменится", "станет бесконечным"], "a": 0, "e": "Появляется ещё один путь для тока — проводимость растёт."}]}}, {"id": "p8-joule", "title": "Работа и мощность электрического тока. Закон Джоуля–Ленца", "explain": "Электрический ток совершает работу: нагревает, светит, вращает двигатели. Мощность тока равна произведению напряжения на силу тока. Количество теплоты, которое выделяет проводник с током, определяет закон Джоуля–Ленца. Расход электроэнергии дома считают в киловатт-часах: 1 кВт·ч = 3,6 МДж.", "formula": "A = U·I·t;  P = U·I = I²R = U²/R;  Q = I²·R·t", "levels": {"easy": [{"q": "Единица мощности тока?", "o": ["ватт", "ампер", "вольт", "ом"], "a": 0, "e": "P = U·I, измеряется в ваттах."}, {"q": "В каких единицах платят за электроэнергию?", "o": ["в киловатт-часах", "в амперах", "в вольтах", "в омах"], "a": 0, "e": "Счётчик считает кВт·ч."}, {"q": "Закон Джоуля–Ленца описывает…", "o": ["нагревание проводника током", "притяжение зарядов", "отражение света", "магнитное поле Земли"], "a": 0, "e": "Q = I²Rt."}], "medium": [{"q": "Мощность прибора при U = 220 В и I = 5 А?", "o": ["1100 Вт", "44 Вт", "225 Вт", "4,4 кВт"], "a": 0, "e": "P = 220 × 5 = 1100 Вт."}, {"q": "Чайник мощностью 2 кВт работал 0,5 ч. Расход энергии?", "o": ["1 кВт·ч", "4 кВт·ч", "2,5 кВт·ч", "0,25 кВт·ч"], "a": 0, "e": "2 × 0,5 = 1 кВт·ч."}, {"q": "Через резистор 5 Ом течёт ток 2 А в течение 10 с. Выделилась теплота?", "o": ["200 Дж", "100 Дж", "50 Дж", "20 Дж"], "a": 0, "e": "Q = I²Rt = 4 × 5 × 10 = 200 Дж."}], "hard": [{"q": "Какой ток идёт через лампу 100 Вт, рассчитанную на 220 В?", "o": ["≈ 0,45 А", "≈ 2,2 А", "≈ 22 А", "≈ 4,5 А"], "a": 0, "e": "I = P / U = 100 / 220 ≈ 0,45 А."}, {"q": "Сопротивление спирали плитки 44 Ом, напряжение 220 В. Мощность?", "o": ["1100 Вт", "5 Вт", "9680 Вт", "264 Вт"], "a": 0, "e": "P = U² / R = 48 400 / 44 = 1100 Вт."}, {"q": "Сколько стоит работа телевизора 100 Вт по 5 ч в день в течение 30 дней при цене 30 ₸ за кВт·ч?", "o": ["450 ₸", "15 ₸", "4500 ₸", "150 ₸"], "a": 0, "e": "0,1 × 5 × 30 = 15 кВт·ч; 15 × 30 = 450 ₸."}], "olympiad": [{"q": "Почему провода, подводящие ток к плитке, почти не нагреваются, а спираль раскаляется?", "o": ["ток одинаков, а сопротивление спирали гораздо больше", "по проводам идёт меньший ток", "провода охлаждаются воздухом сильнее", "спираль ближе к розетке"], "a": 0, "e": "Q = I²R: при одинаковом токе греется участок с большим R."}, {"q": "Спираль плитки укоротили. Как изменилась мощность при том же напряжении?", "o": ["увеличилась", "уменьшилась", "не изменилась", "стала равна нулю"], "a": 0, "e": "R уменьшилось, P = U²/R выросла."}, {"q": "Сколько времени нужно чайнику 2 кВт (КПД 84%), чтобы нагреть 1 кг воды от 20 до 100 °C?", "o": ["200 с", "168 с", "336 с", "400 с"], "a": 0, "e": "Q = 4200 × 80 = 336 кДж; затраты 336 / 0,84 = 400 кДж; t = 400 000 / 2000 = 200 с."}]}}]}, {"title": "Электромагнитные явления", "topics": [{"id": "p8-magnet", "title": "Магнитное поле. Электромагнит. Электродвигатель", "explain": "Вокруг проводника с током и вокруг постоянного магнита существует магнитное поле. Его изображают магнитными линиями; у магнита два полюса: северный (N) и южный (S). Одноимённые полюса отталкиваются, разноимённые притягиваются. Катушка с током и железным сердечником — электромагнит; его магнитное действие можно усиливать током и включать-выключать. Магнитное поле действует на проводник с током — на этом основан электродвигатель. У Земли есть своё магнитное поле, поэтому работает компас.", "levels": {"easy": [{"q": "Сколько полюсов у магнита?", "o": ["два", "один", "три", "сколько угодно, но не меньше трёх"], "a": 0, "e": "Северный и южный — разделить их нельзя."}, {"q": "Как взаимодействуют одноимённые полюса магнитов?", "o": ["отталкиваются", "притягиваются", "не взаимодействуют", "нагреваются"], "a": 0, "e": "N отталкивает N, S отталкивает S."}, {"q": "Почему стрелка компаса указывает на север?", "o": ["у Земли есть магнитное поле", "её притягивает Полярная звезда", "из-за вращения Земли", "на севере холоднее"], "a": 0, "e": "Стрелка — маленький магнит, она поворачивается вдоль линий поля Земли."}], "medium": [{"q": "Как усилить электромагнит?", "o": ["увеличить ток или число витков, вставить железный сердечник", "уменьшить ток", "убрать сердечник", "покрасить катушку"], "a": 0, "e": "Магнитное действие катушки растёт с током и числом витков."}, {"q": "Кто обнаружил магнитное действие тока (отклонение стрелки)?", "o": ["Эрстед", "Ньютон", "Архимед", "Паскаль"], "a": 0, "e": "Опыт Эрстеда: стрелка компаса отклоняется возле провода с током."}, {"q": "Электродвигатель превращает…", "o": ["электрическую энергию в механическую", "механическую в электрическую", "тепловую в световую", "химическую в тепловую"], "a": 0, "e": "Двигатель вращается благодаря действию магнитного поля на ток."}], "hard": [{"q": "Если магнит разрезать пополам, получится…", "o": ["два магнита, у каждого по два полюса", "отдельный северный и южный полюс", "два немагнитных куска", "один полюс исчезнет"], "a": 0, "e": "Магнитных монополей не бывает."}, {"q": "Почему в электромагнитных кранах удобнее использовать электромагнит, а не постоянный магнит?", "o": ["его можно выключить и отпустить груз", "он легче", "он светится", "он дешевле всегда"], "a": 0, "e": "Отключив ток, груз отпускают."}, {"q": "Магнитные линии вне магнита направлены…", "o": ["от северного полюса к южному", "от южного к северному", "по кругу вокруг магнита в одну сторону", "никуда"], "a": 0, "e": "Это принятое соглашение о направлении."}], "olympiad": [{"q": "Почему два параллельных провода с токами в одном направлении притягиваются?", "o": ["каждый находится в магнитном поле другого, и поле действует на ток", "из-за электрических зарядов проводов", "из-за силы тяжести", "они отталкиваются"], "a": 0, "e": "Токи одного направления притягиваются, противоположного — отталкиваются."}, {"q": "Где на Земле находится южный магнитный полюс?", "o": ["вблизи северного географического полюса", "на южном географическом полюсе точно", "на экваторе", "в Казахстане"], "a": 0, "e": "Северный конец стрелки притягивается к южному магнитному полюсу, который находится в Арктике."}, {"q": "Как изменить направление вращения электродвигателя постоянного тока?", "o": ["поменять направление тока (переполюсовать)", "уменьшить напряжение", "нагреть двигатель", "это невозможно"], "a": 0, "e": "Сила, действующая на ток в магнитном поле, меняет направление вместе с током."}]}}]}, {"title": "Световые явления", "topics": [{"id": "p8-reflection", "title": "Распространение и отражение света. Плоское зеркало", "explain": "В однородной среде свет распространяется прямолинейно — поэтому образуются тени. Скорость света в вакууме ≈ 300 000 км/с. Закон отражения: угол падения равен углу отражения, падающий и отражённый лучи лежат в одной плоскости с перпендикуляром. В плоском зеркале изображение мнимое, прямое, такого же размера и находится за зеркалом на таком же расстоянии, как предмет перед ним.", "formula": "α (угол падения) = β (угол отражения)", "levels": {"easy": [{"q": "Почему образуется тень?", "o": ["свет распространяется прямолинейно", "свет отражается", "свет преломляется", "свет поглощается воздухом"], "a": 0, "e": "Предмет загораживает прямые лучи."}, {"q": "Закон отражения света:", "o": ["угол падения равен углу отражения", "угол отражения вдвое больше", "углы всегда 90°", "отражение не подчиняется законам"], "a": 0, "e": "Углы отсчитываются от перпендикуляра к поверхности."}, {"q": "Изображение в плоском зеркале…", "o": ["мнимое, прямое, равное предмету", "действительное и уменьшенное", "перевёрнутое", "увеличенное"], "a": 0, "e": "Зеркало «показывает» предмет за собой на том же расстоянии."}], "medium": [{"q": "Угол между падающим лучом и зеркалом 30°. Угол отражения?", "o": ["60°", "30°", "90°", "120°"], "a": 0, "e": "Угол падения отсчитывают от перпендикуляра: 90° − 30° = 60°."}, {"q": "Человек стоит в 2 м от зеркала. Расстояние от него до изображения?", "o": ["4 м", "2 м", "1 м", "8 м"], "a": 0, "e": "Изображение за зеркалом на 2 м: 2 + 2 = 4 м."}, {"q": "Почему мы видим несветящиеся предметы?", "o": ["они отражают свет, попадающий в глаза", "они светятся слабо", "глаз излучает свет", "благодаря звуку"], "a": 0, "e": "Рассеянное отражение направляет свет во все стороны."}], "hard": [{"q": "Угол между падающим и отражённым лучами 80°. Угол падения?", "o": ["40°", "80°", "50°", "160°"], "a": 0, "e": "Угол делится пополам перпендикуляром: 40°."}, {"q": "Человек приближается к зеркалу со скоростью 1 м/с. С какой скоростью он приближается к своему изображению?", "o": ["2 м/с", "1 м/с", "0,5 м/с", "0"], "a": 0, "e": "Изображение тоже движется к зеркалу со скоростью 1 м/с."}, {"q": "Чем отличается диффузное отражение от зеркального?", "o": ["шероховатая поверхность рассеивает свет во все стороны", "при диффузном свет поглощается", "зеркальное бывает только у воды", "ничем"], "a": 0, "e": "Закон отражения выполняется для каждого луча, но поверхность неровная."}], "olympiad": [{"q": "Какой наименьшей высоты должно быть зеркало, чтобы человек ростом 1,8 м видел себя целиком?", "o": ["0,9 м", "1,8 м", "0,6 м", "3,6 м"], "a": 0, "e": "Нужна половина роста — независимо от расстояния до зеркала."}, {"q": "Зеркало повернули на 10°. На какой угол повернётся отражённый луч?", "o": ["на 20°", "на 10°", "на 5°", "не повернётся"], "a": 0, "e": "Угол падения изменился на 10°, отражения — тоже, итог — 20°."}, {"q": "Солнечный луч падает под углом 60° к горизонту. Как поставить зеркало, чтобы направить луч горизонтально вбок, в направлении от Солнца?", "o": ["под углом 30° к горизонту", "под углом 60°", "вертикально", "горизонтально"], "a": 0, "e": "Перпендикуляр к зеркалу — биссектриса угла (120°) между направлением на Солнце и нужным направлением луча, то есть он наклонён на 60° к горизонту; само зеркало — на 30°."}]}}, {"id": "p8-refraction", "title": "Преломление света", "explain": "Преломление — изменение направления луча на границе двух сред, где свет распространяется с разной скоростью. При переходе в оптически более плотную среду (из воздуха в воду или стекло) луч приближается к перпендикуляру. Из-за преломления ложка в стакане кажется «сломанной», а дно водоёма — ближе, чем на самом деле. Белый свет в призме разлагается на спектр — это дисперсия.", "formula": "n = sin α / sin γ (показатель преломления); n = c / v", "levels": {"easy": [{"q": "Почему ложка в стакане воды кажется сломанной?", "o": ["из-за преломления света", "из-за отражения", "она действительно изогнулась", "из-за тени"], "a": 0, "e": "Свет меняет направление на границе вода–воздух."}, {"q": "Как называется разложение белого света в спектр?", "o": ["дисперсия", "отражение", "диффузия", "интерференция"], "a": 0, "e": "Призма разлагает свет на цвета радуги."}, {"q": "Скорость света в воде по сравнению с воздухом…", "o": ["меньше", "больше", "такая же", "равна нулю"], "a": 0, "e": "В оптически более плотной среде свет медленнее."}], "medium": [{"q": "Луч переходит из воздуха в стекло. Угол преломления по сравнению с углом падения…", "o": ["меньше", "больше", "равен", "всегда 90°"], "a": 0, "e": "В более плотной среде луч приближается к перпендикуляру."}, {"q": "Почему водоём кажется мельче, чем есть?", "o": ["из-за преломления света на поверхности воды", "из-за отражения неба", "вода сжимает дно", "из-за ряби"], "a": 0, "e": "Лучи от дна при выходе из воды отклоняются."}, {"q": "Сколько основных цветов в спектре белого света (по традиции)?", "o": ["7", "3", "5", "12"], "a": 0, "e": "Красный, оранжевый, жёлтый, зелёный, голубой, синий, фиолетовый."}], "hard": [{"q": "Показатель преломления воды 1,33. Скорость света в воде?", "o": ["≈ 225 000 км/с", "≈ 400 000 км/с", "≈ 300 000 км/с", "≈ 133 000 км/с"], "a": 0, "e": "v = c / n = 300 000 / 1,33 ≈ 225 000 км/с."}, {"q": "Что такое полное внутреннее отражение?", "o": ["свет не выходит из более плотной среды и полностью отражается при большом угле падения", "отражение от зеркала", "поглощение света", "разложение света"], "a": 0, "e": "На этом работают оптоволоконные кабели."}, {"q": "Почему радуга видна, когда Солнце позади наблюдателя?", "o": ["свет преломляется и отражается в каплях воды, возвращаясь к наблюдателю", "Солнце светит сквозь облака", "радуга излучает свет сама", "из-за отражения от земли"], "a": 0, "e": "Капля работает как маленькая призма с отражением внутри."}], "olympiad": [{"q": "Луч падает на стекло (n = 1,5) под углом 0° (перпендикулярно). Угол преломления?", "o": ["0°", "30°", "45°", "90°"], "a": 0, "e": "При нормальном падении направление не меняется."}, {"q": "Почему оптоволокно передаёт свет на километры почти без потерь?", "o": ["свет многократно испытывает полное внутреннее отражение", "волокно светится само", "стекло усиливает свет", "свет идёт по оболочке"], "a": 0, "e": "Свет «заперт» внутри сердцевины."}, {"q": "Какой цвет в призме отклоняется сильнее всего?", "o": ["фиолетовый", "красный", "зелёный", "все одинаково"], "a": 0, "e": "Показатель преломления для фиолетового света больше."}]}}, {"id": "p8-lenses", "title": "Линзы. Оптическая сила. Глаз и оптические приборы", "explain": "Линза — прозрачное тело, ограниченное сферическими поверхностями. Собирающая линза (толще в середине) собирает параллельные лучи в фокусе, рассеивающая (тоньше в середине) — рассеивает. Фокусное расстояние F — расстояние от линзы до фокуса. Оптическая сила D = 1/F измеряется в диоптриях (дптр). Глаз работает как собирающая линза; близорукость исправляют рассеивающими линзами, дальнозоркость — собирающими.", "formula": "D = 1 / F;  1/F = 1/d + 1/f", "levels": {"easy": [{"q": "Какая линза толще в середине, чем у краёв?", "o": ["собирающая", "рассеивающая", "любая", "плоская"], "a": 0, "e": "Выпуклая линза собирает лучи."}, {"q": "Единица оптической силы?", "o": ["диоптрия", "метр", "люкс", "ватт"], "a": 0, "e": "1 дптр = 1 / 1 м."}, {"q": "Какие очки нужны при близорукости?", "o": ["с рассеивающими линзами", "с собирающими", "солнцезащитные", "без линз"], "a": 0, "e": "Близорукий глаз собирает лучи перед сетчаткой — их надо рассеять."}], "medium": [{"q": "Фокусное расстояние 0,5 м. Оптическая сила?", "o": ["2 дптр", "0,5 дптр", "5 дптр", "20 дптр"], "a": 0, "e": "D = 1 / 0,5 = 2 дптр."}, {"q": "Оптическая сила −4 дптр. Какая это линза?", "o": ["рассеивающая с F = 25 см", "собирающая с F = 25 см", "собирающая с F = 4 м", "рассеивающая с F = 4 м"], "a": 0, "e": "Отрицательная сила у рассеивающей; F = 1/4 м = 25 см."}, {"q": "Какое изображение даёт собирающая линза на сетчатке глаза?", "o": ["действительное, уменьшенное, перевёрнутое", "мнимое, прямое", "увеличенное прямое", "никакого"], "a": 0, "e": "Мозг «переворачивает» изображение при обработке."}], "hard": [{"q": "Предмет на расстоянии 30 см от собирающей линзы с F = 10 см. Где изображение?", "o": ["15 см за линзой", "30 см", "7,5 см", "20 см"], "a": 0, "e": "1/f = 1/10 − 1/30 = 2/30 → f = 15 см."}, {"q": "Предмет на двойном фокусном расстоянии от собирающей линзы. Изображение…", "o": ["действительное, перевёрнутое, такого же размера", "увеличенное прямое", "мнимое", "уменьшенное прямое"], "a": 0, "e": "При d = 2F получаем f = 2F и увеличение 1."}, {"q": "Где поставить предмет перед собирающей линзой, чтобы она работала как лупа?", "o": ["ближе фокуса", "на двойном фокусе", "дальше двойного фокуса", "в фокусе"], "a": 0, "e": "При d < F изображение мнимое, прямое, увеличенное."}], "olympiad": [{"q": "Две тонкие линзы +3 дптр и +2 дптр сложили вплотную. Общая оптическая сила?", "o": ["5 дптр", "6 дптр", "1 дптр", "1,2 дптр"], "a": 0, "e": "Оптические силы тонких линз, сложенных вплотную, складываются."}, {"q": "Увеличение линзы: предмет 20 см от линзы, изображение 60 см за ней. Во сколько раз изображение больше предмета?", "o": ["в 3 раза", "в 40 раз", "в 1/3", "в 80 раз"], "a": 0, "e": "Γ = f / d = 60 / 20 = 3."}, {"q": "Почему под водой без маски всё видно размытым?", "o": ["показатели преломления воды и глаза близки — роговица почти не преломляет", "вода мутная всегда", "глаз закрывается", "под водой нет света"], "a": 0, "e": "Глаз «рассчитан» на границу воздух–роговица; в воде фокус уходит далеко за сетчатку."}]}}]}]}, "9": {"sections": [{"title": "Основы кинематики", "topics": [{"id": "p9-accel", "title": "Равноускоренное прямолинейное движение", "explain": "При равноускоренном движении скорость тела за любые равные промежутки времени меняется одинаково. Быстроту изменения скорости показывает ускорение a; единица — м/с². Если тело разгоняется, ускорение направлено по скорости, если тормозит — против. Путь при равноускоренном движении растёт как квадрат времени.", "formula": "a = (v − v₀) / t;  v = v₀ + a·t;  s = v₀·t + a·t²/2;  v² − v₀² = 2·a·s", "levels": {"easy": [{"q": "Единица ускорения?", "o": ["м/с²", "м/с", "м", "Н"], "a": 0, "e": "Ускорение — изменение скорости (м/с) за секунду."}, {"q": "Что показывает ускорение?", "o": ["как быстро меняется скорость", "пройденный путь", "массу тела", "направление ветра"], "a": 0, "e": "a = Δv / Δt."}, {"q": "Машина тормозит. Куда направлено ускорение?", "o": ["против скорости", "по скорости", "вверх", "ускорения нет"], "a": 0, "e": "При торможении скорость уменьшается — ускорение направлено против движения."}], "medium": [{"q": "Автомобиль за 5 с разогнался с 0 до 20 м/с. Ускорение?", "o": ["4 м/с²", "100 м/с²", "0,25 м/с²", "20 м/с²"], "a": 0, "e": "a = 20 / 5 = 4 м/с²."}, {"q": "Тело стартует из покоя с ускорением 2 м/с². Скорость через 6 с?", "o": ["12 м/с", "3 м/с", "36 м/с", "8 м/с"], "a": 0, "e": "v = a·t = 2 × 6 = 12 м/с."}, {"q": "Путь тела, начавшего движение из покоя с a = 2 м/с², за 3 с?", "o": ["9 м", "6 м", "3 м", "18 м"], "a": 0, "e": "s = a·t²/2 = 2 × 9 / 2 = 9 м."}], "hard": [{"q": "Машина при скорости 20 м/с тормозит с ускорением 5 м/с². Тормозной путь?", "o": ["40 м", "20 м", "80 м", "4 м"], "a": 0, "e": "s = v₀² / (2a) = 400 / 10 = 40 м."}, {"q": "Как изменится тормозной путь, если начальная скорость увеличится вдвое (то же ускорение)?", "o": ["в 4 раза", "в 2 раза", "не изменится", "в √2 раза"], "a": 0, "e": "s пропорционален квадрату скорости — поэтому превышать скорость опасно."}, {"q": "Тело из покоя за первую секунду прошло 1 м. Сколько оно пройдёт за 3-ю секунду?", "o": ["5 м", "3 м", "9 м", "4 м"], "a": 0, "e": "Пути за последовательные секунды относятся как 1 : 3 : 5."}], "olympiad": [{"q": "Тело, двигаясь равноускоренно из покоя, прошло 100 м за 10 с. Его скорость в конце?", "o": ["20 м/с", "10 м/с", "40 м/с", "5 м/с"], "a": 0, "e": "s = (v/2)·t → v = 2s/t = 20 м/с."}, {"q": "Самолёт при разбеге за 30 с проходит 600 м, начав из покоя. Скорость отрыва?", "o": ["40 м/с", "20 м/с", "80 м/с", "60 м/с"], "a": 0, "e": "a = 2s/t² = 1200/900 = 4/3 м/с²; v = a·t = 40 м/с."}, {"q": "Скорость тела меняется по закону v = 3 + 2t (м/с). Путь за первые 4 с?", "o": ["28 м", "11 м", "16 м", "22 м"], "a": 0, "e": "v₀ = 3, a = 2: s = 3·4 + 2·16/2 = 12 + 16 = 28 м."}]}}, {"id": "p9-freefall", "title": "Свободное падение. Движение тела, брошенного вертикально вверх", "explain": "Свободное падение — движение тела только под действием силы тяжести (без сопротивления воздуха). Все тела падают с одинаковым ускорением g ≈ 9,8 м/с² (в задачах часто 10 м/с²) независимо от массы. Тело, брошенное вверх, движется равнозамедленно, в высшей точке его скорость равна нулю, затем оно падает вниз.", "formula": "v = g·t;  h = g·t²/2;  для броска вверх: hmax = v₀² / (2g),  tподъёма = v₀ / g", "levels": {"easy": [{"q": "Чему примерно равно ускорение свободного падения на Земле?", "o": ["9,8 м/с²", "1 м/с²", "98 м/с²", "0,98 м/с²"], "a": 0, "e": "g ≈ 9,8 м/с²."}, {"q": "В вакууме перо и монета падают…", "o": ["одновременно", "монета быстрее", "перо быстрее", "перо не падает"], "a": 0, "e": "Без воздуха ускорение одинаково для всех тел."}, {"q": "Скорость тела, брошенного вверх, в высшей точке?", "o": ["ноль", "максимальная", "равна начальной", "равна g"], "a": 0, "e": "В высшей точке тело на мгновение останавливается."}], "medium": [{"q": "Камень падает без начальной скорости. Его скорость через 3 с (g = 10 м/с²)?", "o": ["30 м/с", "3 м/с", "45 м/с", "90 м/с"], "a": 0, "e": "v = g·t = 30 м/с."}, {"q": "С какой высоты падало тело, если падение длилось 2 с (g = 10 м/с²)?", "o": ["20 м", "10 м", "40 м", "5 м"], "a": 0, "e": "h = g·t²/2 = 10 × 4 / 2 = 20 м."}, {"q": "Мяч брошен вверх со скоростью 15 м/с. Сколько секунд он поднимается (g = 10 м/с²)?", "o": ["1,5 с", "15 с", "3 с", "0,67 с"], "a": 0, "e": "t = v₀ / g = 1,5 с."}], "hard": [{"q": "Тот же мяч (15 м/с вверх). На какую высоту он поднимется?", "o": ["11,25 м", "22,5 м", "15 м", "7,5 м"], "a": 0, "e": "h = v₀² / (2g) = 225 / 20 = 11,25 м."}, {"q": "Через какое время мяч, брошенный вверх со скоростью 15 м/с, вернётся в точку броска?", "o": ["3 с", "1,5 с", "6 с", "2 с"], "a": 0, "e": "Время подъёма равно времени спуска: 2 × 1,5 = 3 с."}, {"q": "Тело падает с высоты 45 м. Сколько длится падение (g = 10 м/с²)?", "o": ["3 с", "4,5 с", "9 с", "2 с"], "a": 0, "e": "t = √(2h/g) = √9 = 3 с."}], "olympiad": [{"q": "За последнюю секунду падения тело прошло 25 м. С какой высоты оно падало (g = 10 м/с²)?", "o": ["45 м", "25 м", "50 м", "30 м"], "a": 0, "e": "h(t) − h(t−1) = 5(2t − 1) = 25 → t = 3 с; h = 5·9 = 45 м."}, {"q": "Из окна на высоте 20 м одновременно бросили один мяч вверх, другой вниз, оба со скоростью 5 м/с. Какой упадёт с большей скоростью?", "o": ["с одинаковой", "брошенный вверх", "брошенный вниз", "зависит от массы"], "a": 0, "e": "По закону сохранения энергии конечная скорость зависит только от модуля начальной скорости и высоты."}, {"q": "С обрыва уронили камень и через 1 с — второй. Как меняется расстояние между ними в полёте?", "o": ["равномерно растёт", "не меняется", "уменьшается", "растёт как квадрат времени"], "a": 0, "e": "Разность скоростей постоянна (10 м/с), значит расстояние растёт равномерно."}]}}, {"id": "p9-projectile", "title": "Движение тела, брошенного горизонтально и под углом к горизонту", "explain": "Движение тела, брошенного горизонтально или под углом, раскладывают на два независимых движения: равномерное по горизонтали и равноускоренное (с ускорением g) по вертикали. Траектория — парабола. Время полёта при горизонтальном броске зависит только от высоты. При броске под углом с поверхности земли наибольшая дальность получается при угле 45° (без сопротивления воздуха).", "formula": "Горизонтально: x = v₀·t, h = g·t²/2;  под углом: L = v₀²·sin 2α / g", "levels": {"easy": [{"q": "По какой траектории летит тело, брошенное горизонтально?", "o": ["по параболе", "по прямой", "по окружности", "по спирали"], "a": 0, "e": "Сложение равномерного и равноускоренного движений даёт параболу."}, {"q": "Какая составляющая скорости остаётся постоянной при полёте (без сопротивления воздуха)?", "o": ["горизонтальная", "вертикальная", "обе", "никакая"], "a": 0, "e": "По горизонтали силы не действуют."}, {"q": "Под каким углом нужно бросить мяч с земли для наибольшей дальности (без воздуха)?", "o": ["45°", "30°", "60°", "90°"], "a": 0, "e": "sin 2α максимален при α = 45°."}], "medium": [{"q": "Тело бросили горизонтально с высоты 5 м. Время падения (g = 10 м/с²)?", "o": ["1 с", "0,5 с", "2 с", "5 с"], "a": 0, "e": "t = √(2h/g) = √1 = 1 с."}, {"q": "То же тело брошено со скоростью 8 м/с. Дальность полёта?", "o": ["8 м", "5 м", "16 м", "40 м"], "a": 0, "e": "x = v₀·t = 8 × 1 = 8 м."}, {"q": "Пулю выстрелили горизонтально, а другую в тот же момент уронили с той же высоты. Какая упадёт раньше (без воздуха)?", "o": ["одновременно", "выстреленная", "уроненная", "зависит от массы"], "a": 0, "e": "Вертикальное движение у обеих одинаковое."}], "hard": [{"q": "Камень брошен под углом 30° к горизонту со скоростью 20 м/с. Дальность полёта (g = 10 м/с²)?", "o": ["≈ 34,6 м", "40 м", "20 м", "≈ 17,3 м"], "a": 0, "e": "L = v₀² sin 60° / g = 400 × 0,866 / 10 ≈ 34,6 м."}, {"q": "Тот же камень (20 м/с, 30°). Максимальная высота?", "o": ["5 м", "10 м", "20 м", "2,5 м"], "a": 0, "e": "vy = 20 × sin 30° = 10 м/с; h = vy² / (2g) = 100 / 20 = 5 м."}, {"q": "Тело брошено горизонтально с высоты 20 м со скоростью 15 м/с. Скорость при падении (g = 10 м/с²)?", "o": ["25 м/с", "35 м/с", "20 м/с", "15 м/с"], "a": 0, "e": "t = 2 с, vy = 20 м/с; v = √(15² + 20²) = 25 м/с."}], "olympiad": [{"q": "При каких углах броска дальность полёта одинакова (при той же скорости)?", "o": ["α и 90° − α, например 30° и 60°", "только 45°", "α и 180° − α", "дальность всегда разная"], "a": 0, "e": "sin 2α = sin(180° − 2α) = sin 2(90° − α)."}, {"q": "Самолёт летит горизонтально на высоте 500 м со скоростью 100 м/с. За сколько метров до цели (по горизонтали) нужно сбросить груз (g = 10 м/с²)?", "o": ["1000 м", "500 м", "100 м", "2000 м"], "a": 0, "e": "t = √(2·500/10) = 10 с; x = 100 × 10 = 1000 м."}, {"q": "Где находится сброшенный груз относительно самолёта (без воздуха) во время падения?", "o": ["прямо под самолётом", "позади самолёта", "впереди самолёта", "сбоку"], "a": 0, "e": "Горизонтальные скорости груза и самолёта одинаковы."}]}}, {"id": "p9-circle", "title": "Равномерное движение по окружности", "explain": "При равномерном движении по окружности модуль скорости постоянен, но её направление всё время меняется — скорость направлена по касательной. Поэтому есть ускорение, направленное к центру, — центростремительное. Период T — время одного оборота, частота ν — число оборотов за секунду.", "formula": "v = 2πR / T;  ν = 1 / T;  a = v² / R", "levels": {"easy": [{"q": "Куда направлена скорость при движении по окружности?", "o": ["по касательной к окружности", "к центру", "от центра", "вертикально"], "a": 0, "e": "Например, искры от точильного камня летят по касательной."}, {"q": "Куда направлено центростремительное ускорение?", "o": ["к центру окружности", "по касательной", "от центра", "вдоль оси вращения"], "a": 0, "e": "Отсюда и название."}, {"q": "Что такое период вращения?", "o": ["время одного полного оборота", "число оборотов в секунду", "радиус окружности", "скорость"], "a": 0, "e": "T измеряют в секундах."}], "medium": [{"q": "Колесо делает 10 оборотов за 5 с. Частота?", "o": ["2 Гц", "0,5 Гц", "50 Гц", "15 Гц"], "a": 0, "e": "ν = 10 / 5 = 2 об/с."}, {"q": "Скорость 10 м/с, радиус 5 м. Центростремительное ускорение?", "o": ["20 м/с²", "2 м/с²", "50 м/с²", "0,5 м/с²"], "a": 0, "e": "a = v² / R = 100 / 5 = 20 м/с²."}, {"q": "Тело движется по окружности радиусом 2 м с периодом 3,14 с. Скорость (π ≈ 3,14)?", "o": ["4 м/с", "2 м/с", "6,28 м/с", "1 м/с"], "a": 0, "e": "v = 2πR / T = 2 × 3,14 × 2 / 3,14 = 4 м/с."}], "hard": [{"q": "Как изменится центростремительное ускорение, если скорость увеличить вдвое при том же радиусе?", "o": ["увеличится в 4 раза", "в 2 раза", "не изменится", "уменьшится вдвое"], "a": 0, "e": "a = v²/R."}, {"q": "Почему на крутом повороте машину может занести?", "o": ["трения шин не хватает, чтобы обеспечить нужное центростремительное ускорение", "машина становится тяжелее", "уменьшается сила тяжести", "ветер сдувает машину"], "a": 0, "e": "Чем больше скорость и меньше радиус, тем большая сила нужна."}, {"q": "Минутная стрелка длиной 10 см. Скорость её конца (π ≈ 3,14)?", "o": ["≈ 0,17 мм/с", "≈ 1 см/с", "≈ 17 см/с", "≈ 0,17 см/с"], "a": 0, "e": "v = 2π × 0,1 м / 3600 с ≈ 1,7·10⁻⁴ м/с ≈ 0,17 мм/с."}], "olympiad": [{"q": "Земля обращается вокруг Солнца (R ≈ 150 млн км, T = 1 год ≈ 3,15·10⁷ с). Скорость Земли?", "o": ["≈ 30 км/с", "≈ 3 км/с", "≈ 300 км/с", "≈ 1 км/с"], "a": 0, "e": "v = 2π·1,5·10¹¹ / 3,15·10⁷ ≈ 3·10⁴ м/с."}, {"q": "Точки на ободе и в середине радиуса колеса: что у них одинаково?", "o": ["период и угловая скорость", "линейная скорость", "центростремительное ускорение", "путь за оборот"], "a": 0, "e": "Все точки жёсткого колеса делают оборот за одно и то же время."}, {"q": "Почему на экваторе тела весят чуть меньше, чем на полюсе?", "o": ["часть силы тяжести обеспечивает центростремительное ускорение при вращении Земли (и Земля сплюснута)", "на экваторе жарче", "на экваторе нет притяжения", "из-за Луны"], "a": 0, "e": "Вращение Земли и её форма уменьшают вес на экваторе примерно на 0,5%."}]}}]}, {"title": "Основы динамики", "topics": [{"id": "p9-newton", "title": "Законы Ньютона", "explain": "Первый закон (инерции): существуют системы отсчёта, в которых тело сохраняет скорость, если на него не действуют силы или их действие скомпенсировано. Второй закон: ускорение тела прямо пропорционально равнодействующей силе и обратно пропорционально массе. Третий закон: тела действуют друг на друга с силами, равными по модулю и противоположными по направлению.", "formula": "F = m · a;  F₁₂ = −F₂₁", "levels": {"easy": [{"q": "Второй закон Ньютона:", "o": ["F = m·a", "F = m/a", "a = F·m", "F = m·v"], "a": 0, "e": "Ускорение пропорционально силе и обратно пропорционально массе."}, {"q": "Третий закон Ньютона говорит, что силы взаимодействия…", "o": ["равны по модулю и противоположны по направлению", "всегда разные", "направлены в одну сторону", "зависят от цвета тел"], "a": 0, "e": "Действие равно противодействию."}, {"q": "Какой закон называют законом инерции?", "o": ["первый", "второй", "третий", "закон всемирного тяготения"], "a": 0, "e": "Первый закон Ньютона."}], "medium": [{"q": "Сила 10 Н действует на тело массой 2 кг. Ускорение?", "o": ["5 м/с²", "20 м/с²", "0,2 м/с²", "12 м/с²"], "a": 0, "e": "a = F / m = 5 м/с²."}, {"q": "Какая сила сообщает телу массой 500 г ускорение 4 м/с²?", "o": ["2 Н", "2000 Н", "125 Н", "0,125 Н"], "a": 0, "e": "F = 0,5 × 4 = 2 Н."}, {"q": "Лошадь тянет телегу. С какой силой телега тянет лошадь?", "o": ["с такой же по модулю", "с меньшей", "с большей", "не тянет"], "a": 0, "e": "По третьему закону силы равны; лошадь движется, т. к. отталкивается от земли."}], "hard": [{"q": "Тело массой 4 кг тянут силой 20 Н, сила трения 8 Н. Ускорение?", "o": ["3 м/с²", "5 м/с²", "7 м/с²", "2 м/с²"], "a": 0, "e": "a = (20 − 8) / 4 = 3 м/с²."}, {"q": "Лифт массой 500 кг поднимается с ускорением 2 м/с². Сила натяжения троса (g = 10 м/с²)?", "o": ["6000 Н", "5000 Н", "4000 Н", "1000 Н"], "a": 0, "e": "T − mg = ma → T = 500 × 12 = 6000 Н."}, {"q": "Ракета в космосе выключила двигатели. Как она будет двигаться вдали от звёзд и планет?", "o": ["равномерно и прямолинейно", "остановится", "будет тормозить", "полетит по кругу"], "a": 0, "e": "Сил нет — по первому закону скорость сохраняется."}], "olympiad": [{"q": "Два груза 3 кг и 2 кг связаны нитью через неподвижный блок (машина Атвуда). Ускорение (g = 10 м/с²)?", "o": ["2 м/с²", "10 м/с²", "5 м/с²", "1 м/с²"], "a": 0, "e": "a = (m₁ − m₂)g / (m₁ + m₂) = 10/5 = 2 м/с²."}, {"q": "Человек массой 60 кг стоит в лифте, который тормозит при спуске с ускорением 2 м/с². Его вес (g = 10 м/с²)?", "o": ["720 Н", "480 Н", "600 Н", "120 Н"], "a": 0, "e": "Ускорение направлено вверх: P = m(g + a) = 60 × 12 = 720 Н."}, {"q": "Брусок на гладком столе (2 кг) связан нитью с висящим грузом 0,5 кг. Ускорение системы (g = 10 м/с²)?", "o": ["2 м/с²", "2,5 м/с²", "10 м/с²", "5 м/с²"], "a": 0, "e": "a = m₂g / (m₁ + m₂) = 5 / 2,5 = 2 м/с²."}]}}, {"id": "p9-gravitation", "title": "Закон всемирного тяготения. Искусственные спутники Земли", "explain": "Все тела притягиваются друг к другу с силой, прямо пропорциональной произведению их масс и обратно пропорциональной квадрату расстояния между ними. G = 6,67·10⁻¹¹ Н·м²/кг² — гравитационная постоянная. Первая космическая скорость (≈ 7,9 км/с) — скорость, при которой тело становится искусственным спутником Земли у её поверхности. Первый искусственный спутник запущен в 1957 году, первый полёт человека в космос — Юрий Гагарин, 12 апреля 1961 года, с космодрома Байконур (Казахстан).", "formula": "F = G · m₁·m₂ / r²;  v₁ = √(g·R) ≈ 7,9 км/с", "levels": {"easy": [{"q": "Кто открыл закон всемирного тяготения?", "o": ["Исаак Ньютон", "Галилео Галилей", "Архимед", "Альберт Эйнштейн"], "a": 0, "e": "Закон опубликован Ньютоном в XVII веке."}, {"q": "Первая космическая скорость примерно равна…", "o": ["7,9 км/с", "340 м/с", "300 000 км/с", "11,2 км/с"], "a": 0, "e": "11,2 км/с — вторая космическая скорость."}, {"q": "С какого космодрома стартовал Юрий Гагарин?", "o": ["Байконур", "Плесецк", "Канаверал", "Восточный"], "a": 0, "e": "Байконур находится в Казахстане."}], "medium": [{"q": "Как изменится сила притяжения, если расстояние между телами увеличить вдвое?", "o": ["уменьшится в 4 раза", "уменьшится вдвое", "увеличится в 4 раза", "не изменится"], "a": 0, "e": "F ~ 1/r²."}, {"q": "Как изменится сила притяжения, если массу одного тела увеличить в 3 раза?", "o": ["увеличится в 3 раза", "в 9 раз", "не изменится", "уменьшится в 3 раза"], "a": 0, "e": "F ~ m₁·m₂."}, {"q": "Почему мы не замечаем притяжения между людьми?", "o": ["массы людей малы, сила ничтожна", "между людьми притяжения нет", "его компенсирует воздух", "оно направлено вниз"], "a": 0, "e": "G очень мала — заметное притяжение создают только огромные массы."}], "hard": [{"q": "Сила притяжения двух шаров по 1000 кг на расстоянии 1 м (G = 6,67·10⁻¹¹)?", "o": ["6,67·10⁻⁵ Н", "6,67·10⁻¹¹ Н", "6,67 Н", "1000 Н"], "a": 0, "e": "F = 6,67·10⁻¹¹ × 10⁶ / 1 = 6,67·10⁻⁵ Н."}, {"q": "На какой высоте над Землёй (R ≈ 6400 км) ускорение свободного падения в 4 раза меньше, чем у поверхности?", "o": ["6400 км", "3200 км", "12 800 км", "1600 км"], "a": 0, "e": "g ~ 1/r²: нужно r = 2R, то есть высота R."}, {"q": "Почему спутник не падает на Землю?", "o": ["он движется по орбите с такой скоростью, что «падает» мимо Земли", "на орбите нет силы тяжести", "его держат двигатели постоянно", "он легче воздуха"], "a": 0, "e": "Сила тяжести создаёт центростремительное ускорение."}], "olympiad": [{"q": "Масса Луны примерно в 81 раз меньше массы Земли, радиус — в 3,7 раза меньше. Ускорение свободного падения на Луне (g = 9,8)?", "o": ["≈ 1,6 м/с²", "≈ 3,7 м/с²", "≈ 0,12 м/с²", "≈ 9,8 м/с²"], "a": 0, "e": "g ~ M/R²: 9,8 × 3,7² / 81 ≈ 1,65 м/с²."}, {"q": "Как изменится период обращения спутника, если радиус орбиты увеличить? ", "o": ["увеличится", "уменьшится", "не изменится", "станет нулевым"], "a": 0, "e": "Чем выше орбита, тем меньше скорость и длиннее путь — период растёт (третий закон Кеплера)."}, {"q": "Геостационарный спутник висит над одной точкой экватора. Его период обращения?", "o": ["24 часа (сутки)", "1 час", "90 минут", "1 год"], "a": 0, "e": "Он вращается синхронно с Землёй."}]}}]}, {"title": "Законы сохранения", "topics": [{"id": "p9-momentum", "title": "Импульс. Закон сохранения импульса. Реактивное движение", "explain": "Импульс тела — произведение массы на скорость; направлен как скорость. В замкнутой системе тел (внешние силы скомпенсированы) суммарный импульс сохраняется. На этом основано реактивное движение: ракета выбрасывает газы назад и сама движется вперёд. Основоположник теории космических полётов — К. Э. Циолковский.", "formula": "p = m·v;  m₁v₁ + m₂v₂ = m₁v₁' + m₂v₂'", "levels": {"easy": [{"q": "Единица импульса?", "o": ["кг·м/с", "Н", "Дж", "кг/м³"], "a": 0, "e": "p = m·v."}, {"q": "Пример реактивного движения?", "o": ["полёт ракеты", "качение мяча", "падение камня", "плавание бревна"], "a": 0, "e": "Ракета движется, выбрасывая газы."}, {"q": "Импульс направлен…", "o": ["так же, как скорость тела", "против скорости", "вниз", "к центру Земли"], "a": 0, "e": "Масса положительна, поэтому направление совпадает со скоростью."}], "medium": [{"q": "Импульс тела массой 2 кг при скорости 3 м/с?", "o": ["6 кг·м/с", "1,5 кг·м/с", "9 кг·м/с", "5 кг·м/с"], "a": 0, "e": "p = 2 × 3 = 6 кг·м/с."}, {"q": "Почему при выстреле ружьё отдаёт в плечо?", "o": ["по закону сохранения импульса ружьё получает импульс назад", "из-за звука", "из-за нагрева", "из-за силы тяжести"], "a": 0, "e": "Пуля и ружьё получают равные по модулю и противоположные импульсы."}, {"q": "Мальчик массой 50 кг прыгает с неподвижной лодки 100 кг со скоростью 2 м/с. Скорость лодки?", "o": ["1 м/с", "2 м/с", "4 м/с", "0,5 м/с"], "a": 0, "e": "50 × 2 = 100 × v → v = 1 м/с."}], "hard": [{"q": "Вагон 20 т со скоростью 0,6 м/с сцепляется с неподвижным вагоном 10 т. Скорость после сцепки?", "o": ["0,4 м/с", "0,6 м/с", "0,3 м/с", "0,2 м/с"], "a": 0, "e": "20 × 0,6 = 30 × v → v = 0,4 м/с."}, {"q": "Из ружья массой 4 кг вылетает пуля 10 г со скоростью 800 м/с. Скорость отдачи?", "o": ["2 м/с", "8 м/с", "0,2 м/с", "20 м/с"], "a": 0, "e": "4v = 0,01 × 800 = 8 → v = 2 м/с."}, {"q": "Шары 1 кг (2 м/с) и 1 кг (2 м/с) летят навстречу и слипаются. Скорость после удара?", "o": ["0", "2 м/с", "4 м/с", "1 м/с"], "a": 0, "e": "Суммарный импульс: 2 − 2 = 0."}], "olympiad": [{"q": "Ракета массой 1 т выбросила 100 кг газа со скоростью 1000 м/с относительно Земли (начально покоилась). Скорость ракеты?", "o": ["≈ 111 м/с", "100 м/с", "1000 м/с", "≈ 90 м/с"], "a": 0, "e": "900 · v = 100 · 1000 → v ≈ 111 м/с."}, {"q": "Почему ракета может разгоняться в космосе, где не от чего «оттолкнуться»?", "o": ["она отталкивается от собственных выбрасываемых газов", "она отталкивается от вакуума", "её притягивает Луна", "не может"], "a": 0, "e": "Закон сохранения импульса для системы «ракета + газы»."}, {"q": "Снаряд, летящий горизонтально со скоростью 100 м/с, разорвался на две равные части. Одна полетела назад со скоростью 50 м/с. Скорость второй?", "o": ["250 м/с вперёд", "150 м/с вперёд", "50 м/с вперёд", "100 м/с назад"], "a": 0, "e": "m·100 = (m/2)(−50) + (m/2)v → v = 250 м/с."}]}}, {"id": "p9-energy", "title": "Механическая работа и энергия. Закон сохранения механической энергии", "explain": "Работа силы равна произведению силы на перемещение и на косинус угла между ними. Кинетическая энергия тела равна mv²/2, потенциальная в поле тяжести — mgh, сжатой пружины — kx²/2. В замкнутой системе без трения полная механическая энергия сохраняется. Трение превращает часть механической энергии во внутреннюю.", "formula": "A = F·s·cos α;  Eк = mv²/2;  Eп = mgh;  Eп.пр = kx²/2;  Eк + Eп = const", "levels": {"easy": [{"q": "Формула кинетической энергии?", "o": ["mv²/2", "mgh", "kx²/2", "m·v"], "a": 0, "e": "Энергия движения."}, {"q": "Чему равна работа силы, перпендикулярной перемещению?", "o": ["нулю", "F·s", "максимальна", "отрицательна всегда"], "a": 0, "e": "cos 90° = 0."}, {"q": "Что происходит с механической энергией при наличии трения?", "o": ["часть переходит во внутреннюю", "она растёт", "сохраняется точно", "превращается в массу"], "a": 0, "e": "Тела нагреваются."}], "medium": [{"q": "Сила 50 Н под углом 60° к горизонту протянула санки на 10 м. Работа?", "o": ["250 Дж", "500 Дж", "433 Дж", "50 Дж"], "a": 0, "e": "A = 50 × 10 × cos 60° = 250 Дж."}, {"q": "Пружина жёсткостью 400 Н/м сжата на 5 см. Её энергия?", "o": ["0,5 Дж", "10 Дж", "20 Дж", "1 Дж"], "a": 0, "e": "E = 400 × 0,0025 / 2 = 0,5 Дж."}, {"q": "Тело массой 1 кг падает с высоты 20 м. Кинетическая энергия у земли (g = 10)?", "o": ["200 Дж", "20 Дж", "100 Дж", "400 Дж"], "a": 0, "e": "Eк = mgh = 200 Дж (без сопротивления воздуха)."}], "hard": [{"q": "Шарик 0,1 кг выстрелили пружиной (k = 1000 Н/м, сжатие 2 см) вертикально вверх. Высота подъёма (g = 10)?", "o": ["0,2 м", "2 м", "0,02 м", "20 м"], "a": 0, "e": "kx²/2 = 0,2 Дж = mgh → h = 0,2 / 1 = 0,2 м."}, {"q": "Скорость тела увеличилась с 2 до 4 м/с, масса 3 кг. Работа равнодействующей?", "o": ["18 Дж", "6 Дж", "24 Дж", "12 Дж"], "a": 0, "e": "ΔEк = 3(16 − 4)/2 = 18 Дж (теорема о кинетической энергии)."}, {"q": "Маятник отклонили на высоту 5 см. Его скорость в нижней точке (g = 10)?", "o": ["1 м/с", "0,5 м/с", "10 м/с", "0,1 м/с"], "a": 0, "e": "v = √(2gh) = √1 = 1 м/с."}], "olympiad": [{"q": "Брусок соскальзывает с горки высотой 2 м и у подножия имеет скорость 6 м/с, масса 1 кг. Работа силы трения (g = 10)?", "o": ["−2 Дж", "−20 Дж", "−18 Дж", "0"], "a": 0, "e": "mgh = 20 Дж, Eк = 18 Дж; работа трения −2 Дж."}, {"q": "Шайба скользит по льду со скоростью 10 м/с, μ = 0,1. Какой путь она пройдёт до остановки (g = 10)?", "o": ["50 м", "100 м", "10 м", "5 м"], "a": 0, "e": "mv²/2 = μmgs → s = v²/(2μg) = 100/2 = 50 м."}, {"q": "Пуля 9 г, летящая со скоростью 500 м/с, застревает в доске. Сколько энергии перешло во внутреннюю?", "o": ["1125 Дж", "4,5 Дж", "2250 Дж", "562 Дж"], "a": 0, "e": "Eк = 0,009 × 250 000 / 2 = 1125 Дж."}]}}]}, {"title": "Механические колебания и волны", "topics": [{"id": "p9-oscillations", "title": "Механические колебания. Маятники", "explain": "Колебания — движения, которые повторяются через равные промежутки времени. Амплитуда — наибольшее отклонение от положения равновесия, период T — время одного полного колебания, частота ν = 1/T (в герцах). Период математического маятника зависит только от длины нити и g, а пружинного — от массы груза и жёсткости пружины. Резонанс — резкое увеличение амплитуды, когда частота внешней силы совпадает с собственной частотой системы.", "formula": "T = 2π√(l/g);  T = 2π√(m/k);  ν = 1/T", "levels": {"easy": [{"q": "Единица частоты колебаний?", "o": ["герц", "секунда", "метр", "ньютон"], "a": 0, "e": "1 Гц — одно колебание в секунду."}, {"q": "Амплитуда — это…", "o": ["наибольшее отклонение от положения равновесия", "время одного колебания", "число колебаний", "скорость груза"], "a": 0, "e": "Определение амплитуды."}, {"q": "Что такое резонанс?", "o": ["резкий рост амплитуды при совпадении частот", "затухание колебаний", "отражение звука", "остановка маятника"], "a": 0, "e": "Например, раскачивание качелей «в такт»."}], "medium": [{"q": "Маятник сделал 20 колебаний за 10 с. Период?", "o": ["0,5 с", "2 с", "200 с", "10 с"], "a": 0, "e": "T = 10 / 20 = 0,5 с."}, {"q": "Период 0,25 с. Частота?", "o": ["4 Гц", "0,25 Гц", "25 Гц", "2 Гц"], "a": 0, "e": "ν = 1 / T = 4 Гц."}, {"q": "Как изменится период математического маятника, если длину нити увеличить в 4 раза?", "o": ["увеличится в 2 раза", "в 4 раза", "уменьшится вдвое", "не изменится"], "a": 0, "e": "T ~ √l."}], "hard": [{"q": "Период математического маятника длиной 1 м (g ≈ 9,8, π² ≈ 9,8)?", "o": ["≈ 2 с", "≈ 1 с", "≈ 6,28 с", "≈ 0,5 с"], "a": 0, "e": "T = 2π√(1/9,8) ≈ 2 с."}, {"q": "Зависит ли период математического маятника от массы груза?", "o": ["нет", "да, тяжелее — медленнее", "да, тяжелее — быстрее", "только при малых колебаниях"], "a": 0, "e": "В формулу T = 2π√(l/g) масса не входит."}, {"q": "Груз на пружине: массу увеличили в 4 раза. Период…", "o": ["увеличился в 2 раза", "в 4 раза", "уменьшился вдвое", "не изменился"], "a": 0, "e": "T ~ √m."}], "olympiad": [{"q": "Маятниковые часы перенесли на Луну (g в 6 раз меньше). Как изменится период?", "o": ["увеличится примерно в 2,45 раза", "уменьшится в 6 раз", "увеличится в 6 раз", "не изменится"], "a": 0, "e": "T ~ 1/√g; √6 ≈ 2,45 — часы будут отставать."}, {"q": "За одно полное колебание груз проходит путь, равный…", "o": ["четырём амплитудам", "одной амплитуде", "двум амплитудам", "длине нити"], "a": 0, "e": "Из крайней точки в равновесие, в другую крайнюю и обратно."}, {"q": "Почему солдатам запрещено идти по мосту строевым шагом в ногу?", "o": ["может возникнуть резонанс и мост раскачается", "шум мешает жителям", "мост может нагреться", "так требует традиция без причины"], "a": 0, "e": "Совпадение частоты шагов с собственной частотой моста опасно."}]}}, {"id": "p9-waves", "title": "Механические волны. Звук", "explain": "Волна — распространение колебаний в упругой среде; волна переносит энергию, но не вещество. В поперечной волне частицы колеблются поперёк направления распространения, в продольной — вдоль. Длина волны λ — расстояние, которое волна проходит за один период. Звук — продольная механическая волна с частотой примерно от 20 Гц до 20 кГц; в вакууме он не распространяется. Скорость звука в воздухе ≈ 340 м/с, в воде ≈ 1500 м/с.", "formula": "v = λ · ν = λ / T", "levels": {"easy": [{"q": "Распространяется ли звук в вакууме?", "o": ["нет", "да, быстрее, чем в воздухе", "да, так же", "только громкий"], "a": 0, "e": "Звуку нужна среда — воздух, вода, твёрдое тело."}, {"q": "Звук в воздухе — это волна…", "o": ["продольная", "поперечная", "электромагнитная", "световая"], "a": 0, "e": "Частицы воздуха колеблются вдоль направления распространения."}, {"q": "Какие звуки называют ультразвуком?", "o": ["с частотой выше 20 кГц", "очень громкие", "ниже 20 Гц", "звуки в воде"], "a": 0, "e": "Ультразвук не слышен человеку; его используют в УЗИ и эхолотах."}], "medium": [{"q": "Длина волны 2 м, частота 170 Гц. Скорость волны?", "o": ["340 м/с", "85 м/с", "172 м/с", "680 м/с"], "a": 0, "e": "v = λν = 2 × 170 = 340 м/с."}, {"q": "Эхо вернулось через 2 с. Расстояние до преграды (звук 340 м/с)?", "o": ["340 м", "680 м", "170 м", "1360 м"], "a": 0, "e": "Звук прошёл туда и обратно: 340 × 2 / 2 = 340 м."}, {"q": "От чего зависит высота звука?", "o": ["от частоты колебаний", "от амплитуды", "от скорости звука", "от расстояния"], "a": 0, "e": "Громкость связана с амплитудой, высота — с частотой."}], "hard": [{"q": "Эхолот: сигнал вернулся от дна через 0,8 с, скорость звука в воде 1500 м/с. Глубина?", "o": ["600 м", "1200 м", "1875 м", "300 м"], "a": 0, "e": "h = 1500 × 0,8 / 2 = 600 м."}, {"q": "Звук переходит из воздуха в воду. Что не меняется?", "o": ["частота", "скорость", "длина волны", "всё меняется"], "a": 0, "e": "Частота задаётся источником."}, {"q": "Почему в горах слышно эхо, а в степи — нет?", "o": ["в горах есть отражающие поверхности (скалы)", "в горах звук громче", "в степи звук быстрее", "в степи нет воздуха"], "a": 0, "e": "Эхо — отражённый звук."}], "olympiad": [{"q": "Человек услышал два звука удара по рельсу (по рельсу и по воздуху) с интервалом 1 с. Расстояние до места удара (v воздух 340, v сталь 5000 м/с)?", "o": ["≈ 365 м", "≈ 340 м", "≈ 5000 м", "≈ 4660 м"], "a": 0, "e": "s/340 − s/5000 = 1 → s ≈ 365 м."}, {"q": "Летучие мыши ориентируются в темноте благодаря…", "o": ["эхолокации ультразвуком", "отличному зрению", "магнитному полю", "запаху"], "a": 0, "e": "Они издают ультразвук и слушают отражения."}, {"q": "Длина волны звука частотой 20 Гц в воздухе (340 м/с)?", "o": ["17 м", "6800 м", "1,7 м", "0,06 м"], "a": 0, "e": "λ = 340 / 20 = 17 м."}]}}]}, {"title": "Электромагнитные явления", "topics": [{"id": "p9-induction", "title": "Электромагнитная индукция. Электромагнитные волны", "explain": "Явление электромагнитной индукции открыл Майкл Фарадей: при изменении магнитного потока через замкнутый контур в нём возникает индукционный ток. На этом явлении работают генераторы электростанций и трансформаторы. Переменные электрическое и магнитное поля порождают друг друга и распространяются в пространстве как электромагнитная волна со скоростью света. К ним относятся радиоволны, свет, рентгеновское излучение.", "check": true, "levels": {"easy": [{"q": "Кто открыл электромагнитную индукцию?", "o": ["Майкл Фарадей", "Исаак Ньютон", "Архимед", "Блез Паскаль"], "a": 0, "e": "Открытие сделано в 1831 году."}, {"q": "На явлении электромагнитной индукции работает…", "o": ["генератор электростанции", "лампа накаливания", "термометр", "линза"], "a": 0, "e": "Генератор превращает механическую энергию в электрическую."}, {"q": "С какой скоростью распространяются электромагнитные волны в вакууме?", "o": ["со скоростью света", "со скоростью звука", "мгновенно", "10 м/с"], "a": 0, "e": "c ≈ 300 000 км/с."}], "medium": [{"q": "Когда в катушке возникает индукционный ток?", "o": ["когда меняется магнитный поток через неё", "когда магнит лежит неподвижно внутри", "всегда", "только при нагреве"], "a": 0, "e": "Нужно изменение магнитного поля."}, {"q": "Что из перечисленного — электромагнитная волна?", "o": ["видимый свет", "звук", "волна на воде", "ультразвук"], "a": 0, "e": "Звук и волны на воде — механические."}, {"q": "Длина радиоволны частотой 100 МГц?", "o": ["3 м", "30 м", "0,3 м", "300 м"], "a": 0, "e": "λ = c / ν = 3·10⁸ / 10⁸ = 3 м."}], "hard": [{"q": "Почему трансформатор не работает на постоянном токе?", "o": ["постоянный ток не создаёт изменяющегося магнитного потока", "постоянный ток слишком слабый", "трансформатор плавится", "работает так же"], "a": 0, "e": "Индукция возникает только при изменении потока."}, {"q": "Что произойдёт, если магнит быстрее вдвигать в катушку?", "o": ["индукционный ток увеличится", "уменьшится", "не изменится", "исчезнет"], "a": 0, "e": "ЭДС индукции пропорциональна скорости изменения потока."}, {"q": "Расположите по возрастанию частоты: свет, радиоволны, рентген.", "o": ["радиоволны, свет, рентген", "свет, радиоволны, рентген", "рентген, свет, радиоволны", "радиоволны, рентген, свет"], "a": 0, "e": "Шкала электромагнитных волн: от длинных радиоволн до гамма-лучей."}], "olympiad": [{"q": "Магнит пролетает сквозь медное кольцо. Как кольцо действует на магнит?", "o": ["тормозит его (правило Ленца)", "ускоряет", "никак", "притягивает к центру всегда"], "a": 0, "e": "Индукционный ток создаёт поле, препятствующее изменению потока."}, {"q": "Радиолокатор принял отражённый сигнал через 0,2 мс. Расстояние до самолёта?", "o": ["30 км", "60 км", "300 км", "3 км"], "a": 0, "e": "s = c·t/2 = 3·10⁸ × 2·10⁻⁴ / 2 = 3·10⁴ м."}, {"q": "Почему в микроволновке нагревается еда, но не стеклянная тарелка?", "o": ["микроволны поглощаются в основном молекулами воды в еде", "стекло отражает всё тепло", "тарелка уже горячая", "микроволны не доходят до тарелки"], "a": 0, "e": "Энергия волн идёт на раскачивание полярных молекул воды."}]}}]}, {"title": "Атом и атомное ядро", "topics": [{"id": "p9-atom", "title": "Строение атома. Радиоактивность", "explain": "По модели Резерфорда атом состоит из маленького положительно заряженного ядра и электронов вокруг него. Ядро состоит из протонов (заряд +) и нейтронов (без заряда). Радиоактивность — самопроизвольный распад неустойчивых ядер с испусканием излучения: α (ядра гелия), β (электроны) и γ (электромагнитное излучение). Период полураспада — время, за которое распадается половина имеющихся ядер.", "formula": "N = N₀ · 2^(−t/T½)", "levels": {"easy": [{"q": "Что находится в центре атома?", "o": ["ядро", "электрон", "пустота", "фотон"], "a": 0, "e": "Ядро — крошечное, но в нём почти вся масса атома."}, {"q": "Из чего состоит атомное ядро?", "o": ["из протонов и нейтронов", "из электронов", "из фотонов", "из молекул"], "a": 0, "e": "Протоны и нейтроны называют нуклонами."}, {"q": "Какое излучение — поток ядер гелия?", "o": ["α-излучение", "β-излучение", "γ-излучение", "рентгеновское"], "a": 0, "e": "α-частица = 2 протона + 2 нейтрона."}], "medium": [{"q": "Период полураспада 10 дней. Какая доля ядер останется через 20 дней?", "o": ["1/4", "1/2", "0", "1/8"], "a": 0, "e": "Два периода: (1/2)² = 1/4."}, {"q": "Что задерживает α-частицы?", "o": ["лист бумаги", "только свинец", "ничто", "стекло толщиной 1 м"], "a": 0, "e": "α-частицы слабо проникают, но сильно ионизируют."}, {"q": "Опыт Резерфорда по рассеянию α-частиц показал, что…", "o": ["в атоме есть маленькое массивное ядро", "атом сплошной шар", "электроны в центре", "атом не имеет заряда"], "a": 0, "e": "Большинство частиц проходили насквозь, но некоторые сильно отклонялись."}], "hard": [{"q": "В ядре углерода-14 6 протонов. Сколько нейтронов?", "o": ["8", "6", "14", "20"], "a": 0, "e": "N = A − Z = 14 − 6 = 8."}, {"q": "Было 1600 ядер, T½ = 3 ч. Сколько останется через 12 ч?", "o": ["100", "400", "200", "0"], "a": 0, "e": "12/3 = 4 периода: 1600 / 16 = 100."}, {"q": "Какое излучение не отклоняется магнитным полем?", "o": ["γ-излучение", "α", "β", "все отклоняются"], "a": 0, "e": "γ-кванты не имеют заряда."}], "olympiad": [{"q": "При α-распаде ядро уменьшает массовое число и заряд на…", "o": ["4 и 2", "2 и 4", "1 и 1", "0 и 1"], "a": 0, "e": "Уходит ядро гелия ⁴₂He."}, {"q": "При β⁻-распаде заряд ядра…", "o": ["увеличивается на 1, массовое число не меняется", "уменьшается на 2", "не меняется", "уменьшается на 1"], "a": 0, "e": "Нейтрон превращается в протон и электрон."}, {"q": "Радиоуглеродный метод: в находке осталось 25% исходного ¹⁴C (T½ ≈ 5700 лет). Возраст?", "o": ["≈ 11 400 лет", "≈ 5700 лет", "≈ 22 800 лет", "≈ 1425 лет"], "a": 0, "e": "25% = (1/2)² — два периода полураспада."}]}}, {"id": "p9-nuclear", "title": "Ядерные реакции. Ядерная энергетика", "explain": "Ядерные силы удерживают протоны и нейтроны в ядре. При делении тяжёлых ядер (например, урана-235) после захвата нейтрона выделяется огромная энергия и новые нейтроны — так возникает цепная реакция. Управляемую цепную реакцию используют в атомных реакторах АЭС. Синтез лёгких ядер (термоядерная реакция) — источник энергии Солнца. Казахстан — один из крупнейших в мире производителей урана.", "formula": "При ядерных реакциях сохраняются суммарный заряд и массовое число; E = Δm · c²", "levels": {"easy": [{"q": "Какая реакция идёт в атомном реакторе?", "o": ["деление ядер урана", "синтез гелия", "горение угля", "окисление железа"], "a": 0, "e": "Реактор использует управляемую цепную реакцию деления."}, {"q": "Источник энергии Солнца?", "o": ["термоядерный синтез", "деление урана", "горение газа", "химические реакции"], "a": 0, "e": "В недрах Солнца водород превращается в гелий."}, {"q": "Какая частица вызывает деление урана в реакторе?", "o": ["нейтрон", "электрон", "фотон", "протон всегда"], "a": 0, "e": "Нейтрон не отталкивается ядром — легко в него проникает."}], "medium": [{"q": "Что такое цепная реакция?", "o": ["деление ядер, вызванное нейтронами от предыдущих делений", "реакция горения", "распад одного ядра", "реакция в батарейке"], "a": 0, "e": "Каждое деление даёт 2–3 нейтрона."}, {"q": "Зачем в реакторе нужны управляющие стержни?", "o": ["поглощать лишние нейтроны и регулировать реакцию", "охлаждать воду", "освещать реактор", "ускорять реакцию"], "a": 0, "e": "Например, стержни из бора или кадмия."}, {"q": "Какие величины сохраняются в ядерной реакции?", "o": ["заряд и массовое число", "только масса", "только скорость", "ничего"], "a": 0, "e": "Сумма верхних и нижних индексов слева и справа одинакова."}], "hard": [{"q": "Допишите реакцию: ¹⁴₇N + ⁴₂He → ¹⁷₈O + ?", "o": ["протон ¹₁H", "нейтрон", "электрон", "α-частица"], "a": 0, "e": "Заряд: 7 + 2 = 8 + 1; массы: 14 + 4 = 17 + 1."}, {"q": "Почему для деления используют нейтроны, а не протоны?", "o": ["нейтрон не заряжен и не отталкивается ядром", "нейтрон легче", "нейтрон быстрее света", "протоны радиоактивны"], "a": 0, "e": "Кулоновское отталкивание мешает протонам."}, {"q": "Главная экологическая проблема АЭС?", "o": ["хранение радиоактивных отходов", "выбросы CO₂", "шум", "расход кислорода"], "a": 0, "e": "Отходы остаются радиоактивными очень долго."}], "olympiad": [{"q": "Энергия, выделяемая при уменьшении массы на 1 г (c = 3·10⁸ м/с)?", "o": ["9·10¹³ Дж", "3·10⁸ Дж", "9·10¹⁶ Дж", "3·10⁵ Дж"], "a": 0, "e": "E = 0,001 × 9·10¹⁶ = 9·10¹³ Дж."}, {"q": "Что такое критическая масса?", "o": ["наименьшая масса делящегося вещества, при которой идёт цепная реакция", "масса реактора", "масса ядра урана", "масса нейтрона"], "a": 0, "e": "При меньшей массе слишком много нейтронов вылетает наружу."}, {"q": "Почему термоядерный синтез трудно осуществить на Земле?", "o": ["нужны огромные температуры (миллионы градусов), чтобы ядра преодолели отталкивание", "нет водорода", "он не выделяет энергию", "он идёт только в вакууме"], "a": 0, "e": "Ядра положительны и отталкиваются."}]}}]}, {"title": "Основы космологии", "topics": [{"id": "p9-cosmos", "title": "Строение Вселенной. Солнечная система", "explain": "Солнце — звезда, вокруг которой обращаются планеты земной группы (Меркурий, Венера, Земля, Марс) и планеты-гиганты (Юпитер, Сатурн, Уран, Нептун). Солнечная система находится в галактике Млечный Путь. Наблюдения показывают, что галактики удаляются друг от друга — Вселенная расширяется. По современным данным, возраст Вселенной около 13,8 млрд лет.", "check": true, "levels": {"easy": [{"q": "Как называется наша галактика?", "o": ["Млечный Путь", "Андромеда", "Солнечная", "Большая Медведица"], "a": 0, "e": "Солнце — одна из сотен миллиардов звёзд Млечного Пути."}, {"q": "Какие планеты относятся к земной группе?", "o": ["Меркурий, Венера, Земля, Марс", "Юпитер, Сатурн, Уран, Нептун", "Земля и Луна", "все восемь"], "a": 0, "e": "Планеты земной группы небольшие и каменистые."}, {"q": "Что такое звезда?", "o": ["раскалённый газовый шар, излучающий энергию", "холодное каменное тело", "спутник планеты", "комета"], "a": 0, "e": "Энергия звёзд — термоядерный синтез."}], "medium": [{"q": "Какой примерно возраст Вселенной по современным данным?", "o": ["около 13,8 млрд лет", "около 4,6 млрд лет", "около 6000 лет", "около 100 млн лет"], "a": 0, "e": "4,6 млрд лет — возраст Солнечной системы."}, {"q": "Что означает «Вселенная расширяется»?", "o": ["далёкие галактики удаляются друг от друга", "звёзды становятся больше", "Земля растёт", "Солнце удаляется от Земли"], "a": 0, "e": "Это показывает красное смещение в спектрах галактик."}, {"q": "Самая горячая планета Солнечной системы?", "o": ["Венера", "Меркурий", "Марс", "Юпитер"], "a": 0, "e": "Плотная атмосфера Венеры создаёт сильный парниковый эффект."}], "hard": [{"q": "Что такое астрономическая единица?", "o": ["среднее расстояние от Земли до Солнца (≈150 млн км)", "радиус Земли", "световой год", "расстояние до Луны"], "a": 0, "e": "1 а. е. ≈ 1,5·10⁸ км."}, {"q": "Почему звёзды разного цвета?", "o": ["у них разная температура поверхности", "они разного размера", "на разном расстоянии", "из-за атмосферы Земли только"], "a": 0, "e": "Голубые звёзды горячее красных."}, {"q": "Что такое чёрная дыра?", "o": ["область, из которой не может вырваться даже свет", "пустое место между звёздами", "погасшая планета", "тень Луны"], "a": 0, "e": "Гравитация там чрезвычайно сильна."}], "olympiad": [{"q": "Свет от звезды идёт до Земли 100 лет. Что мы видим?", "o": ["звезду такой, какой она была 100 лет назад", "звезду сейчас", "будущее звезды", "отражение Солнца"], "a": 0, "e": "Глядя вдаль, мы смотрим в прошлое."}, {"q": "Почему планеты-гиганты имеют много спутников и кольца?", "o": ["у них большая масса и сильное притяжение", "они ближе к Солнцу", "они холодные", "так случайно"], "a": 0, "e": "Сильная гравитация удерживает много тел."}, {"q": "Какой закон связывает скорость удаления галактики с расстоянием до неё?", "o": ["закон Хаббла", "закон Ома", "закон Архимеда", "закон Гука"], "a": 0, "e": "v = H·r — чем дальше галактика, тем быстрее удаляется."}]}}]}]}, "10": {"sections": [{"title": "Механика", "topics": [{"id": "p10-relative", "title": "Относительность движения. Закон сложения скоростей", "explain": "Скорость, путь и траектория зависят от выбора системы отсчёта. Классический закон сложения скоростей: скорость тела относительно неподвижной системы равна векторной сумме его скорости относительно подвижной системы и скорости самой подвижной системы. Например, скорость лодки относительно берега = скорость лодки относительно воды + скорость течения.", "formula": "v⃗ = v⃗₁ + v⃗₂ (векторно)", "levels": {"easy": [{"q": "Лодка плывёт по течению: 3 м/с относительно воды, течение 1 м/с. Скорость относительно берега?", "o": ["4 м/с", "2 м/с", "3 м/с", "1 м/с"], "a": 0, "e": "По течению скорости складываются."}, {"q": "Та же лодка плывёт против течения. Скорость относительно берега?", "o": ["2 м/с", "4 м/с", "3 м/с", "0"], "a": 0, "e": "3 − 1 = 2 м/с."}, {"q": "Траектория точки обода колеса велосипеда относительно рамы — это…", "o": ["окружность", "прямая", "циклоида", "точка"], "a": 0, "e": "Относительно рамы колесо просто вращается. Относительно дороги — циклоида."}], "medium": [{"q": "Пловец плывёт перпендикулярно течению со скоростью 0,8 м/с, течение 0,6 м/с. Скорость относительно берега?", "o": ["1 м/с", "1,4 м/с", "0,2 м/с", "0,48 м/с"], "a": 0, "e": "√(0,8² + 0,6²) = 1 м/с."}, {"q": "Ширина реки 80 м. За какое время пловец из предыдущей задачи переплывёт реку?", "o": ["100 с", "80 с", "133 с", "57 с"], "a": 0, "e": "Поперёк реки скорость 0,8 м/с: 80 / 0,8 = 100 с."}, {"q": "На сколько метров снесёт этого пловца течением?", "o": ["60 м", "80 м", "100 м", "48 м"], "a": 0, "e": "0,6 × 100 = 60 м."}], "hard": [{"q": "Поезд идёт со скоростью 20 м/с, пассажир идёт по вагону к хвосту со скоростью 2 м/с. Его скорость относительно земли?", "o": ["18 м/с", "22 м/с", "20 м/с", "2 м/с"], "a": 0, "e": "Направления противоположны: 20 − 2 = 18 м/с."}, {"q": "Дождь падает вертикально со скоростью 8 м/с, автобус едет 6 м/с. Под каким углом к вертикали следы капель на боковом стекле? (tg)", "o": ["tg α = 0,75 (≈37°)", "45°", "tg α = 4/3 (≈53°)", "0°"], "a": 0, "e": "Относительно автобуса капли летят назад: tg α = 6/8."}, {"q": "Катер проходит расстояние между пристанями по течению за 2 ч, против — за 3 ч. Во сколько раз скорость катера больше скорости течения?", "o": ["в 5 раз", "в 2 раза", "в 3 раза", "в 1,5 раза"], "a": 0, "e": "(v+u)·2 = (v−u)·3 → v = 5u."}], "olympiad": [{"q": "За сколько плот проплывёт расстояние между пристанями из предыдущей задачи (2 ч по течению, 3 ч против)?", "o": ["12 ч", "5 ч", "6 ч", "2,5 ч"], "a": 0, "e": "v = 5u, s = (6u)·2 = 12u; плот плывёт со скоростью u: t = 12 ч."}, {"q": "Под каким углом к берегу должен грести пловец (v = 1 м/с, течение 0,5 м/с), чтобы переплыть реку строго поперёк?", "o": ["под 60° к берегу против течения", "под 30° к берегу", "перпендикулярно берегу", "под 45°"], "a": 0, "e": "cos α = u/v = 0,5 → α = 60° к берегу, нос направлен против течения."}, {"q": "Два автомобиля едут по перпендикулярным дорогам со скоростями 30 и 40 км/ч. Скорость одного относительно другого?", "o": ["50 км/ч", "70 км/ч", "10 км/ч", "35 км/ч"], "a": 0, "e": "√(30² + 40²) = 50 км/ч."}]}}, {"id": "p10-forces", "title": "Силы в механике. Движение по наклонной плоскости", "explain": "В механике действуют силы тяжести, упругости (в том числе реакции опоры и натяжения нити) и трения. Для решения задач рисуют все силы, выбирают оси и записывают второй закон Ньютона в проекциях. На наклонной плоскости с углом α удобно направить ось вдоль плоскости: составляющая силы тяжести вдоль плоскости mg·sin α, сила давления на плоскость mg·cos α.", "formula": "ma = mg·sin α − μ·mg·cos α (скольжение вниз);  Fтр = μN", "levels": {"easy": [{"q": "Как направлена сила реакции опоры?", "o": ["перпендикулярно поверхности опоры", "вертикально вниз", "вдоль поверхности", "к центру Земли"], "a": 0, "e": "Сила нормальной реакции перпендикулярна поверхности."}, {"q": "Какая составляющая силы тяжести тянет брусок вниз вдоль наклонной плоскости?", "o": ["mg·sin α", "mg·cos α", "mg", "mg·tg α"], "a": 0, "e": "Вдоль плоскости — mg sin α."}, {"q": "Сила натяжения нити направлена…", "o": ["вдоль нити", "вниз", "перпендикулярно нити", "к центру Земли"], "a": 0, "e": "Нить может только тянуть."}], "medium": [{"q": "Брусок массой 2 кг лежит на плоскости с углом 30°. Сила давления на плоскость (g = 10)?", "o": ["≈ 17,3 Н", "10 Н", "20 Н", "11,5 Н"], "a": 0, "e": "N = mg cos 30° = 20 × 0,866 ≈ 17,3 Н."}, {"q": "Ускорение бруска, скользящего без трения по плоскости с углом 30° (g = 10)?", "o": ["5 м/с²", "10 м/с²", "8,66 м/с²", "2,5 м/с²"], "a": 0, "e": "a = g sin α = 10 × 0,5."}, {"q": "При каком коэффициенте трения брусок покоится на плоскости с углом α (на пределе)?", "o": ["μ = tg α", "μ = sin α", "μ = cos α", "μ = 1"], "a": 0, "e": "mg sin α = μ mg cos α."}], "hard": [{"q": "Брусок скользит по плоскости с углом 30°, μ = 0,2. Ускорение (g = 10, cos 30° ≈ 0,87)?", "o": ["≈ 3,3 м/с²", "5 м/с²", "≈ 6,7 м/с²", "≈ 1,7 м/с²"], "a": 0, "e": "a = g(sin α − μ cos α) = 10(0,5 − 0,174) ≈ 3,3 м/с²."}, {"q": "Какую силу надо приложить вдоль плоскости (30°, без трения), чтобы равномерно тянуть вверх груз 10 кг (g = 10)?", "o": ["50 Н", "100 Н", "87 Н", "10 Н"], "a": 0, "e": "F = mg sin α = 100 × 0,5."}, {"q": "Автомобиль проходит поворот радиусом 50 м, μ = 0,5 (g = 10). Максимальная скорость без заноса?", "o": ["≈ 15,8 м/с", "25 м/с", "5 м/с", "50 м/с"], "a": 0, "e": "μmg = mv²/R → v = √(μgR) = √250 ≈ 15,8 м/с."}], "olympiad": [{"q": "Брусок толкнули вверх по плоскости (30°, μ = 0) со скоростью 10 м/с. Какой путь он пройдёт до остановки (g = 10)?", "o": ["10 м", "5 м", "20 м", "8,7 м"], "a": 0, "e": "a = g sin α = 5; s = v²/(2a) = 100/10 = 10 м."}, {"q": "Груз на нити вращается в вертикальной плоскости. Где натяжение нити максимально?", "o": ["в нижней точке", "в верхней точке", "одинаково везде", "в горизонтальном положении"], "a": 0, "e": "Внизу натяжение должно и уравновесить mg, и создать центростремительное ускорение."}, {"q": "Минимальная скорость в верхней точке «мёртвой петли» радиусом 10 м (g = 10)?", "o": ["10 м/с", "√20 м/с", "20 м/с", "0"], "a": 0, "e": "В верхней точке mg = mv²/R → v = √(gR) = 10 м/с."}]}}, {"id": "p10-statics", "title": "Статика. Условия равновесия твёрдого тела", "explain": "Тело находится в равновесии, если выполнены два условия: векторная сумма всех сил равна нулю (нет поступательного ускорения) и сумма моментов сил относительно любой оси равна нулю (нет вращения). Равновесие бывает устойчивым (центр тяжести в самом низком положении), неустойчивым и безразличным. Чем ниже центр тяжести и шире площадь опоры, тем устойчивее тело.", "formula": "ΣF⃗ = 0;  ΣM = 0 (M = F·d)", "levels": {"easy": [{"q": "Первое условие равновесия:", "o": ["сумма сил равна нулю", "сумма скоростей равна нулю", "масса равна нулю", "сила тяжести равна нулю"], "a": 0, "e": "Иначе тело получит ускорение."}, {"q": "Какое равновесие у шарика на дне ямки?", "o": ["устойчивое", "неустойчивое", "безразличное", "никакое"], "a": 0, "e": "При отклонении шарик возвращается."}, {"q": "Почему у гоночных машин низкая посадка?", "o": ["низкий центр тяжести повышает устойчивость", "так быстрее", "меньше трение", "легче руль"], "a": 0, "e": "Низкий центр тяжести — меньше риск опрокидывания."}], "medium": [{"q": "Балка 4 м, вес 400 Н лежит на двух опорах по краям. Сила реакции каждой опоры?", "o": ["200 Н", "400 Н", "100 Н", "800 Н"], "a": 0, "e": "Центр тяжести посередине — нагрузка делится поровну."}, {"q": "На балке (на опорах по краям) груз 600 Н на расстоянии 1 м от левой опоры, длина 3 м. Реакция правой опоры (вес балки не учитывать)?", "o": ["200 Н", "400 Н", "300 Н", "600 Н"], "a": 0, "e": "Моменты относительно левой опоры: R₂ × 3 = 600 × 1."}, {"q": "Какое равновесие у шара на горизонтальном столе?", "o": ["безразличное", "устойчивое", "неустойчивое", "никакое"], "a": 0, "e": "При смещении он остаётся в равновесии в новом положении."}], "hard": [{"q": "Лестница стоит у гладкой стены. Что удерживает её от скольжения?", "o": ["сила трения о пол", "сила трения о стену", "вес лестницы", "ничто"], "a": 0, "e": "Гладкая стена не даёт трения, держит только трение о пол."}, {"q": "Груз 10 кг подвешен на двух нитях, каждая под углом 60° к вертикали. Натяжение каждой (g = 10)?", "o": ["100 Н", "50 Н", "200 Н", "87 Н"], "a": 0, "e": "2T cos 60° = mg → T = 100 / (2 × 0,5) = 100 Н."}, {"q": "Почему трудно удержать длинный шест горизонтально за один конец?", "o": ["момент силы тяжести шеста велик из-за большого плеча", "шест легкий", "из-за трения о воздух", "из-за давления воздуха"], "a": 0, "e": "Центр тяжести далеко от руки — нужен большой момент."}], "olympiad": [{"q": "Однородный брус выступает за край стола на 1/3 длины. Масса 3 кг. Какой груз можно положить на выступающий конец, чтобы брус не опрокинулся?", "o": ["1,5 кг", "0,5 кг", "1 кг", "3 кг"], "a": 0, "e": "Ось — край стола. Центр тяжести бруса на L/6 левее края, груз на L/3 правее: 3 × L/6 = m × L/3 → m = 1,5 кг."}, {"q": "Два одинаковых кирпича длиной L кладут на край стола со сдвигом. На сколько верхний кирпич может выступать за край стола?", "o": ["3L/4", "L/2", "L", "L/4"], "a": 0, "e": "Верхний сдвигаем на L/2 относительно нижнего, общий центр тяжести двух кирпичей должен быть над краем стола — нижний выступает на L/4. Итого L/2 + L/4 = 3L/4."}, {"q": "Почему канатоходец держит длинный шест?", "o": ["увеличивается момент инерции — легче сохранять равновесие", "шест легче веса тела", "чтобы опираться на воздух", "для красоты"], "a": 0, "e": "Длинный шест замедляет опрокидывание и позволяет корректировать положение."}]}}, {"id": "p10-hydro", "title": "Гидро- и аэродинамика. Уравнение Бернулли", "explain": "При течении жидкости через трубу переменного сечения объём, протекающий за единицу времени, одинаков: в узком месте скорость больше. Уравнение Бернулли: там, где скорость потока больше, давление меньше. Это объясняет подъёмную силу крыла самолёта, работу пульверизатора и то, почему два корабля, идущие рядом, притягиваются.", "formula": "S₁v₁ = S₂v₂;  p + ρv²/2 + ρgh = const", "check": true, "levels": {"easy": [{"q": "В узком месте трубы скорость потока…", "o": ["больше", "меньше", "такая же", "равна нулю"], "a": 0, "e": "Через любое сечение за секунду проходит одинаковый объём."}, {"q": "По Бернулли, где скорость потока больше, давление…", "o": ["меньше", "больше", "такое же", "равно нулю"], "a": 0, "e": "Сумма p + ρv²/2 постоянна вдоль линии тока."}, {"q": "Благодаря чему возникает подъёмная сила крыла самолёта?", "o": ["разнице давлений над и под крылом", "силе тяжести", "реактивной струе", "магнитному полю"], "a": 0, "e": "Над крылом поток быстрее — давление ниже."}], "medium": [{"q": "Вода течёт по трубе сечением 10 см² со скоростью 2 м/с, затем в сужение 5 см². Скорость в сужении?", "o": ["4 м/с", "1 м/с", "2 м/с", "10 м/с"], "a": 0, "e": "S₁v₁ = S₂v₂ → v₂ = 2 × 10 / 5."}, {"q": "Почему опасно стоять близко к краю платформы при проходе скоростного поезда?", "o": ["между поездом и человеком быстрый поток воздуха — давление ниже, человека «затягивает»", "поезд притягивает магнитом", "из-за шума", "из-за вибрации"], "a": 0, "e": "Следствие уравнения Бернулли."}, {"q": "Если подуть между двумя листами бумаги, они…", "o": ["сблизятся", "разойдутся", "не сдвинутся", "упадут"], "a": 0, "e": "Давление в быстром потоке между листами уменьшается."}], "hard": [{"q": "Объём воды, вытекающей из крана сечением 1 см² со скоростью 2 м/с за 10 с?", "o": ["2 л", "20 л", "0,2 л", "200 л"], "a": 0, "e": "V = S·v·t = 10⁻⁴ × 2 × 10 = 2·10⁻³ м³."}, {"q": "С какой скоростью вытекает вода из отверстия на глубине 5 м под поверхностью (g = 10)?", "o": ["10 м/с", "5 м/с", "50 м/с", "7 м/с"], "a": 0, "e": "Формула Торричелли: v = √(2gh) = 10 м/с."}, {"q": "Почему крыши иногда срывает ураганом?", "o": ["над крышей быстрый поток — давление ниже, чем внутри дома", "ветер давит сверху", "крыша нагревается", "из-за дождя"], "a": 0, "e": "Разность давлений поднимает крышу."}], "olympiad": [{"q": "Почему мяч, закрученный при ударе, летит по дуге (эффект Магнуса)?", "o": ["с одной стороны поток воздуха быстрее — давление меньше, возникает боковая сила", "из-за силы тяжести", "из-за ветра всегда", "мяч несимметричен"], "a": 0, "e": "Вращение меняет скорость обтекания с разных сторон."}, {"q": "Скорость в широкой части трубы 1 м/с, в узкой 3 м/с. Разность давлений (ρ = 1000 кг/м³, трубка горизонтальна)?", "o": ["4000 Па", "2000 Па", "9000 Па", "1000 Па"], "a": 0, "e": "Δp = ρ(v₂² − v₁²)/2 = 1000 × 8 / 2 = 4000 Па."}, {"q": "Два корабля, идущие параллельно близко друг к другу, …", "o": ["притягиваются", "отталкиваются", "не взаимодействуют", "тонут"], "a": 0, "e": "Вода между ними течёт быстрее, давление там меньше."}]}}]}, {"title": "Молекулярная физика и термодинамика", "topics": [{"id": "p10-mkt", "title": "Основы молекулярно-кинетической теории", "explain": "МКТ: вещество состоит из частиц, частицы хаотично движутся и взаимодействуют. Количество вещества ν измеряется в молях; в 1 моле содержится число Авогадро частиц Nₐ ≈ 6,02·10²³. Молярная масса M — масса одного моля (для воды 0,018 кг/моль). Температура — мера средней кинетической энергии хаотического движения молекул; абсолютная температура T = t + 273 (в кельвинах).", "formula": "ν = m / M = N / Nₐ;  E = (3/2)·k·T;  T = t + 273", "levels": {"easy": [{"q": "Число Авогадро примерно равно…", "o": ["6,02·10²³ моль⁻¹", "3·10⁸", "9,8", "1,6·10⁻¹⁹"], "a": 0, "e": "Столько частиц в одном моле."}, {"q": "Единица количества вещества?", "o": ["моль", "килограмм", "кельвин", "литр"], "a": 0, "e": "Моль — одна из основных единиц СИ."}, {"q": "27 °C — это в кельвинах…", "o": ["300 К", "273 К", "246 К", "27 К"], "a": 0, "e": "T = 27 + 273 = 300 К."}], "medium": [{"q": "Молярная масса воды 18 г/моль. Сколько молей в 36 г воды?", "o": ["2 моль", "18 моль", "0,5 моль", "648 моль"], "a": 0, "e": "ν = 36 / 18 = 2 моль."}, {"q": "Сколько молекул в 2 моль вещества?", "o": ["≈ 1,2·10²⁴", "≈ 6·10²³", "≈ 3·10²³", "2"], "a": 0, "e": "N = 2 × 6,02·10²³."}, {"q": "Как изменится средняя кинетическая энергия молекул газа, если абсолютная температура вырастет вдвое?", "o": ["вырастет вдвое", "в 4 раза", "не изменится", "уменьшится"], "a": 0, "e": "E ~ T."}], "hard": [{"q": "Молярная масса кислорода O₂?", "o": ["0,032 кг/моль", "0,016 кг/моль", "32 кг/моль", "0,008 кг/моль"], "a": 0, "e": "Атомная масса O — 16, молекула из двух атомов."}, {"q": "Сколько молекул в 1 г водорода H₂ (M = 2 г/моль)?", "o": ["≈ 3·10²³", "≈ 6·10²³", "≈ 1,2·10²⁴", "≈ 10²³"], "a": 0, "e": "ν = 0,5 моль → N = 0,5 × 6·10²³."}, {"q": "Что такое абсолютный нуль?", "o": ["0 К ≈ −273 °C — наименьшая возможная температура", "0 °C", "температура в космосе 0 °C", "температура замерзания воды"], "a": 0, "e": "При абсолютном нуле прекращается тепловое движение (в классической теории)."}], "olympiad": [{"q": "Оцените массу одной молекулы воды (M = 18 г/моль).", "o": ["≈ 3·10⁻²⁶ кг", "≈ 3·10⁻²³ кг", "≈ 18·10⁻³ кг", "≈ 10⁻¹⁰ кг"], "a": 0, "e": "m₀ = M / Nₐ = 0,018 / 6·10²³ = 3·10⁻²⁶ кг."}, {"q": "Во сколько раз средняя квадратичная скорость молекул водорода больше, чем кислорода, при одной температуре?", "o": ["в 4 раза", "в 16 раз", "в 2 раза", "одинаковы"], "a": 0, "e": "v ~ 1/√M: √(32/2) = 4."}, {"q": "Оцените объём, приходящийся на одну молекулу воды (ρ = 1000 кг/м³).", "o": ["≈ 3·10⁻²⁹ м³", "≈ 3·10⁻²⁶ м³", "≈ 10⁻¹⁰ м³", "≈ 1 см³"], "a": 0, "e": "V₀ = m₀/ρ = 3·10⁻²⁶ / 1000 = 3·10⁻²⁹ м³ (размер ~3·10⁻¹⁰ м)."}]}}, {"id": "p10-gas", "title": "Идеальный газ. Уравнение состояния. Газовые законы", "explain": "Идеальный газ — модель газа, в которой молекулы считают точками, взаимодействующими только при столкновениях. Его состояние описывает уравнение Менделеева–Клапейрона. Изопроцессы: изотермический (T = const, закон Бойля–Мариотта pV = const), изобарный (p = const, V/T = const), изохорный (V = const, p/T = const). Температуру в газовых законах всегда берут в кельвинах.", "formula": "pV = νRT (R = 8,31 Дж/(моль·К));  p₁V₁/T₁ = p₂V₂/T₂", "levels": {"easy": [{"q": "Изотермический процесс — это процесс при постоянной…", "o": ["температуре", "давлении", "объёме", "массе только"], "a": 0, "e": "«Термо» — температура."}, {"q": "Закон Бойля–Мариотта:", "o": ["pV = const при T = const", "V/T = const", "p/T = const", "pT = const"], "a": 0, "e": "При постоянной температуре давление обратно пропорционально объёму."}, {"q": "Чему равна универсальная газовая постоянная?", "o": ["8,31 Дж/(моль·К)", "6,02·10²³", "9,8 Н/кг", "1,38·10⁻²³ Дж/К"], "a": 0, "e": "R = k·Nₐ."}], "medium": [{"q": "Газ изотермически сжали вдвое. Давление…", "o": ["увеличилось вдвое", "уменьшилось вдвое", "не изменилось", "выросло в 4 раза"], "a": 0, "e": "pV = const."}, {"q": "Газ нагрели при постоянном объёме от 300 К до 600 К. Давление…", "o": ["выросло вдвое", "не изменилось", "уменьшилось вдвое", "выросло в 4 раза"], "a": 0, "e": "p/T = const."}, {"q": "Почему нельзя нагревать закрытый баллончик?", "o": ["давление газа растёт с температурой и баллон может взорваться", "он плавится", "газ исчезает", "давление падает"], "a": 0, "e": "Изохорное нагревание повышает давление."}], "hard": [{"q": "Давление 2 моль газа в сосуде 0,05 м³ при 300 К?", "o": ["≈ 99,7 кПа", "≈ 10 кПа", "≈ 1 МПа", "≈ 50 кПа"], "a": 0, "e": "p = νRT/V = 2 × 8,31 × 300 / 0,05 ≈ 99 720 Па."}, {"q": "Газ при 27 °C занимал 6 л. При постоянном давлении его нагрели до 127 °C. Новый объём?", "o": ["8 л", "28 л", "6 л", "4,5 л"], "a": 0, "e": "V₂ = V₁T₂/T₁ = 6 × 400/300 = 8 л."}, {"q": "Сколько молей газа в 22,4 л при нормальных условиях (0 °C, 101,3 кПа)?", "o": ["1 моль", "22,4 моль", "0,5 моль", "2 моль"], "a": 0, "e": "Молярный объём газа при н. у. ≈ 22,4 л."}], "olympiad": [{"q": "Пузырёк воздуха поднимается со дна озера глубиной 10 м к поверхности. Во сколько раз увеличится его объём (T постоянна, p₀ = 100 кПа)?", "o": ["в 2 раза", "в 10 раз", "в 1,1 раза", "не изменится"], "a": 0, "e": "На глубине 10 м давление ≈ 200 кПа, у поверхности 100 кПа."}, {"q": "Плотность воздуха при 0 °C и 101 кПа (M = 0,029 кг/моль)?", "o": ["≈ 1,29 кг/м³", "≈ 0,029 кг/м³", "≈ 12,9 кг/м³", "≈ 1000 кг/м³"], "a": 0, "e": "ρ = pM/(RT) = 101 000 × 0,029 / (8,31 × 273) ≈ 1,29."}, {"q": "Из баллона выпустили половину газа, а температуру (в К) уменьшили вдвое. Давление…", "o": ["уменьшилось в 4 раза", "уменьшилось вдвое", "не изменилось", "увеличилось"], "a": 0, "e": "p ~ νT: (1/2)·(1/2) = 1/4."}]}}, {"id": "p10-thermo1", "title": "Внутренняя энергия газа. Первый закон термодинамики", "explain": "Внутренняя энергия идеального одноатомного газа зависит только от температуры. Газ совершает работу при расширении: A = pΔV при постоянном давлении. Первый закон термодинамики — закон сохранения энергии для тепловых процессов: количество теплоты, переданное газу, идёт на изменение его внутренней энергии и на совершение газом работы. Адиабатный процесс — без теплообмена.", "formula": "Q = ΔU + A;  U = (3/2)νRT (одноатомный газ);  A = pΔV", "levels": {"easy": [{"q": "Первый закон термодинамики:", "o": ["Q = ΔU + A", "Q = A − ΔU", "U = mgh", "pV = νRT"], "a": 0, "e": "Теплота идёт на изменение внутренней энергии и работу газа."}, {"q": "Что такое адиабатный процесс?", "o": ["процесс без теплообмена с окружающей средой", "при постоянной температуре", "при постоянном объёме", "при постоянном давлении"], "a": 0, "e": "Q = 0."}, {"q": "Работа газа при постоянном объёме?", "o": ["равна нулю", "максимальна", "отрицательна", "равна pV"], "a": 0, "e": "Нет изменения объёма — нет работы."}], "medium": [{"q": "Газ получил 500 Дж и совершил работу 200 Дж. Изменение внутренней энергии?", "o": ["+300 Дж", "+700 Дж", "−300 Дж", "200 Дж"], "a": 0, "e": "ΔU = Q − A = 300 Дж."}, {"q": "Газ при постоянном давлении 100 кПа расширился на 0,02 м³. Работа газа?", "o": ["2000 Дж", "200 Дж", "20 Дж", "5 МДж"], "a": 0, "e": "A = pΔV = 10⁵ × 0,02."}, {"q": "Газ изотермически расширяется. Как связаны Q и A?", "o": ["Q = A", "Q = 0", "A = 0", "Q = −A"], "a": 0, "e": "При T = const ΔU = 0."}], "hard": [{"q": "Внутренняя энергия 2 моль одноатомного газа при 300 К?", "o": ["≈ 7,5 кДж", "≈ 5 кДж", "≈ 2,5 кДж", "≈ 15 кДж"], "a": 0, "e": "U = 1,5 × 2 × 8,31 × 300 ≈ 7479 Дж."}, {"q": "При адиабатном сжатии газа его температура…", "o": ["растёт", "падает", "не меняется", "становится 0 К"], "a": 0, "e": "Q = 0, A < 0 (работу совершают над газом) → ΔU > 0."}, {"q": "Почему воздух, выходящий из проколотой шины, холодный?", "o": ["газ быстро (почти адиабатно) расширяется и совершает работу за счёт внутренней энергии", "шина холодная", "из-за ветра", "воздух внутри всегда холодный"], "a": 0, "e": "Адиабатное расширение охлаждает газ."}], "olympiad": [{"q": "Одноатомному газу при постоянном давлении сообщили 500 Дж. Какая работа совершена газом?", "o": ["200 Дж", "300 Дж", "500 Дж", "0"], "a": 0, "e": "При p = const: A = νRΔT, ΔU = 1,5νRΔT, Q = 2,5νRΔT → A = 0,4Q = 200 Дж."}, {"q": "Нагревание газа при постоянном давлении требует больше теплоты, чем при постоянном объёме, потому что…", "o": ["часть теплоты идёт на работу расширения", "газ становится тяжелее", "давление растёт", "это не так"], "a": 0, "e": "Cp > Cv."}, {"q": "Газ совершил цикл и вернулся в исходное состояние. Чему равно изменение внутренней энергии за цикл?", "o": ["нулю", "работе газа", "полученной теплоте", "отрицательно"], "a": 0, "e": "U — функция состояния."}]}}, {"id": "p10-engines", "title": "Тепловые машины. Второй закон термодинамики", "explain": "Тепловая машина получает теплоту Q₁ от нагревателя, совершает работу и отдаёт теплоту Q₂ холодильнику. Второй закон термодинамики: невозможно полностью превратить теплоту в работу; теплота сама переходит только от горячего тела к холодному. Наибольший возможный КПД у идеальной машины Карно, он зависит только от температур нагревателя и холодильника.", "formula": "η = (Q₁ − Q₂) / Q₁;  ηmax = (T₁ − T₂) / T₁", "levels": {"easy": [{"q": "Может ли теплота сама переходить от холодного тела к горячему?", "o": ["нет", "да", "только летом", "только в вакууме"], "a": 0, "e": "Это одна из формулировок второго закона."}, {"q": "Из каких частей состоит тепловая машина?", "o": ["нагреватель, рабочее тело, холодильник", "только двигатель", "мотор и колёса", "топливо и бак"], "a": 0, "e": "Это общая схема."}, {"q": "КПД идеальной машины Карно зависит от…", "o": ["температур нагревателя и холодильника", "вида топлива", "массы машины", "цвета"], "a": 0, "e": "ηmax = (T₁ − T₂)/T₁."}], "medium": [{"q": "Машина получает 1000 Дж и отдаёт 600 Дж холодильнику. КПД?", "o": ["40%", "60%", "160%", "1,67%"], "a": 0, "e": "(1000 − 600) / 1000."}, {"q": "T₁ = 500 К, T₂ = 300 К. Максимальный КПД?", "o": ["40%", "60%", "67%", "100%"], "a": 0, "e": "(500 − 300)/500."}, {"q": "Почему нельзя построить вечный двигатель второго рода?", "o": ["нельзя превратить всю теплоту в работу без холодильника", "нет подходящих материалов", "это запрещено законом страны", "можно"], "a": 0, "e": "Это следует из второго закона."}], "hard": [{"q": "Нагреватель 527 °C, холодильник 27 °C. Максимальный КПД?", "o": ["62,5%", "95%", "50%", "37,5%"], "a": 0, "e": "T₁ = 800 К, T₂ = 300 К: 500/800."}, {"q": "Холодильник (бытовой) переносит теплоту от холодной камеры в комнату. Нарушает ли это второй закон?", "o": ["нет, для этого совершается работа компрессора", "да", "только летом", "это невозможно"], "a": 0, "e": "Без работы такой перенос невозможен."}, {"q": "КПД машины 30%, она совершила работу 600 Дж. Сколько теплоты отдано холодильнику?", "o": ["1400 Дж", "2000 Дж", "420 Дж", "1800 Дж"], "a": 0, "e": "Q₁ = 600/0,3 = 2000 Дж; Q₂ = 2000 − 600."}], "olympiad": [{"q": "Как сильнее повысить КПД Карно: поднять T₁ на 100 К или понизить T₂ на 100 К (T₁ = 600 К, T₂ = 300 К)?", "o": ["понизить T₂", "поднять T₁", "одинаково", "никак"], "a": 0, "e": "(700−300)/700 ≈ 57%; (600−200)/600 ≈ 67%."}, {"q": "Что такое энтропия (упрощённо)?", "o": ["мера беспорядка; в изолированной системе она не убывает", "энергия движения", "температура газа", "работа машины"], "a": 0, "e": "Это другая формулировка второго закона."}, {"q": "Почему КПД реальных двигателей меньше КПД Карно?", "o": ["есть трение, теплопотери и необратимые процессы", "у них другой холодильник", "они работают на бензине", "КПД больше Карно"], "a": 0, "e": "Цикл Карно — идеальный предел."}]}}]}, {"title": "Электростатика", "topics": [{"id": "p10-coulomb", "title": "Электрический заряд. Закон Кулона", "explain": "Электрический заряд дискретен: любой заряд кратен элементарному e = 1,6·10⁻¹⁹ Кл. В замкнутой системе алгебраическая сумма зарядов сохраняется. Закон Кулона: два точечных заряда взаимодействуют с силой, пропорциональной произведению зарядов и обратно пропорциональной квадрату расстояния; k = 9·10⁹ Н·м²/Кл². В диэлектрике с проницаемостью ε сила уменьшается в ε раз.", "formula": "F = k·|q₁|·|q₂| / (ε·r²)", "levels": {"easy": [{"q": "Элементарный заряд равен…", "o": ["1,6·10⁻¹⁹ Кл", "9·10⁹ Кл", "6·10²³ Кл", "1 Кл"], "a": 0, "e": "Заряд электрона по модулю."}, {"q": "Как изменится сила Кулона, если расстояние уменьшить вдвое?", "o": ["увеличится в 4 раза", "увеличится вдвое", "уменьшится в 4 раза", "не изменится"], "a": 0, "e": "F ~ 1/r²."}, {"q": "Закон сохранения заряда:", "o": ["в замкнутой системе сумма зарядов постоянна", "заряд всегда положителен", "заряды исчезают при касании", "заряд растёт со временем"], "a": 0, "e": "Заряды только перераспределяются."}], "medium": [{"q": "Два заряда по 1 мкКл на расстоянии 0,1 м. Сила взаимодействия (k = 9·10⁹)?", "o": ["0,9 Н", "9 Н", "0,09 Н", "90 Н"], "a": 0, "e": "F = 9·10⁹ × 10⁻¹² / 0,01 = 0,9 Н."}, {"q": "Заряды поместили в воду (ε = 81). Сила взаимодействия…", "o": ["уменьшится в 81 раз", "увеличится в 81 раз", "не изменится", "уменьшится в 9 раз"], "a": 0, "e": "Диэлектрик ослабляет взаимодействие."}, {"q": "Сколько электронов «не хватает» телу с зарядом +3,2·10⁻¹⁹ Кл?", "o": ["2", "1", "3,2", "20"], "a": 0, "e": "N = q/e = 2."}], "hard": [{"q": "Два одинаковых шарика с зарядами +5 нКл и −1 нКл соприкоснули и развели на прежнее расстояние. Как изменилась сила?", "o": ["уменьшилась в 1,25 раза и стала отталкиванием", "не изменилась", "увеличилась в 1,25 раза", "стала нулевой"], "a": 0, "e": "После касания по +2 нКл: F' ~ 4, было ~ 5 (притяжение)."}, {"q": "Во сколько раз электрическая сила между протоном и электроном больше гравитационной?", "o": ["примерно в 10³⁹ раз", "в 10 раз", "одинаковы", "в 1000 раз"], "a": 0, "e": "Гравитация несравнимо слабее электрического взаимодействия."}, {"q": "Заряды +q и +4q закреплены на расстоянии 30 см. Где поместить третий заряд, чтобы он был в равновесии?", "o": ["10 см от +q между ними", "15 см посередине", "20 см от +q", "снаружи от +4q"], "a": 0, "e": "kq/x² = 4kq/(0,3 − x)² → 0,3 − x = 2x → x = 0,1 м."}], "olympiad": [{"q": "Два шарика массой по 1 г висят на нитях из одной точки и, зарядившись одинаково, разошлись. Почему угол меньше при большей массе?", "o": ["сила тяжести сильнее, а кулоновская сила та же", "заряд меньше у тяжёлых", "нити короче", "угол не зависит от массы"], "a": 0, "e": "tg α = F/(mg)."}, {"q": "Что будет с силой взаимодействия, если каждый заряд и расстояние увеличить вдвое?", "o": ["не изменится", "увеличится в 2 раза", "увеличится в 4 раза", "уменьшится вдвое"], "a": 0, "e": "(2·2)/(2²) = 1."}, {"q": "Почему точечный заряд в законе Кулона — модель?", "o": ["размеры тел малы по сравнению с расстоянием между ними", "заряд не имеет размера никогда", "так проще вычислять массу", "это реальный объект"], "a": 0, "e": "Закон точно выполняется для точечных и сферически симметричных зарядов."}]}}, {"id": "p10-field", "title": "Напряжённость и потенциал электрического поля", "explain": "Электрическое поле характеризуют напряжённостью E — силой, действующей на единичный положительный заряд (Н/Кл = В/м). Поле точечного заряда убывает как 1/r². Потенциал φ — энергетическая характеристика поля (вольт), работа поля при перемещении заряда равна q(φ₁ − φ₂). В однородном поле E = U/d. Внутри проводника поле равно нулю — на этом основана электростатическая защита.", "formula": "E = F/q;  E = k·q/r²;  A = q·U;  E = U/d", "levels": {"easy": [{"q": "Единица напряжённости поля?", "o": ["В/м (Н/Кл)", "В", "Кл", "Ф"], "a": 0, "e": "E = F/q."}, {"q": "Чему равна напряжённость поля внутри металлического проводника в равновесии?", "o": ["нулю", "бесконечности", "как снаружи", "E = kq/r²"], "a": 0, "e": "Заряды располагаются на поверхности и компенсируют поле внутри."}, {"q": "Единица потенциала?", "o": ["вольт", "ампер", "фарад", "ньютон"], "a": 0, "e": "φ = W/q."}], "medium": [{"q": "На заряд 2 мкКл поле действует силой 0,01 Н. Напряжённость?", "o": ["5000 Н/Кл", "0,02 Н/Кл", "200 Н/Кл", "5 Н/Кл"], "a": 0, "e": "E = 0,01 / 2·10⁻⁶ = 5000."}, {"q": "Между пластинами напряжение 100 В, расстояние 2 см. Напряжённость?", "o": ["5000 В/м", "50 В/м", "200 В/м", "2 В/м"], "a": 0, "e": "E = 100 / 0,02."}, {"q": "Работа поля при перемещении заряда 3 Кл между точками с разностью потенциалов 12 В?", "o": ["36 Дж", "4 Дж", "15 Дж", "0,25 Дж"], "a": 0, "e": "A = qU."}], "hard": [{"q": "Напряжённость поля точечного заряда 1 нКл на расстоянии 3 см (k = 9·10⁹)?", "o": ["10 000 В/м", "300 В/м", "3000 В/м", "1000 В/м"], "a": 0, "e": "E = 9·10⁹ × 10⁻⁹ / 9·10⁻⁴ = 10⁴."}, {"q": "Электрон ускорен разностью потенциалов 100 В. Его кинетическая энергия?", "o": ["1,6·10⁻¹⁷ Дж (100 эВ)", "100 Дж", "1,6·10⁻¹⁹ Дж", "1,6 Дж"], "a": 0, "e": "E = eU."}, {"q": "Что такое эквипотенциальная поверхность?", "o": ["поверхность, во всех точках которой потенциал одинаков", "поверхность проводника с током", "поверхность без заряда", "плоскость пластин"], "a": 0, "e": "Линии напряжённости перпендикулярны ей."}], "olympiad": [{"q": "Почему во время грозы безопасно сидеть в автомобиле с металлическим кузовом?", "o": ["металлический кузов экранирует поле (клетка Фарадея)", "шины проводят ток", "машину не видно молнии", "это опасно"], "a": 0, "e": "Поле внутри замкнутой проводящей оболочки равно нулю."}, {"q": "Пылинка массой 10⁻⁹ кг с зарядом 10⁻¹¹ Кл висит в поле между горизонтальными пластинами. Напряжённость (g = 10)?", "o": ["1000 В/м", "100 В/м", "10 В/м", "10⁻²⁰ В/м"], "a": 0, "e": "qE = mg → E = 10⁻⁸/10⁻¹¹."}, {"q": "Поля двух зарядов +q и −q на расстоянии 2a. Напряжённость посередине?", "o": ["2kq/a², направлена к −q", "0", "kq/a²", "направлена к +q"], "a": 0, "e": "Поля обоих зарядов посередине направлены в одну сторону — к отрицательному."}]}}, {"id": "p10-capacitor", "title": "Электроёмкость. Конденсаторы", "explain": "Конденсатор — два проводника (обкладки), разделённые диэлектриком; он накапливает заряд и энергию. Электроёмкость C = q/U, единица — фарад (Ф). Ёмкость плоского конденсатора растёт с площадью пластин и диэлектрической проницаемостью и уменьшается с расстоянием между пластинами. При параллельном соединении ёмкости складываются, при последовательном — складываются обратные величины.", "formula": "C = q/U;  C = ε·ε₀·S/d;  W = CU²/2;  парал.: C = C₁ + C₂;  посл.: 1/C = 1/C₁ + 1/C₂", "levels": {"easy": [{"q": "Единица электроёмкости?", "o": ["фарад", "вольт", "кулон", "генри"], "a": 0, "e": "C = q/U, 1 Ф = 1 Кл/В."}, {"q": "Что накапливает конденсатор?", "o": ["заряд и энергию электрического поля", "только массу", "магнитное поле", "звук"], "a": 0, "e": "Энергия запасена в поле между обкладками."}, {"q": "Как изменится ёмкость плоского конденсатора, если раздвинуть пластины?", "o": ["уменьшится", "увеличится", "не изменится", "станет бесконечной"], "a": 0, "e": "C ~ 1/d."}], "medium": [{"q": "Конденсатор 2 мкФ заряжен до 100 В. Заряд?", "o": ["2·10⁻⁴ Кл", "200 Кл", "5·10⁻⁵ Кл", "2·10⁻² Кл"], "a": 0, "e": "q = CU = 2·10⁻⁶ × 100."}, {"q": "Энергия конденсатора 10 мкФ при 200 В?", "o": ["0,2 Дж", "2 Дж", "1000 Дж", "0,002 Дж"], "a": 0, "e": "W = 10⁻⁵ × 40 000 / 2 = 0,2 Дж."}, {"q": "Два конденсатора 3 и 6 мкФ соединены параллельно. Общая ёмкость?", "o": ["9 мкФ", "2 мкФ", "18 мкФ", "4,5 мкФ"], "a": 0, "e": "C = C₁ + C₂."}], "hard": [{"q": "Те же конденсаторы (3 и 6 мкФ) соединены последовательно. Общая ёмкость?", "o": ["2 мкФ", "9 мкФ", "18 мкФ", "0,5 мкФ"], "a": 0, "e": "C = 3·6/(3+6) = 2 мкФ."}, {"q": "Между пластинами вставили слюду (ε = 7). Ёмкость…", "o": ["увеличилась в 7 раз", "уменьшилась в 7 раз", "не изменилась", "увеличилась в 49 раз"], "a": 0, "e": "C ~ ε."}, {"q": "Заряженный конденсатор отключили от источника и раздвинули пластины вдвое. Напряжение…", "o": ["увеличилось вдвое", "уменьшилось вдвое", "не изменилось", "стало нулём"], "a": 0, "e": "q сохраняется, C уменьшилась вдвое → U = q/C вдвое больше."}], "olympiad": [{"q": "В предыдущей ситуации (q постоянен, d увеличили вдвое) энергия конденсатора…", "o": ["увеличилась вдвое за счёт работы по раздвиганию пластин", "уменьшилась вдвое", "не изменилась", "стала нулевой"], "a": 0, "e": "W = q²/(2C), C уменьшилась вдвое."}, {"q": "Конденсатор, подключённый к источнику, заполнили диэлектриком ε = 2. Заряд на обкладках…", "o": ["увеличился вдвое", "уменьшился вдвое", "не изменился", "стал нулевым"], "a": 0, "e": "U = const, C ×2 → q = CU ×2."}, {"q": "Где используют конденсаторы?", "o": ["во вспышках фотоаппаратов, фильтрах блоков питания, дефибрилляторах", "только в батарейках", "в линзах", "в термометрах"], "a": 0, "e": "Конденсатор быстро отдаёт накопленную энергию."}]}}]}, {"title": "Постоянный электрический ток", "topics": [{"id": "p10-emf", "title": "ЭДС. Закон Ома для полной цепи", "explain": "Источник тока разделяет заряды за счёт сторонних сил (химических, механических). Электродвижущая сила (ЭДС) ε — работа сторонних сил по перемещению единичного заряда внутри источника. У источника есть внутреннее сопротивление r. Закон Ома для полной цепи: сила тока равна ЭДС, делённой на полное сопротивление цепи. При коротком замыкании (R ≈ 0) ток максимален: Iкз = ε/r.", "formula": "I = ε / (R + r);  U = ε − I·r", "levels": {"easy": [{"q": "Единица ЭДС?", "o": ["вольт", "ампер", "ом", "ватт"], "a": 0, "e": "ЭДС, как и напряжение, измеряют в вольтах."}, {"q": "Закон Ома для полной цепи:", "o": ["I = ε / (R + r)", "I = U·R", "I = ε·r", "I = R/ε"], "a": 0, "e": "Учитывается внутреннее сопротивление источника."}, {"q": "Что такое короткое замыкание?", "o": ["соединение полюсов источника проводником с очень малым сопротивлением", "отключение лампы", "обрыв провода", "длинный провод"], "a": 0, "e": "Ток резко возрастает — опасно."}], "medium": [{"q": "ε = 12 В, r = 1 Ом, R = 5 Ом. Сила тока?", "o": ["2 А", "2,4 А", "12 А", "1,7 А"], "a": 0, "e": "I = 12 / 6 = 2 А."}, {"q": "Для той же цепи (ε = 12 В, r = 1 Ом, I = 2 А) напряжение на внешнем участке?", "o": ["10 В", "12 В", "2 В", "14 В"], "a": 0, "e": "U = ε − Ir = 12 − 2 = 10 В."}, {"q": "Ток короткого замыкания батареи с ε = 4,5 В и r = 0,5 Ом?", "o": ["9 А", "2,25 А", "4,5 А", "0,11 А"], "a": 0, "e": "Iкз = ε / r."}], "hard": [{"q": "При R₁ = 4 Ом ток 1 А, при R₂ = 9 Ом ток 0,5 А. Внутреннее сопротивление источника?", "o": ["1 Ом", "2 Ом", "0,5 Ом", "5 Ом"], "a": 0, "e": "ε = 1(4 + r) = 0,5(9 + r) → 4 + r = 4,5 + 0,5r → r = 1 Ом."}, {"q": "ЭДС источника в предыдущей задаче?", "o": ["5 В", "4 В", "4,5 В", "10 В"], "a": 0, "e": "ε = 1 × (4 + 1)."}, {"q": "Две батарейки по 1,5 В (r = 0,5 Ом каждая) соединены последовательно и замкнуты на 2 Ом. Ток?", "o": ["1 А", "0,5 А", "1,5 А", "0,75 А"], "a": 0, "e": "ε = 3 В, r = 1 Ом: I = 3 / 3."}], "olympiad": [{"q": "При каком внешнем сопротивлении во внешней цепи выделяется наибольшая мощность?", "o": ["R = r", "R = 0", "R → ∞", "R = 2r"], "a": 0, "e": "Это условие согласования нагрузки."}, {"q": "Максимальная полезная мощность источника с ε = 12 В, r = 2 Ом?", "o": ["18 Вт", "72 Вт", "36 Вт", "6 Вт"], "a": 0, "e": "При R = r: I = 3 А, P = I²R = 9 × 2 = 18 Вт."}, {"q": "КПД источника при R = r?", "o": ["50%", "100%", "25%", "75%"], "a": 0, "e": "η = R/(R + r)."}]}}, {"id": "p10-media", "title": "Электрический ток в различных средах", "explain": "В металлах ток создают свободные электроны; сопротивление металлов растёт при нагревании. В растворах электролитов ток — движение ионов, при этом на электродах выделяется вещество (электролиз). В газах ток возможен при ионизации (разряды: искра, молния, дуга). В вакууме ток создают электроны, вылетевшие из нагретого катода. В полупроводниках есть электронная и дырочная проводимость; их сопротивление уменьшается при нагревании, на p–n-переходе основаны диоды и транзисторы.", "formula": "Закон электролиза Фарадея: m = k·I·t", "levels": {"easy": [{"q": "Какие частицы переносят ток в растворах электролитов?", "o": ["ионы", "только электроны", "нейтроны", "фотоны"], "a": 0, "e": "Положительные и отрицательные ионы."}, {"q": "Пример газового разряда в природе?", "o": ["молния", "радуга", "северный ветер", "роса"], "a": 0, "e": "Молния — гигантский искровой разряд."}, {"q": "Как меняется сопротивление металлов при нагревании?", "o": ["растёт", "падает", "не меняется", "исчезает"], "a": 0, "e": "Ионы решётки колеблются сильнее и мешают электронам."}], "medium": [{"q": "Как меняется сопротивление полупроводника при нагревании?", "o": ["уменьшается", "увеличивается", "не меняется", "становится бесконечным"], "a": 0, "e": "При нагреве появляется больше свободных носителей заряда."}, {"q": "Для чего используют электролиз?", "o": ["для нанесения металлических покрытий и получения чистых металлов", "для нагрева воды", "для освещения", "для охлаждения"], "a": 0, "e": "Гальванопластика, хромирование, получение алюминия."}, {"q": "Какое свойство у полупроводникового диода?", "o": ["проводит ток в основном в одном направлении", "усиливает свет", "накапливает заряд", "проводит ток одинаково в обе стороны"], "a": 0, "e": "Диод выпрямляет переменный ток."}], "hard": [{"q": "Что такое сверхпроводимость?", "o": ["исчезновение сопротивления у некоторых веществ при очень низкой температуре", "очень большой ток", "свечение металла", "проводимость вакуума"], "a": 0, "e": "Открыта в 1911 году у ртути при ≈ 4 К."}, {"q": "Что такое «дырка» в полупроводнике?", "o": ["вакантное место электрона, ведущее себя как положительный заряд", "отверстие в кристалле", "нейтрон", "свободный протон"], "a": 0, "e": "Дырки — носители заряда в p-полупроводниках."}, {"q": "Электрохимический эквивалент меди 3,3·10⁻⁷ кг/Кл. Сколько меди выделится при токе 2 А за 1000 с?", "o": ["0,66 г", "6,6 г", "0,33 г", "66 г"], "a": 0, "e": "m = kIt = 3,3·10⁻⁷ × 2000 = 6,6·10⁻⁴ кг."}], "olympiad": [{"q": "Почему у лампы накаливания ток в момент включения больше, чем в рабочем режиме?", "o": ["холодная нить имеет меньшее сопротивление", "напряжение больше при включении", "лампа заряжается", "ток всегда одинаков"], "a": 0, "e": "Сопротивление вольфрама растёт с температурой."}, {"q": "Какая примесь создаёт в кремнии n-проводимость?", "o": ["пятивалентная (например, фосфор)", "трёхвалентная (бор)", "кислород", "любая"], "a": 0, "e": "Лишний электрон примеси становится свободным."}, {"q": "Почему неоновая лампа светится при напряжении, а при малом — нет?", "o": ["разряд в газе начинается, когда напряжение достаточно для ионизации", "газ нагревается", "неон — металл", "лампа без газа"], "a": 0, "e": "Нужна ударная ионизация молекул газа."}]}}]}]}, "11": {"sections": [{"title": "Магнитное поле. Электромагнитная индукция", "topics": [{"id": "p11-magnetic", "title": "Магнитное поле. Сила Ампера и сила Лоренца", "explain": "Магнитное поле создаётся движущимися зарядами (токами) и действует на движущиеся заряды. Его характеризует вектор магнитной индукции B (тесла, Тл). На проводник с током в магнитном поле действует сила Ампера, на движущуюся заряженную частицу — сила Лоренца. Направление этих сил определяют правилом левой руки. Сила Лоренца перпендикулярна скорости, поэтому не меняет модуль скорости — частица движется по окружности.", "formula": "Fₐ = I·B·l·sin α;  Fл = q·v·B·sin α;  R = m·v / (q·B)", "levels": {"easy": [{"q": "Единица магнитной индукции?", "o": ["тесла", "вебер", "генри", "вольт"], "a": 0, "e": "B измеряется в теслах."}, {"q": "Какое правило определяет направление силы Ампера?", "o": ["правило левой руки", "правило правой руки для тока", "правило буравчика для заряда", "закон Ома"], "a": 0, "e": "Четыре пальца — по току, линии B входят в ладонь, большой палец — сила."}, {"q": "На что действует магнитное поле?", "o": ["на движущиеся заряды и токи", "на неподвижные заряды", "только на железо", "ни на что"], "a": 0, "e": "На покоящийся заряд магнитное поле не действует."}], "medium": [{"q": "Проводник длиной 0,5 м с током 4 А находится в поле 0,2 Тл перпендикулярно линиям. Сила Ампера?", "o": ["0,4 Н", "1,6 Н", "4 Н", "0,1 Н"], "a": 0, "e": "F = IBl = 4 × 0,2 × 0,5."}, {"q": "Если проводник с током расположить вдоль линий магнитной индукции, сила Ампера…", "o": ["равна нулю", "максимальна", "удваивается", "направлена вдоль тока"], "a": 0, "e": "sin 0° = 0."}, {"q": "Работа силы Лоренца при движении частицы…", "o": ["равна нулю", "положительна", "отрицательна", "зависит от заряда"], "a": 0, "e": "Сила перпендикулярна скорости."}], "hard": [{"q": "Протон (q = 1,6·10⁻¹⁹ Кл) влетает со скоростью 10⁶ м/с перпендикулярно полю 0,1 Тл. Сила Лоренца?", "o": ["1,6·10⁻¹⁴ Н", "1,6·10⁻¹⁹ Н", "10⁵ Н", "1,6·10⁻¹² Н"], "a": 0, "e": "F = qvB = 1,6·10⁻¹⁹ × 10⁶ × 0,1."}, {"q": "Как изменится радиус окружности частицы, если её скорость увеличить вдвое?", "o": ["увеличится вдвое", "уменьшится вдвое", "не изменится", "увеличится в 4 раза"], "a": 0, "e": "R = mv/(qB)."}, {"q": "Почему полярные сияния бывают в основном у полюсов?", "o": ["магнитное поле Земли направляет заряженные частицы солнечного ветра к полюсам", "у полюсов холоднее", "там ближе к Солнцу", "из-за льда"], "a": 0, "e": "Частицы движутся по спирали вдоль линий поля."}], "olympiad": [{"q": "Период обращения заряженной частицы в однородном магнитном поле…", "o": ["не зависит от скорости", "растёт со скоростью", "уменьшается со скоростью", "равен нулю"], "a": 0, "e": "T = 2πm/(qB) — принцип циклотрона (при нерелятивистских скоростях)."}, {"q": "Два параллельных провода с токами в противоположных направлениях…", "o": ["отталкиваются", "притягиваются", "не взаимодействуют", "вращаются"], "a": 0, "e": "Противоположные токи отталкиваются."}, {"q": "Электрон и протон влетают с одинаковой скоростью перпендикулярно полю. У кого радиус окружности больше?", "o": ["у протона", "у электрона", "одинаковые", "у обоих ноль"], "a": 0, "e": "Заряды равны по модулю, масса протона в ~1836 раз больше."}]}}, {"id": "p11-induction", "title": "Электромагнитная индукция. Самоиндукция", "explain": "Магнитный поток Φ = B·S·cos α (вебер). При любом изменении магнитного потока через контур возникает ЭДС индукции (закон Фарадея). Правило Ленца: индукционный ток направлен так, чтобы своим магнитным полем препятствовать изменению потока, которое его вызвало. Самоиндукция — возникновение ЭДС в контуре при изменении тока в нём самом; характеризуется индуктивностью L (генри). Энергия магнитного поля катушки LI²/2.", "formula": "εi = −ΔΦ/Δt;  Φ = B·S·cos α;  εsi = −L·ΔI/Δt;  W = L·I²/2", "levels": {"easy": [{"q": "Единица магнитного потока?", "o": ["вебер", "тесла", "генри", "фарад"], "a": 0, "e": "1 Вб = 1 Тл·м²."}, {"q": "Правило Ленца говорит, что индукционный ток…", "o": ["препятствует изменению магнитного потока", "усиливает изменение потока", "всегда течёт по часовой стрелке", "не зависит от потока"], "a": 0, "e": "Это следствие закона сохранения энергии."}, {"q": "Единица индуктивности?", "o": ["генри", "ом", "вебер", "тесла"], "a": 0, "e": "L = Φ/I."}], "medium": [{"q": "Поток через контур изменился на 0,6 Вб за 0,2 с. ЭДС индукции?", "o": ["3 В", "0,12 В", "0,8 В", "1,2 В"], "a": 0, "e": "ε = ΔΦ/Δt = 0,6/0,2."}, {"q": "Рамка 0,1 м² в поле 0,5 Тл перпендикулярно линиям. Поток?", "o": ["0,05 Вб", "5 Вб", "0,6 Вб", "0,2 Вб"], "a": 0, "e": "Φ = BS = 0,5 × 0,1."}, {"q": "Энергия поля катушки 0,2 Гн при токе 3 А?", "o": ["0,9 Дж", "0,6 Дж", "1,8 Дж", "0,3 Дж"], "a": 0, "e": "W = 0,2 × 9 / 2."}], "hard": [{"q": "Проводник длиной 0,5 м движется со скоростью 4 м/с перпендикулярно полю 0,2 Тл. ЭДС индукции?", "o": ["0,4 В", "1,6 В", "4 В", "0,1 В"], "a": 0, "e": "ε = Bvl = 0,2 × 4 × 0,5."}, {"q": "Ток в катушке 0,4 Гн равномерно убывает с 5 А до 0 за 0,1 с. ЭДС самоиндукции?", "o": ["20 В", "2 В", "0,2 В", "50 В"], "a": 0, "e": "ε = L·ΔI/Δt = 0,4 × 50."}, {"q": "Почему при размыкании цепи с большой катушкой проскакивает искра?", "o": ["ЭДС самоиндукции при резком спаде тока очень велика", "катушка нагревается", "ток увеличивается", "это электролиз"], "a": 0, "e": "Быстрое изменение тока даёт большую ЭДС."}], "olympiad": [{"q": "Магнит падает сквозь медную трубу медленнее, чем сквозь пластиковую. Почему?", "o": ["в меди возникают вихревые токи, тормозящие магнит", "медь притягивает магнит как железо", "в пластике меньше трение", "медь тяжелее"], "a": 0, "e": "Правило Ленца: индукционные токи препятствуют движению магнита."}, {"q": "Рамку повернули из положения, где плоскость перпендикулярна B, на 90°. Как изменился поток?", "o": ["от BS до 0", "от 0 до BS", "не изменился", "удвоился"], "a": 0, "e": "Φ = BS cos α: α от 0° до 90°."}, {"q": "Катушку (L = 0,5 Гн) с током 2 А замкнули на резистор. Сколько теплоты выделится до исчезновения тока?", "o": ["1 Дж", "2 Дж", "0,5 Дж", "4 Дж"], "a": 0, "e": "Вся энергия поля LI²/2 = 0,5 × 4/2 = 1 Дж переходит в тепло."}]}}]}, {"title": "Колебания и волны", "topics": [{"id": "p11-em-osc", "title": "Электромагнитные колебания. Колебательный контур", "explain": "Колебательный контур — цепь из конденсатора и катушки. Заряженный конденсатор разряжается через катушку, энергия электрического поля переходит в энергию магнитного поля и обратно — возникают свободные электромагнитные колебания. Период определяется формулой Томсона. В реальном контуре колебания затухают из-за сопротивления.", "formula": "T = 2π√(LC);  ν = 1/T;  CU²max/2 = LI²max/2", "levels": {"easy": [{"q": "Из чего состоит колебательный контур?", "o": ["из конденсатора и катушки", "из резистора и лампы", "из батарейки и ключа", "из трансформатора"], "a": 0, "e": "LC-контур."}, {"q": "Формула Томсона для периода:", "o": ["T = 2π√(LC)", "T = 2π√(l/g)", "T = 1/LC", "T = LC"], "a": 0, "e": "Период контура."}, {"q": "Какие превращения энергии происходят в контуре?", "o": ["энергия электрического поля ↔ энергия магнитного поля", "механическая ↔ тепловая", "световая ↔ звуковая", "никаких"], "a": 0, "e": "Аналогично маятнику: потенциальная ↔ кинетическая."}], "medium": [{"q": "Как изменится период контура, если ёмкость увеличить в 4 раза?", "o": ["увеличится вдвое", "в 4 раза", "уменьшится вдвое", "не изменится"], "a": 0, "e": "T ~ √C."}, {"q": "L = 1 мГн, C = 1 мкФ. Период (π ≈ 3,14)?", "o": ["≈ 0,2 мс", "≈ 2 мс", "≈ 6,28 с", "≈ 1 мкс"], "a": 0, "e": "T = 2π√(10⁻⁹) = 2π·3,16·10⁻⁵ ≈ 1,99·10⁻⁴ с."}, {"q": "Почему колебания в реальном контуре затухают?", "o": ["энергия переходит в тепло на сопротивлении проводов", "катушка теряет витки", "заряд исчезает", "не затухают"], "a": 0, "e": "Активное сопротивление превращает энергию во внутреннюю."}], "hard": [{"q": "Конденсатор 2 мкФ заряжен до 10 В и подключён к катушке. Максимальная энергия магнитного поля?", "o": ["10⁻⁴ Дж", "2·10⁻⁵ Дж", "10⁻² Дж", "10 Дж"], "a": 0, "e": "Wmax = CU²/2 = 2·10⁻⁶ × 100 / 2."}, {"q": "В том контуре L = 0,02 Гн. Максимальный ток?", "o": ["0,1 А", "1 А", "0,01 А", "10 А"], "a": 0, "e": "LI²/2 = 10⁻⁴ → I² = 0,01."}, {"q": "Что такое резонанс в электрической цепи?", "o": ["резкое увеличение амплитуды тока при совпадении частоты источника с собственной частотой контура", "короткое замыкание", "разряд конденсатора", "нагрев провода"], "a": 0, "e": "На резонансе основана настройка радиоприёмника."}], "olympiad": [{"q": "Чтобы приёмник принимал станцию с большей длиной волны, ёмкость конденсатора нужно…", "o": ["увеличить", "уменьшить", "не менять", "убрать"], "a": 0, "e": "λ = c·T = 2πc√(LC)."}, {"q": "Во сколько раз изменится частота контура, если L увеличить в 9 раз, а C уменьшить в 4 раза?", "o": ["уменьшится в 1,5 раза", "увеличится в 1,5 раза", "уменьшится в 6 раз", "не изменится"], "a": 0, "e": "ν ~ 1/√(LC): √(9/4) = 1,5."}, {"q": "Через какую часть периода после начала разрядки конденсатора ток в контуре максимален?", "o": ["через T/4", "через T/2", "через T", "сразу"], "a": 0, "e": "Энергия полностью перейдёт в магнитное поле через четверть периода."}]}}, {"id": "p11-ac", "title": "Переменный ток. Трансформатор. Передача электроэнергии", "explain": "Переменный ток — ток, сила и направление которого периодически меняются; в сети Казахстана частота 50 Гц, действующее напряжение 220 В. Действующее значение в √2 раз меньше амплитудного. Трансформатор повышает или понижает переменное напряжение; отношение напряжений равно отношению чисел витков. Электроэнергию передают на большие расстояния при высоком напряжении, чтобы уменьшить потери на нагрев проводов.", "formula": "U = Um/√2;  U₁/U₂ = N₁/N₂ = k;  Pпотерь = I²R", "levels": {"easy": [{"q": "Частота переменного тока в сети Казахстана?", "o": ["50 Гц", "60 Гц", "220 Гц", "1 Гц"], "a": 0, "e": "Стандартная частота сети."}, {"q": "Что делает трансформатор?", "o": ["изменяет переменное напряжение", "превращает переменный ток в постоянный", "накапливает энергию", "вырабатывает энергию"], "a": 0, "e": "Повышающий или понижающий."}, {"q": "Почему ЛЭП работают при высоком напряжении?", "o": ["чтобы уменьшить ток и потери на нагрев проводов", "чтобы ток был больше", "ради безопасности", "так дешевле провода красить"], "a": 0, "e": "Pпотерь = I²R."}], "medium": [{"q": "Первичная обмотка 1000 витков, вторичная 50. На входе 220 В. Напряжение на выходе?", "o": ["11 В", "4400 В", "220 В", "50 В"], "a": 0, "e": "U₂ = 220 × 50/1000."}, {"q": "Амплитуда напряжения сети 220 В действующего значения?", "o": ["≈ 311 В", "220 В", "≈ 156 В", "440 В"], "a": 0, "e": "Um = 220 × √2."}, {"q": "Работает ли трансформатор на постоянном токе?", "o": ["нет", "да", "только понижающий", "только повышающий"], "a": 0, "e": "Нужен изменяющийся магнитный поток."}], "hard": [{"q": "Мощность 100 кВт передают по проводам сопротивлением 10 Ом при напряжении 10 кВ. Потери?", "o": ["1 кВт", "10 кВт", "100 Вт", "100 кВт"], "a": 0, "e": "I = P/U = 10 А; P = I²R = 100 × 10 = 1000 Вт."}, {"q": "Если то же передавать при 100 кВ, потери станут…", "o": ["в 100 раз меньше", "в 10 раз меньше", "такими же", "в 100 раз больше"], "a": 0, "e": "Ток в 10 раз меньше, потери ~ I²."}, {"q": "Сколько раз за секунду меняет направление ток частотой 50 Гц?", "o": ["100 раз", "50 раз", "25 раз", "220 раз"], "a": 0, "e": "За период направление меняется дважды."}], "olympiad": [{"q": "КПД трансформатора 95%, на вход подаётся 2 кВт. Мощность на выходе?", "o": ["1,9 кВт", "2 кВт", "1,05 кВт", "2,1 кВт"], "a": 0, "e": "Pвых = 0,95 × 2."}, {"q": "Почему сердечник трансформатора набирают из тонких изолированных пластин?", "o": ["чтобы уменьшить вихревые токи и нагрев", "для лёгкости", "для красоты", "чтобы усилить вихревые токи"], "a": 0, "e": "Пластины разрывают пути вихревых токов."}, {"q": "Действующее значение тока 5 А, сопротивление 10 Ом. Средняя мощность?", "o": ["250 Вт", "50 Вт", "500 Вт", "125 Вт"], "a": 0, "e": "Действующее значение и введено для формулы P = I²R."}]}}, {"id": "p11-em-waves", "title": "Электромагнитные волны. Радиосвязь", "explain": "Электромагнитная волна — распространяющееся в пространстве переменное электромагнитное поле; она поперечная, переносит энергию и распространяется в вакууме со скоростью c ≈ 3·10⁸ м/с. Существование волн предсказал Максвелл, получил Герц. Шкала ЭМ волн: радиоволны, инфракрасное, видимое, ультрафиолетовое, рентгеновское, гамма-излучение. В радиосвязи звуковой сигнал модулирует высокочастотную несущую волну.", "formula": "c = λ·ν", "levels": {"easy": [{"q": "Кто экспериментально получил электромагнитные волны?", "o": ["Генрих Герц", "Исаак Ньютон", "Майкл Фарадей", "Нильс Бор"], "a": 0, "e": "Герц провёл опыты в 1880-х годах."}, {"q": "Электромагнитная волна — продольная или поперечная?", "o": ["поперечная", "продольная", "и та и другая", "никакая"], "a": 0, "e": "Векторы E и B перпендикулярны направлению распространения."}, {"q": "Какое излучение имеет наибольшую частоту?", "o": ["гамма-излучение", "радиоволны", "видимый свет", "инфракрасное"], "a": 0, "e": "Гамма — самая коротковолновая часть шкалы."}], "medium": [{"q": "Длина волны радиостанции 300 м. Частота?", "o": ["1 МГц", "1 кГц", "100 МГц", "300 кГц"], "a": 0, "e": "ν = 3·10⁸ / 300 = 10⁶ Гц."}, {"q": "Что такое модуляция?", "o": ["изменение параметров несущей волны в такт со звуковым сигналом", "усиление сигнала", "приём волны антенной", "отражение волны"], "a": 0, "e": "Амплитудная или частотная модуляция."}, {"q": "Какое излучение используют в пультах ДУ?", "o": ["инфракрасное", "ультрафиолетовое", "рентгеновское", "гамма"], "a": 0, "e": "ИК-светодиод пульта."}], "hard": [{"q": "Почему УКВ-радио (ФМ) принимают только в пределах прямой видимости, а длинные волны — далеко?", "o": ["длинные волны огибают поверхность Земли и отражаются от ионосферы", "УКВ слабее", "длинные волны быстрее", "из-за спутников"], "a": 0, "e": "Дифракция и отражение от ионосферы для длинных волн."}, {"q": "Сигнал до геостационарного спутника (36 000 км) и обратно идёт примерно…", "o": ["0,24 с", "2,4 с", "0,024 с", "мгновенно"], "a": 0, "e": "t = 2 × 3,6·10⁷ / 3·10⁸ = 0,24 с."}, {"q": "Чем опасно ультрафиолетовое излучение?", "o": ["может вызвать ожоги кожи и повреждение глаз", "оно холодное", "оно радиоактивно", "ничем"], "a": 0, "e": "Озоновый слой задерживает большую часть УФ."}], "olympiad": [{"q": "Почему мобильный телефон плохо ловит в лифте?", "o": ["металлическая кабина экранирует электромагнитные волны", "в лифте мало воздуха", "из-за движения лифта", "из-за освещения"], "a": 0, "e": "Металлическая оболочка работает как клетка Фарадея."}, {"q": "Частота Wi-Fi 2,4 ГГц. Длина волны?", "o": ["12,5 см", "1,25 м", "1,25 см", "125 м"], "a": 0, "e": "λ = 3·10⁸ / 2,4·10⁹ = 0,125 м."}, {"q": "Почему рентгеновские снимки показывают кости?", "o": ["кости сильнее поглощают рентгеновское излучение, чем мягкие ткани", "кости светятся", "кости отражают свет", "кости — проводники"], "a": 0, "e": "Разное поглощение даёт контраст."}]}}]}, {"title": "Оптика и теория относительности", "topics": [{"id": "p11-wave-optics", "title": "Волновая оптика: интерференция, дифракция, поляризация", "explain": "Свет обладает волновыми свойствами. Интерференция — сложение когерентных волн с усилением или ослаблением (радужные плёнки мыльных пузырей). Дифракция — огибание волнами препятствий; на дифракционной решётке свет разлагается в спектр. Поляризация доказывает, что свет — поперечная волна. Дисперсия — зависимость показателя преломления от длины волны.", "formula": "Максимум интерференции: Δ = k·λ;  дифракционная решётка: d·sin φ = k·λ", "levels": {"easy": [{"q": "Почему мыльные пузыри переливаются цветами?", "o": ["из-за интерференции света в тонкой плёнке", "мыло окрашено", "из-за отражения неба", "из-за ветра"], "a": 0, "e": "Волны, отражённые от двух поверхностей плёнки, складываются."}, {"q": "Что доказывает поляризация света?", "o": ["свет — поперечная волна", "свет — поток частиц", "свет — продольная волна", "свет не волна"], "a": 0, "e": "Продольные волны поляризовать нельзя."}, {"q": "Что такое дифракция?", "o": ["огибание волнами препятствий", "отражение от зеркала", "поглощение света", "излучение света"], "a": 0, "e": "Особенно заметна, когда размер препятствия сравним с длиной волны."}], "medium": [{"q": "Условие максимума при интерференции:", "o": ["разность хода равна целому числу длин волн", "разность хода равна половине волны", "волны некогерентны", "амплитуды равны нулю"], "a": 0, "e": "Волны приходят в одной фазе."}, {"q": "Период решётки 2 мкм, λ = 0,5 мкм. Синус угла первого максимума?", "o": ["0,25", "0,5", "4", "1"], "a": 0, "e": "sin φ = λ/d."}, {"q": "Зачем на объективы наносят просветляющее покрытие?", "o": ["чтобы за счёт интерференции уменьшить отражение", "для цвета", "для защиты от царапин только", "чтобы увеличить отражение"], "a": 0, "e": "Отражённые волны гасят друг друга."}], "hard": [{"q": "Наибольший порядок спектра для решётки d = 2 мкм при λ = 0,5 мкм?", "o": ["4", "2", "5", "8"], "a": 0, "e": "k ≤ d/λ = 4 (sin φ ≤ 1)."}, {"q": "Какой свет дифракционная решётка отклоняет сильнее?", "o": ["красный", "фиолетовый", "одинаково", "зелёный"], "a": 0, "e": "sin φ ~ λ — у красного длина волны больше (в отличие от призмы)."}, {"q": "Почему поляроидные очки уменьшают блики от воды?", "o": ["отражённый свет частично поляризован, и фильтр его задерживает", "очки тёмные", "вода поглощает свет", "очки нагреваются"], "a": 0, "e": "Свет, отражённый от воды, поляризован горизонтально."}], "olympiad": [{"q": "Две волны с разностью хода 1,5λ. Результат?", "o": ["ослабление (минимум)", "усиление (максимум)", "ничего", "удвоение частоты"], "a": 0, "e": "Разность хода — полуцелое число длин волн."}, {"q": "Почему мы слышим звук из-за угла, но не видим источник света?", "o": ["длина звуковой волны сравнима с размерами препятствий, а световой — намного меньше", "звук быстрее", "свет не дифрагирует вообще", "уши лучше глаз"], "a": 0, "e": "Дифракция заметна при соизмеримых размерах."}, {"q": "Решётка 500 штрихов на 1 мм. Её период?", "o": ["2 мкм", "0,5 мкм", "500 мкм", "2 мм"], "a": 0, "e": "d = 1 мм / 500 = 0,002 мм."}]}}, {"id": "p11-relativity", "title": "Основы специальной теории относительности", "explain": "Постулаты Эйнштейна: все законы физики одинаковы во всех инерциальных системах отсчёта; скорость света в вакууме одинакова во всех ИСО и не зависит от движения источника. Следствия: замедление времени в движущейся системе, сокращение длины вдоль движения, скорость света — предельная скорость передачи сигналов. Энергия покоя тела связана с массой: E = mc².", "formula": "E₀ = m·c²;  t = t₀ / √(1 − v²/c²);  l = l₀·√(1 − v²/c²)", "levels": {"easy": [{"q": "Кто создал специальную теорию относительности?", "o": ["Альберт Эйнштейн", "Исаак Ньютон", "Нильс Бор", "Макс Планк"], "a": 0, "e": "Опубликована в 1905 году."}, {"q": "Скорость света в вакууме…", "o": ["одинакова во всех инерциальных системах отсчёта", "зависит от скорости источника", "меньше скорости звука", "бесконечна"], "a": 0, "e": "Второй постулат СТО."}, {"q": "Формула энергии покоя:", "o": ["E = mc²", "E = mgh", "E = mv²/2", "E = hν/c"], "a": 0, "e": "Масса — мера энергии покоя."}], "medium": [{"q": "Можно ли разогнать тело с массой до скорости света?", "o": ["нет", "да", "да, с мощным двигателем", "только в космосе"], "a": 0, "e": "Для этого нужна бесконечная энергия."}, {"q": "Энергия покоя 1 кг вещества?", "o": ["9·10¹⁶ Дж", "3·10⁸ Дж", "9,8 Дж", "1 Дж"], "a": 0, "e": "E = 1 × (3·10⁸)²."}, {"q": "Что происходит с ходом часов в быстро движущемся корабле (с точки зрения Земли)?", "o": ["они идут медленнее", "быстрее", "так же", "останавливаются"], "a": 0, "e": "Релятивистское замедление времени."}], "hard": [{"q": "Корабль летит со скоростью 0,6c. Во сколько раз медленнее идут его часы для земного наблюдателя?", "o": ["в 1,25 раза", "в 1,67 раза", "в 0,6 раза", "в 2 раза"], "a": 0, "e": "√(1 − 0,36) = 0,8; 1/0,8 = 1,25."}, {"q": "Длина стержня 1 м в покое. Какой она будет при скорости 0,8c вдоль стержня?", "o": ["0,6 м", "0,8 м", "1 м", "1,67 м"], "a": 0, "e": "√(1 − 0,64) = 0,6."}, {"q": "Почему в повседневной жизни мы не замечаем эффектов СТО?", "o": ["скорости тел много меньше скорости света", "их не существует", "они заметны всегда", "мы живём в неинерциальной системе"], "a": 0, "e": "При v ≪ c формулы СТО совпадают с классическими."}], "olympiad": [{"q": "Мюоны, рождающиеся в верхней атмосфере, доходят до Земли, хотя живут очень мало. Почему?", "o": ["из-за замедления времени их время жизни для нас удлиняется", "они летят быстрее света", "атмосфера их ускоряет", "это ошибка измерений"], "a": 0, "e": "Классическое подтверждение СТО."}, {"q": "Два фотона летят навстречу друг другу. Скорость одного относительно другого?", "o": ["c", "2c", "0", "c/2"], "a": 0, "e": "Скорость света одинакова в любой системе отсчёта."}, {"q": "Солнце излучает около 4·10²⁶ Вт. На сколько уменьшается его масса за секунду?", "o": ["≈ 4·10⁹ кг", "≈ 4·10²⁶ кг", "≈ 1 кг", "≈ 10³⁰ кг"], "a": 0, "e": "Δm = P·t/c² = 4·10²⁶ / 9·10¹⁶ ≈ 4,4·10⁹ кг."}]}}]}, {"title": "Квантовая и атомная физика", "topics": [{"id": "p11-photoeffect", "title": "Фотоэффект. Фотон", "explain": "Фотоэффект — вырывание электронов из вещества светом. Опыты Столетова и объяснение Эйнштейна показали, что свет поглощается порциями — квантами (фотонами) с энергией hν. Уравнение Эйнштейна: энергия фотона идёт на работу выхода и кинетическую энергию электрона. Фотоэффект возникает, только если частота света не меньше красной границы; кинетическая энергия электронов зависит от частоты, а не от интенсивности света.", "formula": "E = h·ν;  h·ν = Aвых + m·v²/2;  νmin = Aвых / h;  h = 6,63·10⁻³⁴ Дж·с", "levels": {"easy": [{"q": "Что такое фотон?", "o": ["квант (порция) света", "частица ядра", "электрон в металле", "звуковая волна"], "a": 0, "e": "Энергия фотона E = hν."}, {"q": "Кто объяснил законы фотоэффекта?", "o": ["Альберт Эйнштейн", "Ньютон", "Резерфорд", "Максвелл"], "a": 0, "e": "За это Эйнштейн получил Нобелевскую премию."}, {"q": "От чего зависит энергия фотона?", "o": ["от частоты света", "от яркости света", "от расстояния до источника", "от массы приёмника"], "a": 0, "e": "E = hν."}], "medium": [{"q": "Энергия фотона частотой 10¹⁵ Гц (h = 6,63·10⁻³⁴)?", "o": ["6,63·10⁻¹⁹ Дж", "6,63·10⁻³⁴ Дж", "10¹⁵ Дж", "6,63·10⁻⁴⁹ Дж"], "a": 0, "e": "E = hν."}, {"q": "Если увеличить яркость света (частота та же), то при фотоэффекте…", "o": ["вырывается больше электронов, их энергия та же", "энергия электронов растёт", "фотоэффект прекратится", "ничего не изменится"], "a": 0, "e": "Интенсивность определяет число фотонов."}, {"q": "Что такое красная граница фотоэффекта?", "o": ["минимальная частота света, при которой ещё есть фотоэффект", "красный цвет света", "максимальная частота", "граница спектра"], "a": 0, "e": "νmin = A/h."}], "hard": [{"q": "Работа выхода 2 эВ, энергия фотона 5 эВ. Максимальная кинетическая энергия электронов?", "o": ["3 эВ", "7 эВ", "2,5 эВ", "10 эВ"], "a": 0, "e": "Eк = hν − A."}, {"q": "Работа выхода 3,3·10⁻¹⁹ Дж. Красная граница (частота)?", "o": ["≈ 5·10¹⁴ Гц", "≈ 5·10¹⁹ Гц", "≈ 2·10¹⁴ Гц", "≈ 10¹⁶ Гц"], "a": 0, "e": "ν = A/h = 3,3·10⁻¹⁹ / 6,63·10⁻³⁴ ≈ 5·10¹⁴."}, {"q": "Где применяют фотоэффект?", "o": ["в солнечных батареях и фотодатчиках", "в линзах", "в трансформаторах", "в термометрах"], "a": 0, "e": "Фотоэлементы превращают свет в электрический ток."}], "olympiad": [{"q": "Импульс фотона с длиной волны 663 нм?", "o": ["10⁻²⁷ кг·м/с", "10⁻³⁴ кг·м/с", "10⁻¹⁹ кг·м/с", "6,63 кг·м/с"], "a": 0, "e": "p = h/λ = 6,63·10⁻³⁴ / 6,63·10⁻⁷."}, {"q": "Почему ультрафиолет вызывает фотоэффект в цинке, а видимый свет — нет?", "o": ["энергия фотонов видимого света меньше работы выхода цинка", "видимый свет слабее", "цинк прозрачен для видимого света", "так совпало"], "a": 0, "e": "Важна энергия отдельного фотона."}, {"q": "Какое задерживающее напряжение нужно, чтобы остановить электроны с энергией 3 эВ?", "o": ["3 В", "1,5 В", "6 В", "0,3 В"], "a": 0, "e": "eUз = Eк → Uз = 3 В."}]}}, {"id": "p11-atom", "title": "Строение атома. Постулаты Бора. Спектры", "explain": "Планетарная модель Резерфорда не объясняла устойчивость атома. Нильс Бор предложил постулаты: электрон в атоме находится только в определённых стационарных состояниях, не излучая; при переходе с одного уровня на другой атом излучает или поглощает фотон с энергией, равной разности энергий уровней. Поэтому у каждого элемента свой линейчатый спектр — на этом основан спектральный анализ. Лазер — источник когерентного излучения на основе вынужденного излучения.", "formula": "h·ν = Eₖ − Eₙ", "levels": {"easy": [{"q": "Кто предложил постулаты о стационарных состояниях атома?", "o": ["Нильс Бор", "Эрнест Резерфорд", "Дмитрий Менделеев", "Майкл Фарадей"], "a": 0, "e": "Постулаты Бора — 1913 год."}, {"q": "Что излучает атом при переходе электрона на более низкий уровень?", "o": ["фотон", "электрон", "протон", "нейтрон"], "a": 0, "e": "Энергия уносится квантом света."}, {"q": "Какой спектр дают разреженные газы?", "o": ["линейчатый", "сплошной", "полосатый всегда", "никакой"], "a": 0, "e": "Набор отдельных линий — «отпечаток» элемента."}], "medium": [{"q": "Электрон перешёл с уровня −1,5 эВ на уровень −3,4 эВ. Энергия фотона?", "o": ["1,9 эВ", "4,9 эВ", "−1,9 эВ", "3,4 эВ"], "a": 0, "e": "E = −1,5 − (−3,4) = 1,9 эВ (красная линия водорода)."}, {"q": "Для чего используют спектральный анализ?", "o": ["чтобы определить химический состав вещества, даже звёзд", "чтобы измерить массу", "чтобы найти скорость звука", "чтобы взвесить звезду"], "a": 0, "e": "Так в спектре Солнца открыли гелий."}, {"q": "Чем свет лазера отличается от света лампы?", "o": ["он когерентный, монохроматический и узконаправленный", "он всегда невидим", "он теплее", "ничем"], "a": 0, "e": "Лазерный пучок почти не расходится."}], "hard": [{"q": "Энергия основного состояния водорода −13,6 эВ. Энергия ионизации?", "o": ["13,6 эВ", "6,8 эВ", "27,2 эВ", "1 эВ"], "a": 0, "e": "Чтобы оторвать электрон, нужно довести энергию до нуля."}, {"q": "Почему модель Резерфорда противоречила классической физике?", "o": ["вращающийся электрон должен излучать и упасть на ядро", "ядро слишком тяжёлое", "электроны отталкиваются от ядра", "она не противоречила"], "a": 0, "e": "Ускоренный заряд излучает энергию."}, {"q": "Атом поглощает фотоны только определённых частот, потому что…", "o": ["энергия фотона должна точно равняться разности уровней", "атом маленький", "фотоны разных цветов не поглощаются", "атом всегда поглощает любые"], "a": 0, "e": "Отсюда линии поглощения."}], "olympiad": [{"q": "Сколько разных линий может излучить атом водорода, возбуждённый на 4-й уровень?", "o": ["6", "3", "4", "10"], "a": 0, "e": "Число переходов между 4 уровнями: 4·3/2 = 6."}, {"q": "Энергия уровней водорода Eₙ = −13,6/n² эВ. Энергия фотона при переходе 3 → 2?", "o": ["≈ 1,89 эВ", "≈ 12,1 эВ", "≈ 3,4 эВ", "≈ 0,66 эВ"], "a": 0, "e": "−1,51 − (−3,4) ≈ 1,89 эВ."}, {"q": "Как по спектру определили, что звёзды удаляются?", "o": ["линии смещены к красному концу (эффект Доплера)", "звёзды краснеют от старости", "по яркости", "по мерцанию"], "a": 0, "e": "Красное смещение указывает на удаление источника."}]}}, {"id": "p11-nucleus", "title": "Атомное ядро. Энергия связи. Ядерные реакции", "explain": "Ядро состоит из Z протонов и N нейтронов, массовое число A = Z + N. Ядерные силы короткодействующие и очень мощные. Масса ядра меньше суммы масс нуклонов — разность (дефект масс) соответствует энергии связи. Наибольшая удельная энергия связи у ядер в районе железа, поэтому энергия выделяется и при делении тяжёлых ядер, и при синтезе лёгких. Закон радиоактивного распада: N = N₀·2^(−t/T).", "formula": "Eсв = Δm·c²;  Δm = Z·mp + N·mn − Mя;  1 а. е. м. ↔ 931,5 МэВ", "levels": {"easy": [{"q": "Массовое число A — это…", "o": ["число протонов и нейтронов в ядре", "число электронов", "заряд ядра", "масса атома в граммах"], "a": 0, "e": "A = Z + N."}, {"q": "Что такое изотопы?", "o": ["атомы одного элемента с разным числом нейтронов", "разные элементы с одинаковой массой", "ионы", "молекулы"], "a": 0, "e": "Например, ¹²C и ¹⁴C."}, {"q": "Что такое дефект масс?", "o": ["разность между суммой масс нуклонов и массой ядра", "ошибка взвешивания", "масса электронов", "масса фотона"], "a": 0, "e": "Он соответствует энергии связи."}], "medium": [{"q": "Сколько нейтронов в ядре ²³⁵₉₂U?", "o": ["143", "92", "235", "327"], "a": 0, "e": "N = 235 − 92."}, {"q": "Дефект масс 0,03 а. е. м. Энергия связи?", "o": ["≈ 28 МэВ", "≈ 3 МэВ", "≈ 931 МэВ", "≈ 0,03 МэВ"], "a": 0, "e": "0,03 × 931,5 ≈ 28 МэВ (это примерно для гелия)."}, {"q": "Почему энергия выделяется и при делении урана, и при синтезе водорода?", "o": ["продукты имеют большую удельную энергию связи", "так совпало", "не выделяется", "из-за химических реакций"], "a": 0, "e": "Удельная энергия связи максимальна у средних ядер."}], "hard": [{"q": "Допишите: ²³⁸₉₂U → ²³⁴₉₀Th + ?", "o": ["α-частица ⁴₂He", "β-частица", "нейтрон", "протон"], "a": 0, "e": "A: 238 − 234 = 4; Z: 92 − 90 = 2."}, {"q": "Сколько α- и β-распадов превращают ²³⁸₉₂U в ²⁰⁶₈₂Pb?", "o": ["8 α и 6 β", "6 α и 8 β", "8 α и 8 β", "10 α и 2 β"], "a": 0, "e": "ΔA = 32 → 8 α (Z уменьшится на 16); Z нужно уменьшить на 10 → 6 β⁻ увеличивают на 6."}, {"q": "Что такое удельная энергия связи?", "o": ["энергия связи, приходящаяся на один нуклон", "энергия ядра", "энергия электрона", "масса ядра"], "a": 0, "e": "Eсв / A."}], "olympiad": [{"q": "При делении одного ядра U-235 выделяется ≈ 200 МэВ. Сколько энергии даст деление всех ядер 1 г урана-235 (Nₐ = 6·10²³)?", "o": ["≈ 8·10¹⁰ Дж", "≈ 8·10⁵ Дж", "≈ 2·10⁸ Дж", "≈ 10²⁰ Дж"], "a": 0, "e": "N = 6·10²³/235 ≈ 2,6·10²¹; E = 2,6·10²¹ × 200 × 1,6·10⁻¹³ ≈ 8·10¹⁰ Дж."}, {"q": "Почему ядерные силы не притягивают ядра соседних атомов?", "o": ["ядерные силы действуют только на очень малых расстояниях (~10⁻¹⁵ м)", "они слабые", "они отталкивающие", "атомы заряжены"], "a": 0, "e": "Короткодействие ядерных сил."}, {"q": "Через 3 периода полураспада распадётся какая доля ядер?", "o": ["7/8", "1/8", "3/4", "1/2"], "a": 0, "e": "Останется 1/8, распадётся 7/8."}]}}, {"id": "p11-particles", "title": "Элементарные частицы", "explain": "Элементарные частицы — мельчайшие известные составляющие материи. Протоны и нейтроны состоят из кварков, а электрон считается бесструктурной частицей. У каждой частицы есть античастица (у электрона — позитрон). При встрече частицы и античастицы происходит аннигиляция с превращением в фотоны. Четыре фундаментальных взаимодействия: гравитационное, электромагнитное, сильное и слабое.", "check": true, "levels": {"easy": [{"q": "Античастица электрона?", "o": ["позитрон", "протон", "нейтрон", "фотон"], "a": 0, "e": "Позитрон имеет заряд +e."}, {"q": "Сколько фундаментальных взаимодействий известно?", "o": ["четыре", "два", "одно", "десять"], "a": 0, "e": "Гравитационное, электромагнитное, сильное, слабое."}, {"q": "Из чего состоят протоны и нейтроны?", "o": ["из кварков", "из электронов", "из фотонов", "ни из чего"], "a": 0, "e": "Протон — два u-кварка и один d-кварк."}], "medium": [{"q": "Что такое аннигиляция?", "o": ["превращение частицы и античастицы в другие частицы, например фотоны", "распад ядра", "деление урана", "слияние ядер"], "a": 0, "e": "e⁻ + e⁺ → γ + γ."}, {"q": "Какое взаимодействие удерживает кварки в протоне?", "o": ["сильное", "слабое", "гравитационное", "электромагнитное"], "a": 0, "e": "Сильное взаимодействие переносят глюоны."}, {"q": "Какое взаимодействие отвечает за β-распад?", "o": ["слабое", "сильное", "гравитационное", "магнитное"], "a": 0, "e": "Слабое взаимодействие меняет тип кварков."}], "hard": [{"q": "Минимальная энергия двух фотонов при аннигиляции покоящихся электрона и позитрона (mₑc² ≈ 0,511 МэВ)?", "o": ["≈ 1,02 МэВ суммарно", "≈ 0,511 МэВ суммарно", "≈ 931 МэВ", "0"], "a": 0, "e": "2 × 0,511 МэВ."}, {"q": "Какая частица не имеет массы покоя?", "o": ["фотон", "электрон", "нейтрон", "протон"], "a": 0, "e": "Фотон всегда движется со скоростью света."}, {"q": "Где изучают элементарные частицы?", "o": ["на ускорителях, например Большом адронном коллайдере", "в обычных микроскопах", "в телескопах только", "в химических лабораториях"], "a": 0, "e": "Частицы разгоняют и сталкивают."}], "olympiad": [{"q": "Почему электрон и протон не аннигилируют при встрече?", "o": ["они не являются частицей и античастицей друг для друга", "они одинаковые", "протон тяжелее", "аннигилируют"], "a": 0, "e": "Аннигилируют только частица и её античастица."}, {"q": "Какой заряд у u-кварка?", "o": ["+2/3 e", "+1 e", "−1/3 e", "0"], "a": 0, "e": "u: +2/3, d: −1/3; протон uud: +1."}, {"q": "Какую частицу открыли на БАК в 2012 году?", "o": ["бозон Хиггса", "электрон", "нейтрон", "позитрон"], "a": 0, "e": "Бозон Хиггса связан с механизмом появления масс частиц."}]}}]}, {"title": "Астрофизика", "topics": [{"id": "p11-stars", "title": "Звёзды и эволюция Вселенной", "explain": "Звёзды — огромные газовые шары, в недрах которых идёт термоядерный синтез. Жизнь звезды зависит от её массы: звёзды вроде Солнца в конце становятся красными гигантами и белыми карликами, массивные — взрываются как сверхновые и превращаются в нейтронные звёзды или чёрные дыры. По модели Большого взрыва Вселенная возникла около 13,8 млрд лет назад и расширяется.", "check": true, "levels": {"easy": [{"q": "Источник энергии звёзд?", "o": ["термоядерный синтез", "горение угля", "деление урана", "трение газа"], "a": 0, "e": "Водород превращается в гелий."}, {"q": "Чем станет Солнце в конце жизни?", "o": ["красным гигантом, затем белым карликом", "чёрной дырой", "сверхновой", "планетой"], "a": 0, "e": "У Солнца недостаточно массы для взрыва сверхновой."}, {"q": "Возраст Вселенной по современным данным?", "o": ["около 13,8 млрд лет", "около 4,6 млрд лет", "около 100 млн лет", "бесконечен"], "a": 0, "e": "4,6 млрд лет — возраст Солнечной системы."}], "medium": [{"q": "Что такое сверхновая?", "o": ["мощный взрыв массивной звезды в конце жизни", "новая планета", "рождение звезды", "комета"], "a": 0, "e": "При взрыве образуются тяжёлые элементы."}, {"q": "Что такое нейтронная звезда?", "o": ["сверхплотный остаток массивной звезды", "звезда из нейтронов газа", "молодая звезда", "планета"], "a": 0, "e": "Масса порядка солнечной при радиусе ~10 км."}, {"q": "Что подтверждает теорию Большого взрыва?", "o": ["реликтовое излучение и расширение Вселенной", "форма Земли", "существование Луны", "цвет неба"], "a": 0, "e": "Реликтовое излучение открыто в 1965 году."}], "hard": [{"q": "Почему массивные звёзды живут меньше, чем маленькие?", "o": ["они расходуют водород намного быстрее", "у них меньше водорода", "они холоднее", "живут дольше"], "a": 0, "e": "Светимость растёт с массой очень сильно."}, {"q": "Где образовались атомы тяжелее железа, например золото?", "o": ["при взрывах сверхновых и слияниях нейтронных звёзд", "в обычных звёздах типа Солнца", "на Земле", "при Большом взрыве"], "a": 0, "e": "Синтез в звёздах эффективно идёт до железа."}, {"q": "Что такое световой год?", "o": ["расстояние, которое свет проходит за год", "время", "скорость", "яркость звезды"], "a": 0, "e": "≈ 9,46·10¹⁵ м."}], "olympiad": [{"q": "Галактика удаляется со скоростью 7000 км/с, постоянная Хаббла ≈ 70 км/(с·Мпк). Расстояние?", "o": ["≈ 100 Мпк", "≈ 10 Мпк", "≈ 1000 Мпк", "≈ 490 000 Мпк"], "a": 0, "e": "r = v/H = 7000/70."}, {"q": "Почему ночное небо тёмное, если звёзд бесконечно много (парадокс Ольберса)?", "o": ["Вселенная имеет конечный возраст и расширяется", "звёзды слишком маленькие", "свет поглощает воздух", "звёзд мало"], "a": 0, "e": "Свет от далёких звёзд ещё не дошёл или сильно покраснел."}, {"q": "Что такое горизонт событий чёрной дыры?", "o": ["граница, из-за которой не может выйти даже свет", "поверхность звезды", "граница Солнечной системы", "орбита спутника"], "a": 0, "e": "Радиус Шварцшильда."}]}}]}]}}};
